TURATH_CHUNK(13,[{"num":2600,"demo":false,"sanad":"","matn":["عن أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنْ أَبِيهِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا تَثَاءَبَ أَحَدُكُمْ فِي الصَّلَاةِ فَلْيَكْظِمْ مَا اسْتَطَاعَ، فَإِنَّ الشَّيْطَانَ يَدْخُلُ."],"takhrij":"صحيح: رواه مسلم في الزهد والرقائق (2995/59) عن أبي بكر بن أبي شيبة، حدثنا وكيع، عن سفيان، عن سهل بن أبي صالح، عن ابن أبي سعيد، عن أبيه فذكر مثله.","grade":"صحيح","chapter_ar":"باب كراهية التثاؤب في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (2995).","chapter_en":"The dislikedness of yawning during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Abu Sa‘id al-Khudri said: The Messenger of Allah ﷺ said: “If one of you yawns during prayer, let him restrain it as much as he can, for Shaytan enters.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2995/59)."},{"num":2601,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: كَانَ قِرَامٌ لِعَائِشَةَ سَتَرَتْ بِهِ جَانِبَ بَيْتِهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَمِيطِي عَنَّا قِرَامَكِ هَذَا؛ فَإِنَّهُ لَا تَزَالُ تَصَاوِيرُهُ تَعْرِضُ فِي صَلَاتِي."],"takhrij":"صحيح: رواه البخاري في الصلاة (374) عن أبي معمر عبدالله بن عمرو، حدثنا عبدالوارث، حدثنا عبد العزيز بن صهيب، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الصلاة أمام التصاوير","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (374).","chapter_en":"The dislikedness of praying in front of images (pictures).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":5,"content":{"translation":{"en":["Anas reported: ‘A’ishah had a qirām (a patterned curtain/cloth) with which she covered a side of her house, and the Prophet ﷺ said: “Remove this qirām of yours from us, for its images keep appearing to me during my prayer.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (374)."},{"num":2602,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهى أَنْ يُصَلّي الرَّجُلُ مُخْتَصِرًا، وَفِي رِوَايَةِ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عن الاختصار فِي الصلاة."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1219) من طريق أيوب، عن محمد بن سِيرين، عن أبي هريرة قال: نُهيَ عن الخَصر في الصلاة. وقال هشام (وهو ابن حسان) وأبو هلال (وهو محمد بن سِلم الراسبي) عن ابن سيرين، عن أبي هريرة عن النبيّ صلى الله عليه وسلم .","grade":"متفق عليه","chapter_ar":"باب النهي عن الاختصار في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1219), Muslim (545).","chapter_en":"The prohibition/dislikedness of ikhtisār in prayer (placing the hands on the waist/hips).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ forbade a man from praying while doing ikhtisār (standing with hands on the waist/hips). In another wording: the Messenger of Allah ﷺ forbade ikhtisār in prayer."]},"buhuth":{"en":["Abu Dawud said: meaning that he places his hand on his waist/side."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1219)، ومسلم (545). قال أبو داود: يعني يضع يده على خاصرته."},{"num":2603,"demo":false,"sanad":"","matn":["عَنْ زِيَادِ بْنِ صُبَيْحٍ الْحَنَفِيِّ، قَالَ: صَلَّيْتُ إِلَى جَنْبِ ابْنِ عُمَرَ، فَوَضَعْتُ يَدَىَّ عَلَى خَاصِرَتَىَّ، فَلَمَّا صَلَّى قَالَ: هَذَا الصَّلْبُ فِي الصَّلاَةِ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهُ."],"takhrij":"حسن: رواه أبو داود (903)، والنسائي (892) كلاهما من طريق سعيد ابن زياد، عن زياد بن صُبيح فذكر مثله. واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب النهي عن الاختصار في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (903), al-Nasa’i (892).","chapter_en":"The prohibition/dislikedness of ikhtisār in prayer (placing the hands on the waist/hips).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":6,"content":{"translation":{"en":["Ziyad ibn Subayh al-Hanafi said: I prayed next to Ibn ‘Umar and I placed my hand on my waist. When he finished praying, he said: “This is al-ṣulb in prayer, and the Messenger of Allah ﷺ used to forbid it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (903)، والنسائي (892)."},{"num":2604,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ الاِلْتِفَاتِ فِي الصَّلاَةِ فَقَالَ: هُوَ اخْتِلاَسٌ يَخْتَلِسُهُ الشَّيْطَانُ مِنْ صَلاَةِ الْعَبْدِ."],"takhrij":"صحيح: رواه البخاري في الأذان (751) عن مسدد، قال: حدثنا أبو الأحوص قال: حدثنا أشعث بن سُليم، عن أبيه، عن مسروق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب كراهية الالتفات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (751).","chapter_en":"The dislikedness of turning/looking around (iltifāt) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":7,"content":{"translation":{"en":["‘A’ishah said: I asked the Messenger of Allah ﷺ about turning (looking around) during prayer. He said: “It is a snatching that Shaytan snatches away from the prayer of the servant.”"]},"buhuth":{"en":["The word ikhtilās means: a quick snatching/stealing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (751). وقوله: اختلاس: أي: اختطاف بسرعة."},{"num":2605,"demo":false,"sanad":"","matn":["عن الحارث الأشعري أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَالَ: ...في حديث طويل...","وَإِنَّ اللَّهَ أَمَرَكُمْ بِالصَّلَاةِ فَإِذَا صَلَّيْتُمْ فَلَا تَلْتَفِتُوا ، فَإِنَّ اللَّهَ يَنْصِبُ وَجْهَهُ لِوَجْهِ عَبْدِهِ فِي صَلَاتِهِ مَا لَمْ يَلْتَفِتْ."],"takhrij":"صحيح: رواه الترمذي (2864) عن محمد بن إسماعيل، حدثنا موسى بن إسماعيل، وعن محمد بن بَشَّار، حدثنا أبو داود الطيالسي، كلاهما عن أبان بن يزيد، حدثنا يحيى بن أبي كثير، عن زيد بن سلام، أن أبا سَلاَّم حدَّثه أن الحارث الأشعري حدثه فذكر مثله في حديث طويل سيأتي في الأمثال.","grade":"صحيح","chapter_ar":"باب كراهية الالتفات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Tirmidhi (2864), Abu Dawud al-Tayalisi (1257), and Ibn Khuzaymah (483, 930) graded it authentic.","chapter_en":"The dislikedness of turning/looking around (iltifāt) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":7,"content":{"translation":{"en":["Al-Harith al-Ash‘ari reported that the Prophet ﷺ said in a long hadith: “Allah has commanded you to pray, so when you pray do not turn (look around), for Allah sets His Face toward the face of His servant in his prayer so long as he does not turn away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2864)، وأبو داود الطيالسي (1257)، وصححه ابن خزيمة (483،930)."},{"num":2606,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَزَالُ اللَّهُ عزَّ وجلَّ مُقْبِلاً عَلَى الْعَبْدِ وَهُوَ فِي صَلاَتِهِ مَا لَمْ يلتفِتْ فَإِذَا الْتَفَتَ انْصَرَفَ عَنْهُ ."],"takhrij":"حسن: رواه أبو داود (909)، والنسائي (1195) كلاهما عن يونس، عن الزهري، قال: سمعتُ أبا الأحوص يحدثنا في مجلس سعيد بن المسيب، وابن المسيب جالس أنه سمع أبا ذر يقول: فذكره.","grade":"حسن","chapter_ar":"باب كراهية الالتفات في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (909), al-Nasa’i (1195). Ibn Khuzaymah (481–482) and al-Hakim (1/236) authenticated it.","chapter_en":"The dislikedness of turning/looking around (iltifāt) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":7,"content":{"translation":{"en":["Abu Dharr reported that the Prophet ﷺ said: “Allah, Mighty and Majestic, continues facing the servant while he is in his prayer as long as he does not turn away; but when he turns away, He turns away from him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (909)، والنسائي (1195)، وصححه ابن خزيمة (481،482) والحاكم (1/236)."},{"num":2607,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي خَمِيصَةٍ لَهَا أَعْلاَمٌ فَقَالَ: شَغَلَتْنِي أَعْلاَمُ هَذِهِ، اذْهَبُوا بِهَا إِلَى أَبِي جَهْمٍ، وَأْتُونِي بِأَنْبِجَانِيَّةٍ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (752)، ومسلم في المساجد (556) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن عروة، عن عائشة فذكرته. انظر للمزيد: جموع أبواب ما يصلى فيه.","grade":"متفق عليه","chapter_ar":"باب الرخصة في الالتفات في الصلاة لحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (752), Muslim (556).","chapter_en":"The concession to turn/look around in prayer due to a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":8,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ prayed in a khamisah (a garment) that had markings, and he said: “Its markings distracted me. Take it to Abu Jahm and bring me an anbijaniyyah (a plain cloak).”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (752)، ومسلم (556)."},{"num":2608,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ، وَأَبُو بَكْرٍ يُسْمِعُ النَّاسَ تَكْبِيرَهُ. فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا، فَأَشَارَ إِلَيْنَا فَقَعَدْنَا، فَصَلَّيْنَا بِصَلَاتِهِ قُعُودًا. فَلَمَّا سَلَّمَ قَالَ: إِنْ كِدْتُمْ آنِفًا لَتَفْعَلُونَ فِعْلَ فَارِسَ وَالرُّومِ، يَقُومُونَ عَلَى مُلُوكِهِمْ، وَهُمْ قُعُودٌ. فَلَا تَفْعَلُوا، ائْتَمُّوا بِأَئِمَّتِكُمْ. إِنْ صَلَّى قَائِمًا فَصَلُّوا قِيَامًا، وَإِنْ صَلَّى قَاعِدًا فَصَلُّوا قُعُودًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (413) من طرق عن الليث بن سعد، عن أبي الزبير، عن جابر فذكر مثله.","grade":"صحيح","chapter_ar":"باب الرخصة في الالتفات في الصلاة لحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (413).","chapter_en":"The concession to turn/look around in prayer due to a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":8,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ fell ill, so we prayed behind him while he was seated, and Abu Bakr was making the people hear his takbīr. The Prophet ﷺ turned toward us and saw us standing, so he gestured to us and we sat. We prayed seated following his prayer. When he gave the taslim he said: “You almost just now did what the Persians and Romans do: they stand over their kings while the kings are sitting. Do not do that. Follow your imams: if he prays standing then pray standing, and if he prays sitting then pray sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1231,2283,13937],"tks":"صحيح: رواه مسلم (413)."},{"num":2609,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَلْحَظُ فِي الصَّلاَةِ يَمِينًا وَشِمَالاً، وَلاَ يَلْوِي عُنُقَهُ خَلْفَ ظَهْرِهِ."],"takhrij":"صحيح: رواه الترمذي (587)، والنسائي (1201) كلاهما من طريق الفضل بن موسى، عن عبدالله بن سعيد بن أبي هند، عن ثور بن زيد، عن عكرمة، عن ابن عباس فذكر مثله. واللفظ للترمذي.","grade":"صحيح","chapter_ar":"باب الرخصة في الالتفات في الصلاة لحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Tirmidhi (587) (wording his), al-Nasa’i (1201).","chapter_en":"The concession to turn/look around in prayer due to a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: The Messenger of Allah ﷺ would glance to his right and left during prayer, but he would not turn his neck behind his back."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (587)، والنسائي (1201). واللفظ للترمذي."},{"num":2610,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ ابْنِ الْحَنْظَلِيَّةِ، قَالَ: ثُوِّبَ بِالصَّلاَةِ - يَعْنِي صَلاَةَ الصُّبْحِ، - فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَهُوَ يَلْتَفِتُ إِلَى الشِّعْبِ."],"takhrij":"صحيح: رواه أبو داود (916) عن الربيع بن نافع، حدثنا معاوية -يعني ابن سلاَّم، عن زيد، أنه سمع أبا سلاَّم قال: حدثني السَّلُوليُّ -وهو أبو كبشة- عن سهل ابن الحنظلية فذكره.","grade":"صحيح","chapter_ar":"باب الرخصة في الالتفات في الصلاة لحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nAbu Dawud (916). Ibn Khuzaymah (487) and al-Hakim (1/237) authenticated it.","chapter_en":"The concession to turn/look around in prayer due to a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":8,"content":{"translation":{"en":["Sahl ibn al-Hanzaliyyah said: The iqāmah was called for prayer—meaning the Fajr prayer—then the Messenger of Allah ﷺ began praying while turning his attention toward the mountain pass (the shi‘b)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (916)، وصححه ابن خزيمة (487)، والحاكم (1/237)."},{"num":2611,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ حَدَّثَهُمْ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَالُ أَقْوَامٍ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي صَلاَتِهِمْ. فَاشْتَدَّ قَوْلُهُ فِي ذَلِكَ حَتَّى قَالَ: لَيَنْتَهُنَّ عَنْ ذَلِكَ، أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ."],"takhrij":"صحيح: رواه البخاريّ في الأذان (750) عن علي بن عبدالله قال: أخبرنا يحيى بن سعيد، قال: حدثنا ابن أبي عروبة، قال: حدثنا قتادة، أن أنس ابن مالك حدثهم فذكر مثله.","grade":"صحيح","chapter_ar":"باب كراهية رفع البصر إلى السماء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nal-Bukhari (750).","chapter_en":"The dislikedness of raising one’s gaze to the sky during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik reported: The Prophet ﷺ said: “What is the matter with people who raise their eyes to the sky during their prayer?” Then he became very stern about it until he said: “They must stop doing that, or their eyesight will be snatched away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (750)."},{"num":2612,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَيَنْتَهِيَنَّ أَقْوَامٌ عَنْ رَفْعِهِمْ أَبْصَارَهُمْ عِنْدَ الدُّعَاءِ فِي الصَّلَاةِ إِلَى السَّمَاءِ، أَوْ لَتُخْطَفَنَّ أَبْصَارُهُمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (429) من حديث ابن وهب، حدثني الليث ابن سعد، عن جعفر بن ربيعة، عن عبدالرحمن بن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهية رفع البصر إلى السماء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (429).","chapter_en":"The dislikedness of raising one’s gaze to the sky during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":9,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “People must stop raising their eyes to the sky when supplicating during prayer, or their eyesight will be snatched away.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (429)."},{"num":2613,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَيَنْتَهِيَنَّ أَقْوَامٌ يَرْفَعُونَ أَبْصَارَهُمْ إِلَى السَّمَاءِ فِي الصَّلَاةِ. أَوْ لَا تَرْجِعُ إِلَيْهِمْ."],"takhrij":"صحيح: رواه مسلم في الصلاة (428) من رواية الأعمش، عن المسيب، عن تميم بن طرفة، عن جابر بن سمرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب كراهية رفع البصر إلى السماء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (428).","chapter_en":"The dislikedness of raising one’s gaze to the sky during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn Samurah reported: The Messenger of Allah ﷺ said: “People must stop raising their eyes to the sky in prayer, or (their eyes) will not return to them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (428)."},{"num":2614,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَرْفَعُوا أَبْصَارَكُمْ إِلَى السَّمَاءِ أَنْ تَلْتَمِعَ. يَعْنِي فِي الصَّلاَةِ."],"takhrij":"حسن: روه ابن ماجه (1043) عن عثمان بن أبي شيبة، حدثنا طلحةُ ابن يحيى، عن يونس بن يزيد الأيلي، عن الزهري، عن سالم، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب كراهية رفع البصر إلى السماء في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (1043). Also authenticated by Ibn Hibban (2281) and al-Tabarani in al-Kabir (13139).","chapter_en":"The dislikedness of raising one’s gaze to the sky during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported: The Messenger of Allah ﷺ said: “Do not raise your eyes to the sky lest they be tultama‘a (snatched away)”—meaning in prayer."]},"buhuth":{"en":["“Tultama‘a” means “to be snatched/quickly taken away.” It is said: “we iltama‘na the people,” meaning: we took them away. From this is also said: “his color iltama‘a” when it vanished."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1043)، وصححه أيضا ابن حبان (2281) والطبراني في الكبير (13139)."},{"num":2615,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّهُ رَأَى عبدالله بْنَ الْحَارِثِ يُصَلِّي وَرَأْسُهُ مَعْقُوصٌ مِنْ وَرَائِهِ. فَقَامَ فَجَعَلَ يحلُّه. فَلَمَّا انْصَرَفَ أَقْبَلَ إِلَى ابْنِ عَبَّاسٍ. فَقَالَ: مالك وَرَأْسِي؟ فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا مثلُ هَذَا مثلُ الَّذِي يُصَلِّي وَهُوَ مَكْتُوفٌ ."],"takhrij":"صحيح: رواه مسلم في الصلاة (492) عن عمرو بن سوَّاد العامِري، أخبرنا عبدالله بن وهب، أخبرنا عمرو بن الحارث، أن بُكيراً حدَّثه، أن كُرَيباً مولى ابن عباس حدَّثه عن عبدالله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب نهي الرجل عن الصلاة، ورأسه معقوص","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim, in the Book of Prayer (492).","chapter_en":"The prohibition of praying while one’s hair is tied up (bound).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":10,"content":{"translation":{"en":["Ibn ‘Abbas saw ‘Abdullah ibn al-Harith praying while his hair was tied/bound behind him. He got up and began undoing it. When he finished, he turned to Ibn ‘Abbas and said: “What do you have against my hair?” Ibn ‘Abbas replied: “I heard the Messenger of Allah ﷺ say: ‘The example of this is like the one who prays while he is bound (hands tied).’”"]},"buhuth":{"en":["“Ma‘qūṣ (معقوص)” here carries the meaning of “maktūf (مكتوف)”—i.e., bound—because it is gathering the hair at the middle/back of the head, and it also resembles the action of women.","Ibn al-Athir said in al-Nihayah (3/275): The meaning of Ibn ‘Abbas’s hadith is that if the hair is left loose it falls to the ground in sujūd, and its owner receives the reward of prostrating with it; but if it is tied up, it is as though it did not prostrate. He likened it to someone bound, whose hands do not fall on the ground in sujūd."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (492)."},{"num":2616,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْمَقْبُرِيِّ أَنَّهُ رَأَى أَبَا رَافِعٍ مَوْلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَرَّ بِحَسَنِ بْنِ عَلِيٍّ وَهُوَ يُصَلِّي قَائِمًا، وَقَدْ غَرَزَ ضُفُرَهُ فِي قَفَاهُ. فحلَّها أَبُو رَافِعٍ. فَالْتَفَتَ حَسَنٌ إِلَيْهِ مُغْضَبًا فَقَالَ أَبُو رَافِعٍ: أَقْبِلْ عَلَى صَلاَتِكَ وَلاَ تَغْضَبْ؛ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: ذَلِكَ كفْل الشَّيْطَانِ يَعْنِي مَقْعَدَ الشَّيْطَانِ يَعْنِي: مَغْرِزَ ضُفُرِهِ."],"takhrij":"حسن: رواه أبو داود (646)، والترمذي (384) كلاهما من طريق عبد الرزاق - وهو في مصنفه (2991) عن ابن جريج، قال: حدثني عمران بن موسى، عن سعيد بن أبي سعيد المقبري، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب نهي الرجل عن الصلاة، ورأسه معقوص","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (646), al-Tirmidhi (384) (he graded it hasan), and ‘Abd al-Razzaq (2991).","chapter_en":"The prohibition of praying while one’s hair is tied up (bound).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":10,"content":{"translation":{"en":["Abu Sa‘id al-Maqburi saw Abu Rafi‘ (the freedman of the Prophet ﷺ) pass by al-Hasan ibn ‘Ali while he was praying standing, and he had fastened his braids at the back of his head (at the nape). Abu Rafi‘ undid them. Al-Hasan turned to him angrily, so Abu Rafi‘ said: “Focus on your prayer and don’t be angry, for I heard the Messenger of Allah ﷺ say: ‘That is the seat/portion of Shaytan,’” meaning: Shaytan’s sitting place—meaning where the braids are fastened."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (646)، والترمذي (384) وحسنه، وعبد الرزاق (2991)."},{"num":2617,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُصَلِّيَ الرَّجُلُ وَرَأَسُهُ مَعْقُوصٌ."],"takhrij":"حسن: رواه الطبراني في الكبير (23/ح 512) عن علي بن عبد العزيز، ثنا أبو حذيفة، ثنا سفيان، عن مخول بن راشد، عن سعيد المقبري، عن أبي رافع، عن أم سلمة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب نهي الرجل عن الصلاة، ورأسه معقوص","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (23/252).","chapter_en":"The prohibition of praying while one’s hair is tied up (bound).","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":10,"content":{"translation":{"en":["Umm Salamah reported that the Prophet ﷺ forbade a man from praying while his hair is tied up (bound)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (23/ح 512)."},{"num":2618,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى بُصَاقًا فِي جِدَارِ الْقِبْلَةِ، فحكَّه ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: إِذَا كَانَ أَحَدُكُمْ يُصَلِّي فَلَا يَبْصُقْ قِبَلَ وَجْهِهِ، فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قِبَل وَجْهِهِ إِذَا صَلَّى ."],"takhrij":"متفق عليه: رواه مالك في القبلة (4) عن نافع، عن ابن عمر فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب النهي عن البصاق في القبلة في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (4), al-Bukhari in al-Salah (406), and Muslim (547).","chapter_en":"The prohibition of spitting toward the qiblah during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":11,"content":{"translation":{"en":["Ibn ‘Umar reported: The Messenger of Allah ﷺ saw some spittle on the qiblah wall, so he scraped it off. Then he turned to the people and said: “When one of you is praying, let him not spit in front of his face, for Allah—Blessed and Exalted—is in front of his face when he prays.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4) والبخاري (406)، ومسلم (547)."},{"num":2619,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: أَمَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا يُصَلِّي بِالنَّاسِ الظُّهْرَ، فَتَفَلَ فِي الْقِبْلَةِ وَهُوَ يُصَلِّي لِلنَّاسِ. فَلَمَّا كَانَتْ صَلَاةُ الْعَصْرِ، أَرْسَلَ إِلَى آخَرَ، فَأَشْفَقَ الرَّجُلُ الْأَوَّلُ، فَجَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! أَنَزَلَ فِيَّ؟ قَالَ: لَا، وَلَكِنَّكَ تَفِلْتَ بَيْنَ يَدَيْكَ، وَأَنْتَ تَؤُمُّ النَّاسَ فَآذَيْتَ اللَّهَ وَالْمَلَائِكَةَ."],"takhrij":"حسن: رواه الطبراني في الكبير (13/ح 104) وبقي بن مخلد كما في بيان الوهم والإيهام (5/282) كلاهما من طريق عبد الله بن وهب، حدثني حيي بن عبدالله، عن أبي عبد الرحمن (واسمه: عبد الله بن يزيد المعافري)، عن عبد الله بن عمرو، فذكره.","grade":"حسن","chapter_ar":"باب النهي عن البصاق في القبلة في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nal-Tabarani in al-Kabir (13/80–81); and Baqi ibn Makhlad as cited in Bayān al-Wahm wa’l-Īhām (5/282).","chapter_en":"The prohibition of spitting toward the qiblah during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":11,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr reported: The Messenger of Allah ﷺ ordered a man to lead the people in the noon (ẓuhr) prayer, and he spat toward the qiblah while leading them in prayer. When it was time for the afternoon (‘aṣr) prayer, he sent someone else to lead. The first man became afraid, so he came to the Prophet ﷺ and said: “O Messenger of Allah! Has something been revealed about me?” He replied: “No—rather, you spat in front of you while you were leading the people, so you harmed (offended) Allah and His angels.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (13/ح 104) وبقي بن مخلد كما في بيان الوهم والإيهام (5/282)."},{"num":2620,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُغَطِّيَ الرَّجُلُ فَاهُ فِي الصَّلاَةِ."],"takhrij":"حسن: رواه ابن ماجه (966) عن أبي سعيد سفيان بن زياد المؤدِّب، قال: حدثنا محمد بن راشد، عن الحسن بن ذكوان، عن عطاء، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب كراهية تغطية الرجل فاه في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nIbn Majah (966).","chapter_en":"The dislikedness of a man covering his mouth in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":12,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ forbade a man from covering his mouth in prayer."]},"buhuth":{"en":["And Abu Dawud (643) also narrated that the Prophet ﷺ “forbade as-sadl in prayer, and that a man cover his mouth.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (966)."},{"num":2621,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي قَبْلَ أَنْ يُبْنَى الْمَسْجِدُ فِي مَرابِض الْغَنَمِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوءِ (234) وفي الصلاة (429)، ومسلم في المساجد (524/10) كلاهما من حديث شعبة، حدَّثني أبو التيَّاح، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية الصلاة في معاطن الإبل وجوازها في مرابض الغنم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (234, 429) and Muslim (524).","chapter_en":"The dislikedness of praying in camel resting-places, and the permissibility of praying in sheep pens.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":13,"content":{"translation":{"en":["Anas reported: The Prophet ﷺ used to pray—before the mosque was built—in the sheep pens."]},"buhuth":{"en":["“Marābiḍ” is the plural of “marbiḍ,” the place where animals settle/rest. For sheep it is like a human lying down; for camels it is like kneeling down; and for birds it is like crouching. (Mentioned by al-Nawawi.)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (429 ،234)، ومسلم (524/10)."},{"num":2622,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ ، أَنَّ رَجُلًا ، سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.... قَالَ : أُصَلِّي فِي مَرَابِضِ الْغَنَمِ؟ ؟ قَالَ: : نَعَمْ ، قَالَ : أُصَلِّي فِي مَبَارِكِ الإِبِلِ؟ ؟ قَالَ : لَا."],"takhrij":"صحيح: رواه مسلم في الوضوء (360) عن أبي كامل فُضيل بن حسين، الجحدري، حدثنا أبو عوانة، عن عثمان بن عبدالله بن موْهَب، عن جعفر بن أبي ثور، عن جابر بن سمرة في حديث سبق تخريجه في الطهارة باب نقض الوضوء من لحوم الإبل.","grade":"صحيح","chapter_ar":"باب كراهية الصلاة في معاطن الإبل وجوازها في مرابض الغنم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih\nMuslim (360).","chapter_en":"The dislikedness of praying in camel resting-places, and the permissibility of praying in sheep pens.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Samurah reported that a man asked the Prophet ﷺ: “May I pray in the sheep pens?” He said: “Yes.” He asked: “May I pray in the places where camels kneel?” He said: “No.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (360)."},{"num":2623,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ بْنِ عَازِبٍ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عن الصَّلاَةِ فِي مَبَارِكِ الإِبِلِ فَقَالَ: لاَ تُصَلُّوا فِي مَبَارِكِ الإِبِلِ، فإنَّها مِنَ الشَّيَاطِينِ وَسُئِلَ عَنِ الصَّلاَةِ فِي مرابِضِ الْغَنَمِ فَقَالَ: صلَّوا فِيهَا فَإِنَّهَا بَرَكَةٌ .","وفي لفظ: لا تصلوا في عطن الإبل فإنها من الشيطان ."],"takhrij":"حسن: رواه أبو داود (184،493)، والترمذي (81)، وابن ماجه (494) كلّهم من حديث أبي معاوية، ثنا الأعمش، عن عبدالله بن عبدالله الرازي، عن عبدالرحمن بن أبي ليلى، عن البراء إلا أن ابن ماجه لم يذكر قصة الصلاة في مرابض الغنم والإبل.","grade":"حسن","chapter_ar":"باب كراهية الصلاة في معاطن الإبل وجوازها في مرابض الغنم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan\nAbu Dawud (184, 493), al-Tirmidhi (81), Ibn Majah (494).","chapter_en":"The dislikedness of praying in camel resting-places, and the permissibility of praying in sheep pens.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":13,"content":{"translation":{"en":["Al-Bara’ ibn ‘Azib reported: The Messenger of Allah ﷺ was asked about praying in the places where camels rest/kneel, and he said: “Do not pray in the places where camels rest, for they are from the devils.” And he was asked about praying in the sheep pens, so he said: “Pray in them, for they are a blessing.” In another wording: “Do not pray in the camel ‘aṭan (watering/resting place), for it is from Shaytan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (184،493)، والترمذي (81)، وابن ماجه (494)."},{"num":2624,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنْ لَمْ تَجِدُوا إِلاَّ مَرَابِضَ الْغَنَمِ وَأَعْطَانَ الإِبِلِ، فَصَلُّوا فِي مَرَابِضِ الْغَنَمِ، وَلاَ تُصَلُّوا فِي أَعْطَانِ الإِبِلِ."],"takhrij":"صحيح: رواه الترمذي (348)، وابن ماجه (768) كلاهما من طريق هشام بن حسان، عن محمد بن سِيرين، عن أبي هريرة. واللفظ لابن ماجه.","grade":"صحيح","chapter_ar":"باب كراهية الصلاة في معاطن الإبل وجوازها في مرابض الغنم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Tirmidhi (348), Ibn Majah (768). Ibn Khuzaymah authenticated it (795) and said: “Hasan Sahih.”","chapter_en":"The dislikedness of praying in camel resting-places, and the permissibility of praying in sheep pens.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ said: “If you find nothing except sheep pens and the camel watering/resting places, then pray in the sheep pens, and do not pray in the camel watering/resting places.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (348)، وابن ماجه (768) وصححه ابن خزيمة (795)، وقال: حسن صحيح."},{"num":2625,"demo":false,"sanad":"","matn":["عَنْ سَبْرَةَ بن مَعْبَدٍ الجهني أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يُصَلَّى فِي أَعْطَانِ الإِبِلِ، ويُصلَّى فِي مُرَاحِ الْغَنَمِ ."],"takhrij":"حسن: رواه ابن ماجه (770) عن أبي بكر بن أبي شيبة وهو في مصنفه (1/385) عن زيد بن الحُباب، قال: حدثنا عبد الملك بن ربيع بن سَبْرَة بن معبد الجهني، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب كراهية الصلاة في معاطن الإبل وجوازها في مرابض الغنم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nIbn Majah (770), Abu Bakr ibn Abi Shaybah (1/385), Ahmad (15341).","chapter_en":"The dislikedness of praying in camel resting-places, and the permissibility of praying in sheep pens.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":13,"content":{"translation":{"en":["Sabrah ibn Ma‘bad al-Juhani reported that the Messenger of Allah ﷺ said: “Do not pray in the camel watering/resting places, but do pray in the sheep enclosure.”"]},"buhuth":{"en":["“‘Aṭan al-ibil (عطن الإبل)” means the camel kneeling/resting place; it is said: “the camels ‘aṭanat” when they kneel at water after drinking.","Ibn al-Athir said in Jāmi‘ al-Uṣūl (5/470): “The a‘ṭān of camels are their kneeling places around water where they return to drink again after having already drunk. The reason for forbidding prayer in camel a‘ṭān is not because of impurity—since impurity is also found in sheep pens—but because camels can push and jostle at the watering place, and when they drink they lift their heads; their scattering and sudden bolting in that place is not safe, so a person praying near them may be harmed.”","And al-murāḥ is the place where sheep spend the night.","Al-Baghawi said: “The prohibition of praying in camel a‘ṭān is due to their tendency to bolt; it is not safe that they might bolt and distract the praying person’s heart or ruin his prayer. If he prays and the place is pure, the prayer is valid according to most scholars.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه ( 770) وأبو بكر بن أبي شيبة (1/385). والإمام أحمد (15341 )."},{"num":2626,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَرْثَدٍ الْغَنَوِيِّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  لَا تُصَلُّوا إِلَى الْقُبُورِ، وَلَا تَجْلِسُوا عَلَيْهَا."],"takhrij":"صحيح: رواه مسلم في الجنائز (972) من طريق واثلة بن الأَسْقع، عن أبي مرثد فذكر مثله.","grade":"صحيح","chapter_ar":"باب المواضع التي نهي عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (972).","chapter_en":"Places in which prayer has been forbidden.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":14,"content":{"translation":{"en":["Abu Marthad al-Ghanawi said: I heard the Messenger of Allah ﷺ say: “Do not pray facing graves, and do not sit on them.”"]},"buhuth":{"en":["The scholars said: prayer is disliked (makruh) when directed toward graves, on graves, and between graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (972)."},{"num":2627,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الأَرْضُ كُلُّهَا مَسْجِدٌ إِلاَّ الْمَقْبَرَةَ وَالْحَمَّامَ."],"takhrij":"صحيح: رواه أبو داود (492)، وابن ماجه (745) كلاهما من طريق حماد بن سلمة، عن عمرو بن يحيى بن عمارة، عن أبيه، عن أبي سعيد الخدري فذكر الحديث.","grade":"صحيح","chapter_ar":"باب المواضع التي نهي عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (492), Ibn Majah (745).","chapter_en":"Places in which prayer has been forbidden.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":14,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported: The Messenger of Allah ﷺ said: “The whole earth is a place of prayer except the bathhouse and the graveyard.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (492)، وابن ماجه (745)."},{"num":2628,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُصلَّى بَيْنَ الْقُبُورِ."],"takhrij":"صحيح: رواه ابن حبان (1698،2315،2318)، وأبو يعلى (2888) والبزار - كشف الأستار (442)، من حفص بن غياث، عن أشعث، عن الحسن، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب المواضع التي نهي عن الصلاة فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nIbn Hibban (1698, 2315, 2318), Abu Ya‘la (2888), al-Bazzar (Kashf al-Astar 442).","chapter_en":"Places in which prayer has been forbidden.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب ما يحرم وما يكره في الصلاة","group_en":"A collection of chapters on what is prohibited and what is disliked in prayer.","part_no":9,"group_no":14,"chapter_no":14,"content":{"translation":{"en":["Anas ibn Malik reported: The Messenger of Allah ﷺ forbade praying between graves."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن حبان (1698،2315،2318)، وأبو يعلى (2888) والبزار - كشف الأستار (442)."},{"num":2629,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ الأَنْصَارِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي وَهْوَ حَامِلٌ أُمَامَةَ بِنْتَ زَيْنَبَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلأَبِي الْعَاصِ بْنِ رَبِيعَةَ، بْنِ عَبْدِ شَمْسٍ، فَإِذَا سَجَدَ وَضَعَهَا، وَإِذَا قَامَ حَمَلَهَا."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة في السفر (81) عن عامر بن عبدالله بن الزبير، عن عمرو بن سُلَيم الزرقيّ، عن أبي قتادة الأنصاري فذكره.","grade":"متفق عليه","chapter_ar":"باب حمل الصبيان في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (81) and al-Bukhari (516). Muslim (543) also narrated it and in his wording: The Messenger of Allah ﷺ came out to us with Umamah bint Abu al-‘As on his shoulder; he prayed, and when he bowed he put her down, and when he rose he lifted her. In it is an indication that this occurred in congregational prayer.","chapter_en":"Carrying small children during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":1,"content":{"translation":{"en":["Abu Qatadah al-Ansari reported that the Messenger of Allah ﷺ used to pray while carrying Umamah bint Zaynab (the daughter of the Messenger of Allah ﷺ) and (she was) the daughter of Abu al-‘As ibn Rabi‘ah ibn ‘Abd Shams. When he prostrated, he would put her down; and when he stood, he would carry her."]},"buhuth":{"en":["And it is explicitly stated in a narration of Muslim: Abu Qatadah said: “I saw the Prophet ﷺ leading the people, with Umamah bint Abu al-‘As on his shoulder.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14085],"tks":"متفق عليه: رواه مالك (81) والبخاري (516)، ورواه مسلم (543) وفيه: خرج علينا رسول الله ﷺ وأمامة بنت أبي العاص على عاتقه، فصلى، فإذا ركع وضع، وإذا رفع رفعها، وفيه إشارة إلى أن ذلك في صلاة الجماعة."},{"num":2630,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ شَدَّادٍ، عَنْ أَبِيهِ، قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِحْدَى صَلاَتَىِ الْعِشَاءِ، وَهُوَ حَامِلٌ حَسَنًا أَوْ حُسَيْنًا، فَتَقَدَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَهُ، ثُمَّ كَبَّرَ لِلصَّلاَةِ فَصَلَّى، فَسَجَدَ بَيْنَ ظَهْرَانَىْ صَلاَتِهِ سَجْدَةً أَطَالَهَا. قَالَ أَبِي: فَرَفَعْتُ رَأْسِي، وَإِذَا الصَّبِيُّ عَلَى ظَهْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ سَاجِدٌ، فَرَجَعْتُ إِلَى سُجُودِي، فَلَمَّا قَضَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصَّلاَةَ، قَالَ النَّاسُ: يَا رَسُولَ اللَّهِ! إِنَّكَ سَجَدْتَ بَيْنَ ظَهْرَانَىْ صَلاَتِكَ سَجْدَةً أَطَلْتَهَا حَتَّى ظَنَنَّا أَنَّهُ قَدْ حَدَثَ أَمْرٌ، أَوْ أَنَّهُ يُوحَى إِلَيْكَ. قَالَ: كُلُّ ذَلِكَ لَمْ يَكُنْ، وَلَكِنَّ ابْنِي ارْتَحَلَنِي، فَكَرِهْتُ أَنْ أُعَجِّلَهُ حَتَّى يَقْضِيَ حَاجَتَهُ."],"takhrij":"صحيح: رواه النسائي (1141) قال: أخبرنا عبدالرحمن بن محمد بن سلام، قال: حدثنا يزيد بن هارون قال: حدثنا جرير بن حازم، قال: حدثنا محمد بن أبي يعقوب البصري، عن عبدالله بن شداد، عن أبيه فذكر الحديث.","grade":"صحيح","chapter_ar":"باب حمل الصبيان في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1141); authenticated by al-Hakim (3/165–166).","chapter_en":"Carrying small children during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":1,"content":{"translation":{"en":["‘Abdullah ibn Shaddad, from his father, reported: The Messenger of Allah ﷺ came out to us for one of the night prayers (‘isha’), carrying Hasan or Husayn. The Prophet ﷺ stepped forward and put him down, then said ‘Allāhu akbar’ for the prayer and prayed. During his prayer he made a prostration that he lengthened. My father said: I raised my head and saw the child on the back of the Messenger of Allah ﷺ while he was prostrating, so I returned to my prostration. When the Messenger of Allah ﷺ finished the prayer, the people said: “O Messenger of Allah! You prostrated during your prayer with a prostration you lengthened, until we thought something had happened or revelation was coming to you.” He said: “None of that happened. Rather, my son climbed onto me, and I disliked to hurry him until he fulfilled his need.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1141) وصححه الحاكم (4775)."},{"num":2631,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كُنَّا نُصَلِّي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، فَإِذَا سَجَدَ وَثَبَ الْحَسَنُ وَالْحُسَيْنُ عَلَى ظَهْرِهِ، فَإِذَا رَفَعَ رَأْسَهُ، أَخَذَهُمَا بِيَدِهِ مِنْ خَلْفِهِ أَخْذًا رَفِيقًا، فَيَضَعُهُمَا عَلَى الْأَرْضِ، فَإِذَا عَادَ عَادَا، حَتَّى قَضَى صَلَاتَهُ، أَقْعَدَهُمَا عَلَى فَخِذَيْهِ، قَالَ: فَقُمْتُ إِلَيْهِ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَرُدُّهُمَا، فَبَرَقَتْ بَرْقَةٌ، فَقَالَ لَهُمَا: الْحَقَا بِأُمِّكُمَا. قَالَ: فَمَكَثَ ضَوْؤُهَا حَتَّى دَخَلَا."],"takhrij":"حسن: أخرجه الإمام أحمد في مسنده (10659) وفي فضائل الصحابة (1401)، والطبراني في الكبير (3/45) والبزار - كشف الأستار (2630) كلهم من طريق كامل أبي العلاء، عن أبي صالح، عن أبي هريرة فذكر مثله إلا أن البزار ذكره مختصراً ولم يذكر موضع الشاهد.","grade":"حسن","chapter_ar":"باب حمل الصبيان في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (10659); al-Tabarani in al-Kabir (3/45); al-Bazzar (Kashf al-Astar 2630).","chapter_en":"Carrying small children during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah reported: We used to pray ‘isha’ with the Messenger of Allah ﷺ. When he prostrated, Hasan and Husayn would jump onto his back. When he raised his head, he would take them gently with his hand from behind him and place them on the ground. When he returned to prostration they returned (again), until he completed his prayer; then he seated them on his thighs. He said: I stood up to him and said: “O Messenger of Allah ﷺ, shall I take them back?” Then a flash of lightning appeared, and he said to them: “Go to your mother.” He said: its light remained until they entered."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه الإمام أحمد (10659)، والطبراني في الكبير (3/45) والبزار - كشف الأستار (2630)."},{"num":2632,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اقْتُلُوا الأَسْوَدَيْنِ فِي الصَّلاَةِ: الْحَيَّةَ وَالْعَقْرَبَ."],"takhrij":"صحيح: رواه أبو داود (921)، والترمذي (390)، والنسائي (1202)، وابن ماجة (1245) كلهم من طرق عن يحيى بن أبي كثير، عن ضمضم بن جَوْسٍ، عن أبي هريرة فذكر مثله. واللّفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب في قتل الحيّة والعقرب في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (921), al-Tirmidhi (390), al-Nasa’i (1202), Ibn Majah (1245).","chapter_en":"Killing the snake and scorpion during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":2,"content":{"translation":{"en":["Abu Hurayrah reported: The Messenger of Allah ﷺ said: “Kill the two black creatures during prayer: the snake and the scorpion.”"]},"buhuth":{"en":["The meaning of the hadith is that killing these two— the snake and the scorpion—during prayer does not invalidate the prayer, because killing them is obligatory. After finishing killing them, the worshipper continues from what he has already prayed and completes the rest of his prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (921)، والترمذي (390)، والنسائي (1202)، وابن ماجه (1245)."},{"num":2633,"demo":false,"sanad":"","matn":["عَنْ سهل بْنِ سَعْدٍ قَالَ: أَقَامَ بِلاَلٌ الصَّلاَةَ. فَتَقَدَّمَ أَبُو بَكْرٍ فَصَلَّى، فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشِي فِي الصُّفُوفِ يشُقُها شقّاً حَتَّى قَامَ فِي الصَّفِّ الأَوَّلِ. فَأَخَذَ النَّاسُ بِالتَّصْفِيحِ. قَالَ سَهْلٌ: هَلْ تَدْرُونَ مَا التَّصْفِيحُ؟ هُوَ التَّصْفِيقُ. وَكَانَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ لاَ يَلْتَفِتُ فِي صَلاَتِهِ، فَلَمَّا أَكْثَرُوا الْتَفَتَ، فَإِذَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الصَّفِّ فَأَشَارَ إِلَيْهِ: مَكَانَكَ. فَرَفَعَ أَبُو بَكْرٍ يَدَيْهِ، فحمِـدَ اللَّهَ، ثُمَّ رَجَعَ الْقَهْقَرَى وَرَاءَهُ، وَتَقَدَّمَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1201)، ومسلم في الصّلاة (421/103) كلاهما من حديث عبد العزيز بن أبي حازم، عن أبيه، عن سهل بن سعد واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في رجوع القَهْقَرَى في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1201), Muslim (421/103) — wording is al-Bukhari’s.","chapter_en":"Stepping backward (al-qahqara) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Sa‘d said: Bilal established the prayer. Abu Bakr stepped forward and led the prayer. Then the Prophet ﷺ came, passing through the rows until he stood in the first row. The people began tasfih. Sahl said: Do you know what tasfih is? It is clapping. Abu Bakr used not to turn around in his prayer, but when they did it repeatedly he turned and saw the Prophet ﷺ in the row, who gestured to him: “Stay where you are.” Abu Bakr raised his hands and praised Allah, then stepped backward behind him, and the Prophet ﷺ stepped forward and led the prayer."]},"buhuth":{"en":["This contains proof that small actions in prayer are permissible—because Abu Bakr moved back from his place to the next row. Whoever needs to do something like that should step backward (qahqara) and not turn his back to the qiblah nor deviate away from it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1201)، ومسلم (421/103) واللفظ للبخاري."},{"num":2634,"demo":false,"sanad":"","matn":["عَنْ سهل بْنِ سَعْدٍ قَالَ: أَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى امْرَأَةٍ مِنْ الأنصار أَنَّ مُرِي غلامَكِ النَّجَّارَ يَعْمَلْ لِي أَعْوَادًا أُكلِّم النَّاسَ عَلَيْهَا. فَعَمِلَ هَذِهِ الثَّلَاثَ دَرَجَاتٍ، ثُمَّ أَمَرَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فوُضِعتْ هَذَا الْمَوْضِعَ. وَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَيْهِ، فكبَّر وكبَّر النَّاسُ وَرَاءَهُ وَهُوَ عَلَى الْمِنْبَرِ. ثُمَّ رَفَعَ فَنَزَلَ القَهْقَرَى حَتَّى سَجَدَ فِي أَصْلِ الْمِنْبَرِ. ثُمَّ عَادَ حَتَّى فَرَغَ مِنْ صَلَاتِهِ، ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَقَالَ: يَا أَيُّهَا النَّاسُ إِنَّمَا فَعَلْتُ هَذَا لِتَأْتَمُّوا بِي، وَلِتَعَلَّمُوا صَلَاتِي .","وفي رواية: فَاسْتَقْبَلَ الْقِبْلَةَ، وكبَّر وَقَامَ النَّاسُ خَلْفَهُ. فَقَرَأَ وَرَكَعَ، وَرَكَعَ النَّاسُ خَلْفَهُ، ثُمَّ رَفَعَ رَأْسَهُ حتى رَجَعَ الْقَهْقَرَى فَسَجَدَ عَلَى الأَرْضِ، ثُمَّ عَادَ إِلَى الْمِنْبَرِ ثُمَّ رَكَعَ، ثُمَّ رَفَعَ رَأْسَهُ، ثُمَّ رَجَعَ الْقَهْقَرَى حَتَّى سَجَدَ بِالأَرْضِ. فَهَذَا شَأْنُهُ."],"takhrij":"متفق عليه: رواه البخاري في الجمعة (917)، ومسلم في المساجد (544/45) كلاهما عن قتيبة بن سعيد، حدثنا يعقوب بن عبدالرحمن بن محمد بن عبدالله بن عبدٍ القاريُّ القرشي الإسكندراني، قال حدثنا أبو حازم بن دينار أن رجالاً أتوا سهل بن سعد الساعدي وقد امتروا في المنبر مِمَّ عودُه، فسألوه عن ذلك. فقال: والله إني لأعرف مما هو، ولقد رأيتُه أول يوم وُضع، وأول يوم جلس عليه رسول الله صلى الله عليه وسلم فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب في رجوع القَهْقَرَى في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (917) and Muslim (544/45). The second narration is in al-Bukhari (377).","chapter_en":"Stepping backward (al-qahqara) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Sa‘d said: The Messenger of Allah ﷺ sent to a woman among the Ansar: “Tell your carpenter servant to make wooden steps for me so I can speak to the people from them.” So he made these three steps. Then the Messenger of Allah ﷺ ordered that they be placed in this spot. I certainly saw the Messenger of Allah ﷺ stand on it; he said ‘Allāhu akbar’ and the people said ‘Allāhu akbar’ behind him while he was on the pulpit. Then he raised up, and stepped down backward until he prostrated at the base of the pulpit. Then he returned until he finished his prayer. Then he turned to the people and said: “O people, I did this only so that you would follow me and so that you would learn my prayer.” In another narration: He faced the qiblah, said ‘Allāhu akbar,’ and the people stood behind him. He recited and bowed, and the people bowed behind him. Then he raised his head and stepped backward until he prostrated on the ground. Then he returned to the pulpit, then bowed, then raised his head, then stepped backward until he prostrated on the ground. This was his manner."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (917)، ومسلم (544/45). والرواية الثانية رواها البخاري (377)."},{"num":2635,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ أَنَّ أَبَا بَكْرٍ كَانَ يُصَلِّي لَهُمْ فِي وَجَعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي تُوُفِّيَ فِيهِ، حَتَّى إِذَا كَانَ يَوْمُ الِاثْنَيْنِ وَهُمْ صُفُوفٌ فِي الصَّلَاةِ، كَشَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سِتْرَ الْحُجْرَةِ. فَنَظَرَ إِلَيْنَا وَهُوَ قَائِمٌ كَأَنَّ وَجْهَهُ وَرَقَةُ مُصْحَفٍ، ثُمَّ تَبَسَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَاحِكًا. قَالَ: فَبُهِتْنَا وَنَحْنُ فِي الصَّلَاةِ مِنْ فَرَحٍ بِخُرُوجِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَكَصَ أَبُو بَكْرٍ عَلَى عَقِبَيْهِ لِيَصِلَ الصَّفَّ، وَظَنَّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَارِجٌ لِلصَّلَاةِ. فَأَشَارَ إِلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ أَنْ أَتِمُّوا صَلَاتَكُمْ. قَالَ: ثُمَّ دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَرْخَى السِّتْرَ. قَالَ: فَتُوُفِّيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ يَوْمِهِ ذَلِكَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (754) وفي مواضع أخرى من طرق عن ابن شهاب، قال أخبرني أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب في رجوع القَهْقَرَى في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (754), Muslim (419).","chapter_en":"Stepping backward (al-qahqara) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Malik said: Abu Bakr was leading them in prayer during the illness of the Messenger of Allah ﷺ in which he died. Then on Monday, while they were standing in rows in prayer, the Messenger of Allah ﷺ drew back the curtain of his room and looked at us while standing, as though his face were a page of the Qur’an. Then the Messenger of Allah ﷺ smiled, laughing slightly. We were startled in prayer from the joy of seeing the Messenger of Allah ﷺ come out. Abu Bakr stepped backward on his heels to join the row, thinking the Messenger of Allah ﷺ was coming out to pray. But the Messenger of Allah ﷺ gestured to them with his hand: “Complete your prayer.” Then the Messenger of Allah ﷺ went back in and let down the curtain. He died later that same day."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (754)، ومسلم (419)."},{"num":2636,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : لَقَدْ رَأَيْتُ فِي مَقَامِي هَذَا كُلَّ شيء وُعِدْتُه، حَتَّى لَقَدْ رأيتُي أُرِيدُ أَنْ آخُذَ قِطْفاً مِنَ الْجَنَّةِ حِينَ رَأَيْتُمُونِي جَعَلْتُ أتقدَّمُ، وَلَقَدْ رَأَيْتُ جهنَّم يَحْطِمُ بَعْضُهَا بَعْضًا حِينَ رَأَيْتُمُونِي تأخَّرتُ. وَرَأَيْتُ فِيهَا عَمْرَو بْنَ لُحيّ، وَهُوَ الَّذِي سيَّبَ السَّوَائِبَ ."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1212)، ومسلم في الكسوف (901/3) كلاهما من رواية يونس بن يزيد، عن ابن شهاب، عن عروة، عن عائشة في حديث طويل في صلاة الكسوف وسيأتي.","grade":"متفق عليه","chapter_ar":"باب في رجوع القَهْقَرَى في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1212), Muslim (901/3).","chapter_en":"Stepping backward (al-qahqara) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said: “I have seen, from this very place of mine, everything that I was promised. I even saw myself wanting to take a cluster from Paradise when you saw me step forward. And I saw Hellfire crushing parts of itself when you saw me step back. And I saw in it ‘Amr ibn Luhayy, the one who set free the sawa’ib (the released animals dedicated to idols).”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1212)، ومسلم (901/3)."},{"num":2637,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ أَحْمَدُ - يُصَلِّي، وَالْبَابُ عَلَيْهِ مُغْلَقٌ، فَجِئْتُ فَاسْتَفْتَحْتُ. - قَالَ أَحْمَدُ - فَمَشَى، فَفَتَحَ لِي، ثُمَّ رَجَعَ إِلَى مُصَلاَّهُ. وَذَكَرَ أَنَّ الْبَابَ كَانَ فِي الْقِبْلَةِ."],"takhrij":"حسن: رواه أبو داود (922)، والترمذي (601)، والنسائي (1206) كلهم من طرق عن بُرد بن سنان الشامي، عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب في المشي في الصلاة عند الحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (922), al-Tirmidhi (601), al-Nasa’i (1206), Ahmad (24027).","chapter_en":"Walking during prayer when there is a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":4,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ would be praying while the door was closed. I came and sought to open it, so he walked and opened it for me, then returned to his place of prayer. And it was mentioned that the door was in the direction of the qiblah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (922)، والترمذي (601)، والنسائي (1206)، وأحمد (24027)."},{"num":2638,"demo":false,"sanad":"","matn":["عَنِ الأَزْرَقِ بْنِ قَيْسٍ، قَالَ: كُنَّا عَلَى شَاطِئِ نَهْرٍ بِالأَهْوَازِ، قَدْ نَضَبَ عَنْهُ الْمَاءُ، فَجَاءَ أَبُو بَرْزَةَ الأَسْلَمِيُّ عَلَى فَرَسٍ، فَصَلَّى، وَخَلَّى فَرَسَهُ، فَانْطَلَقَتِ الْفَرَسُ، فَتَرَكَ صَلاَتَهُ، وَتَبِعَهَا حَتَّى أَدْرَكَهَا، فَأَخَذَهَا، ثُمَّ جَاءَ فَقَضَى صَلاَتَهُ، وَفِينَا رَجُلٌ لَهُ رَأْىٌ، فَأَقْبَلَ يَقُولُ: انْظُرُوا إِلَى هَذَا الشَّيْخِ، تَرَكَ صَلاَتَهُ مِنْ أَجْلِ فَرَسٍ. فَأَقْبَلَ فَقَالَ: مَا عَنَّفَنِي أَحَدٌ مُنْذُ فَارَقْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: إِنَّ مَنْزِلِي مُتَرَاخٍ، فَلَوْ صَلَّيْتُ وَتَرَكْتُ لَمْ آتِ أَهْلِي إِلَى اللَّيْلِ. وَذَكَرَ أَنَّهُ صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَى مِنْ تَيْسِيرِهِ.","وفي رواية قال: وإني غزوت مع رسول الله صلى الله عليه وسلم ستَّ غزوات أو سبعَ غزوات وثمان، وشهدتُ تيسيره، وإنِّي إنْ كنتُ أن أرجعَ مع دابّتي أحبُّ إليَّ من أن أدعَها ترجعُ إلى مألفها، فيشقّ عَليَّ."],"takhrij":"صحيح: رواه البخاري في الأدب (6127) عن أبي النعمان، حدثنا حماد بن زيد، عن الأزرق بن قيس به مثله.","grade":"صحيح","chapter_ar":"باب في المشي في الصلاة عند الحاجة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhari (6127).","chapter_en":"Walking during prayer when there is a need.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":4,"content":{"translation":{"en":["Al-Azraq ibn Qays said: We were on the bank of a river in al-Ahwaz, and its water had receded. Abu Barzah al-Aslami came on a horse, prayed, and let his horse go. The horse ran off, so he left his prayer and pursued it until he caught it, took hold of it, then returned and completed his prayer. Among us was a man who had his own opinion, and he began saying: “Look at this old man—he left his prayer for the sake of a horse!” Abu Barzah came and said: “No one has reproached me since I left the company of the Messenger of Allah ﷺ. My home is far away—if I prayed and left (the horse), I would not reach my family until night.” And he mentioned that he had accompanied the Prophet ﷺ and saw how he made matters easy. In another narration he said: “I went on six—or seven—or eight campaigns with the Messenger of Allah ﷺ, and I witnessed his leniency. And for me to return along with my mount is more beloved to me than to leave it to return to its familiar place, causing hardship for me.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6127)."},{"num":2639,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: التَّسْبِيحُ لِلرِّجَالِ، وَالتَّصْفِيقُ لِلنِّسَاءِ."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1203)، ومسلم في الصلاة (422) كلاهما من طريق سفيان بن عيينة، عن الزهري، عن أبي سلمة، عن أبي هريرة فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب في التسبيح والتصفيق في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1203), Muslim (422).","chapter_en":"Saying “Subhan Allah” and clapping during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":5,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “Saying ‘Subhan Allah’ is for men, and clapping is for women.”"]},"buhuth":{"en":["In a narration in Muslim, Ibn Shihab said: “And I have seen men of knowledge saying ‘Subhan Allah’ and gesturing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1203)، ومسلم (422)."},{"num":2640,"demo":false,"sanad":"","matn":["عَنْ سهل بْنِ سَعْدٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَا لِي رَأَيْتُكُمْ أَكْثرتُم التَّصْفِيقَ، مَنْ رَابَهُ شيء فِي صَلاَتِهِ فليُسَبِّح، فَإِنَّهُ إِذَا سبَّح التفِتَ إِلَيْهِ، وَإِنَّمَا التَّصْفِيقُ لِلنِّسَاءِ ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (684)، ومسلم في الصلاة (421) كلاهما من طريق مالك، عن أبي حازم، عن سهل بن سعد في حديث طويل.","grade":"متفق عليه","chapter_ar":"باب في التسبيح والتصفيق في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (684), Muslim (421).","chapter_en":"Saying “Subhan Allah” and clapping during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Sa‘d said: The Prophet ﷺ said: “Why do I see you clapping so much? Whoever is confronted with something in his prayer should say ‘Subhan Allah,’ for when he says ‘Subhan Allah,’ attention will be turned to him. Clapping is only for women.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (684)، ومسلم (421)."},{"num":2641,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ قَالَ: رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نُخَامَةً فِي قِبْلَةِ الْمَسْجِدِ، وَهْوَ يُصَلِّي بَيْنَ يَدَىِ النَّاسِ، فَحَتَّهَا، ثُمَّ قَالَ حِينَ انْصَرَفَ: إِنَّ أَحَدَكُمْ إِذَا كَانَ فِي الصَّلاَةِ، فَإِنَّ اللَّهَ قِبَلَ وَجْهِهِ، فَلاَ يَتَنَخَّمَنَّ أَحَدٌ قِبَلَ وَجْهِهِ فِي الصَّلاَةِ."],"takhrij":"صحيح: رواه البخاري في الأذان (753) عن قتيبة بن سعيد، قال: حدثنا ليث، عن نافع، عن ابن عمر فذكر مثله. وقال: رواه موسى بن عقبة وابن أبي روَّاد، عن نافع.","grade":"صحيح","chapter_ar":"باب إزالة البصاق من قبلة المسجد في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhari (753).","chapter_en":"Removing spittle from the qiblah wall of the mosque during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":6,"content":{"translation":{"en":["Ibn ‘Umar said: The Prophet ﷺ saw some mucus on the qiblah side of the mosque while he was praying in front of the people, so he scraped it off. Then, when he finished, he said: “When one of you is in prayer, Allah is in front of his face, so let none of you spit in front of his face during prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (753)."},{"num":2642,"demo":false,"sanad":"","matn":["عَنْ مُعَيْقِيبٍ قَالَ:  ذَكَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْحَ فِي الْمَسْجِدِ. - يَعْنِي الْحَصَى - قَالَ: إِنْ كُنْتَ لَا بُدَّ فَاعِلًا فَوَاحِدَةً."],"takhrij":"متفق عليه: رواه البخاري في العمل في الصلاة (1207) من حديث شيبان، ومسلم في المساجد (546) من حديث هشام الدستوائي، كلاهما عن يحيى بن أبي كثير، عن أبي سلمة، عن معيقيب فذكره.","grade":"متفق عليه","chapter_ar":"باب مسح الحصى في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1207) and Muslim (546) — wording is Muslim’s.","chapter_en":"Wiping/smoothing pebbles during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":7,"content":{"translation":{"en":["Mu‘ayqib said: The Prophet ﷺ mentioned wiping in the mosque—meaning the pebbles—and said: “If you must do it, then (do it) once.”"]},"buhuth":{"en":["In al-Bukhari’s wording: The Prophet ﷺ said about a man smoothing the earth where he prostrates: “If you do it, then (do it) once.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1207)، ومسلم (546) واللفظ لمسلم،."},{"num":2643,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: كُنْتُ أُصَلِّي الظُّهْرَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَآخُذُ قَبْضَةً مِنَ الْحَصَى لِتَبْرُدَ فِي كَفِّي أَضَعُهَا لِجَبْهَتِي أَسْجُدُ عَلَيْهَا لِشِدَّةِ الْحَرِّ."],"takhrij":"حسن: رواه أبو داود (399)، والنسائي (1081) كلاهما من حديث عباد بن عباد، حدثنا محمد بن عمرو، عن سعيد بن الحارث الأنصاري، عن جابر بن عبدالله فذكر مثله.","grade":"حسن","chapter_ar":"باب مسح الحصى في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (399), al-Nasa’i (1081).","chapter_en":"Wiping/smoothing pebbles during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abdillah said: I used to pray Dhuhr with the Messenger of Allah ﷺ, and I would take a handful of pebbles to cool them in my palm, then place them for my forehead to prostrate on because of the intense heat."]},"buhuth":{"en":["Ibn Hibban graded it authentic (2276), and his wording is: “We used to pray with the Prophet ﷺ in severe heat. One of us would take a handful of pebbles and place them in this palm, then in this palm; when they cooled, he would prostrate on them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1796],"tks":"حسن: رواه أبو داود (399)، والنسائي ( 1081)،."},{"num":2644,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِذَا قَامَ أَحَدُكُمْ إِلَى الصَّلاَةِ، فإنّ الرَّحْمَةَ تُوَاجِهُهُ، فَلاَ يَمْسَحِ الْحَصَى .","وفي رواية: فلا يمسّ الحصى."],"takhrij":"حسن: رواه أبو داود (945)، والترمذي (379)، والنسائي (1190)، وابن ماجة (1027)، وأحمد (21330) كلّهم من طرق عن سفيان، عن الزهري، عن أبي الأحوص شيخ من أهل المدينة، عن أبي ذر فذكره. واللفظ لأبي داود.","grade":"حسن","chapter_ar":"باب مسح الحصى في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (945), al-Tirmidhi (379) who graded it hasan, al-Nasa’i (1190), Ibn Majah (1027).","chapter_en":"Wiping/smoothing pebbles during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":7,"content":{"translation":{"en":["Abu Dharr reported that the Prophet ﷺ said: “When one of you stands for prayer, mercy faces him, so let him not wipe the pebbles.” In another narration: “So let him not touch the pebbles.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (945)، والترمذي (379) وحسنه، والنسائي (1190)، وابن ماجه (1027)."},{"num":2645,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ أَنَّهُ قَالَ:  إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَنِي لِحَاجَةٍ ثُمَّ أَدْرَكْتُهُ وَهُوَ يَسِيرُ - قَالَ قُتَيْبَةُ: يُصَلِّي - فَسَلَّمْتُ عَلَيْهِ. فَأَشَارَ إِلَيَّ. فَلَمَّا فَرَغَ دَعَانِي فَقَالَ: إِنَّكَ سَلَّمْتَ آنِفًا، وَأَنَا أُصَلِّي، وَهُوَ مُوَجِّهٌ حِينَئِذٍ قِبَلَ الْمَشْرِقِ."],"takhrij":"صحيح: رواه مسلم في المساجد (540) عن قتيبة بن سعيد، حدثنا الليث ابن سعد، عن أبي الزبير، عن جابر فذكر مثله.","grade":"صحيح","chapter_ar":"باب ردّ السلام بالإشارة في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (540).","chapter_en":"Returning the greeting of السلام by gesture during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":8,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ sent me on an errand, then I caught up with him while he was traveling (Qutaybah said: “praying”). I greeted him with salām, and he gestured to me. When he finished, he called me and said: “You greeted me earlier while I was praying,” and at that time he was facing toward the east."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (540)."},{"num":2646,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: أَتَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَسْجِدَ قُبَاءٍ يُصَلِّي فِيهِ. فَجَاءَتْ رِجَالٌ مِنَ الأَنْصَارِ يُسَلِّمُونَ عَلَيْهِ. فَسَأَلْتُ صُهيباً، وَكَانَ مَعَهُ: كَيْفَ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرُدُّ عَلَيْهِمْ؟ قَالَ: كَانَ يُشِيرُ بِيَدِهِ."],"takhrij":"صحيح: رواه النسائي (1187)، وابن ماجة (1017) كلاهما من طريق سفيان بن عيينة، عن زيد بن أسلم، عن عبدالله بن عمر فذكر مثله. ومن هذا الطريق رواه ابن خزيمة في صحيحه (888).","grade":"صحيح","chapter_ar":"باب ردّ السلام بالإشارة في الصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1187), Ibn Majah (1017), Ibn Khuzaymah in his Sahih (888).","chapter_en":"Returning the greeting of السلام by gesture during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":8,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: The Messenger of Allah ﷺ came to the Mosque of Quba’ to pray in it, and some men from the Ansar came greeting him with salām. I asked Suhayb—who was with him—how the Messenger of Allah ﷺ used to respond to them. He said: “He would gesture with his hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1187)، وابن ماجه (1017) وابن خزيمة في صحيحه (888)،."},{"num":2647,"demo":false,"sanad":"","matn":["عَنْ عَمَّارِ بْنِ يَاسِرٍ، أَنَّهُ سَلَّمَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي، فَرَدَّ عَلَيْهِ."],"takhrij":"صحيح: رواه النسائي (1188) عن محمد بن بشار، قال حدثنا وهب -يعني ابن جرير، قال: حدثنا أبي، عن قيس بن سعد، عن عطاء، عن محمد بن علي، عن عمار بن ياسر فذكر مثله.","grade":"صحيح","chapter_ar":"باب الإشارة في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1188).","chapter_en":"Gesturing during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":9,"content":{"translation":{"en":["‘Ammar ibn Yasir greeted the Prophet ﷺ with salām while he was praying, and he returned the greeting to him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1188)."},{"num":2648,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتِ:  اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَدَخَلَ عَلَيْهِ نَاسٌ مِنْ أَصْحَابِهِ يَعُودُونَهُ، فَصَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا. فَصَلَّوْا بِصَلَاتِهِ قِيَامًا، فَأَشَارَ إِلَيْهِمْ أَنِ اجْلِسُوا. فَجَلَسُوا. فَلَمَّا انْصَرَفَ قَالَ: إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ، فَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا رَفَعَ فَارْفَعُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا."],"takhrij":"متفق عليه: رواه البخاري في الأذان (688) عن عبدالله بن يوسف، عن مالك، عن هشام بن عروة، عن أبيه، عن عائشة. ورواه مسلم في الصلاة (412) عن أبي بكر بن أبي شيبة، حدثنا عبدة بن سليمان، عن هشام، عن أبيه، عن عائشة فذكرتِ الحديث واللفظ له.","grade":"متفق عليه","chapter_ar":"باب الإشارة في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (688) and Muslim (412) — wording is Muslim’s.","chapter_en":"Gesturing during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":9,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ was ill, and some of his Companions entered to visit him. The Messenger of Allah ﷺ prayed sitting, while they prayed standing following his prayer. He gestured to them to sit. When he finished, he said: “The imam is only appointed to be followed: when he bows, then bow; when he rises, then rise; and when he prays sitting, then pray sitting.”"]},"buhuth":{"en":["Al-Bayhaqi (2/261) said: ‘Urwah said in this hadith: “So he signaled to them with his hand to sit.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (688) ومسلم (412) واللفظ له."},{"num":2649,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ أَنَّهَا قَالَتْ: أَتَيْتُ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ خَسَفَتِ الشَّمْسُ، فَإِذَا النَّاسُ قِيَامٌ يُصَلُّونَ، وَإِذَا هِيَ قَائِمَةٌ تُصَلِّي. فَقُلْتُ: مَا لِلنَّاسِ؟ فَأَشَارَتْ بِيَدِهَا نَحْوَ السَّمَاءِ. وَقَالَتْ: سُبْحَانَ اللَّهِ. فَقُلْتُ: آيَةٌ؟ فَأَشَارَتْ أَىْ نَعَمْ."],"takhrij":"متفق عليه: رواه مالك في الكسوف (4) عن هشام بن عروة، عن فاطمة بنت المنذر، عن أسماء فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب الإشارة في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (4), al-Bukhari (184), Muslim (905).","chapter_en":"Gesturing during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":9,"content":{"translation":{"en":["Asma’ bint Abi Bakr said: I came to ‘A’ishah, the wife of the Prophet ﷺ, when the sun was eclipsed. The people were standing in prayer, and she was standing praying. I asked: “What is with the people?” She gestured with her hand toward the sky and said: “Subhan Allah.” I asked: “A sign?” She gestured: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4) والبخاري (184)، ومسلم ( 905)."},{"num":2650,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: اشْتَكَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّيْنَا وَرَاءَهُ وَهُوَ قَاعِدٌ. فَالْتَفَتَ إِلَيْنَا فَرَآنَا قِيَامًا. فَأَشَارَ إِلَيْنَا فَقَعَدْنَا."],"takhrij":"صحيح: رواه مسلم في الصلاة (413) من طريق الليث، عن أبي الزبير، عن جابر في حديث طويل.","grade":"صحيح","chapter_ar":"باب الإشارة في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (413).","chapter_en":"Gesturing during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":9,"content":{"translation":{"en":["Jabir ibn ‘Abdillah said: The Messenger of Allah ﷺ was ill, so we prayed behind him while he was sitting. He turned to us and saw us standing, so he gestured to us and we sat."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (413)."},{"num":2651,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُشِيرُ فِي الصَّلاَةِ."],"takhrij":"صحيح: رواه أبو داود (943) عن أحمد بن محمد بن شبويه ومحمد بن رافع قالا: حدثنا عبد الرزاق، أخبرنا معمر، عن الزهري، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب الإشارة في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (943), ‘Abd al-Razzaq (3276), Ibn Khuzaymah (885), Ibn Hibban (2264).","chapter_en":"Gesturing during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Malik reported that the Prophet ﷺ used to gesture during prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (943). وعبد الرزاق (3276) وابن خزيمة (885)، وابن حبان (2264)."},{"num":2652,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بن رَافِعٍ قَالَ: صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَطَسْتُ فَقُلْتُ: الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، مُبَارَكًا عَلَيْهِ كَمَا يحبّ رَبُّنَا وَيَرْضَى، فَلَمَّا صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ فَقَالَ: مَنِ الْمُتَكَلِّمُ فِي الصَّلاَةِ؟ فَلَمْ يَتَكَلَّمْ أحدٌ، ثُمَّ قاله الثَّانِيَةَ: مَن الْمُتَكَلِّمُ فِي الصَّلاَةِ؟ فَلَمْ يَتَكَلَّمْ أحدٌ، ثُمَّ قَالَهَا الثَّالِثَةَ: مَن الْمُتَكَلِّمُ فِي الصَّلاَةِ؟ فَقَالَ رِفَاعَةُ بْنُ رَافِعِ بن عَفْرَاءَ، أَنَا يَا رَسُولَ اللَّهِ قَالَ: كَيْفَ قُلْتَ؟ قَالَ: قُلْتُ: الْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، مُبَارَكًا عَلَيْهِ كَمَا يحبّ ربُّنا وَيَرْضَى، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : وَالَّذِي نَفْسِي بِيَدِهِ لَقَدِ ابْتَدَرَهَا بِضْعَةٌ وَثَلاَثُونَ مَلَكًا أَيُّهُمْ يَصْعَدُ بِهَا ."],"takhrij":"حسن: رواه أبو داود (772)، والترمذي (404)، والنسائي (931) كلهم عن قتيبة بن سعيد، قال: حدثنا رفاعة بن يحيى بن عبدالله بن رفاعة بن رافع الزُرقي، عن عم أبيه معاذ بن رفاعة بن رافع، عن أبيه رفاعة بن رافع فذكره.","grade":"حسن","chapter_ar":"باب قول العاطس في الصّلاة: الحمد لله","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (772), al-Tirmidhi (404), al-Nasa’i (931).","chapter_en":"Saying “Alhamdulillah” when one sneezes in prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":10,"content":{"translation":{"en":["Rifa‘ah ibn Rafi‘ said: I prayed behind the Messenger of Allah ﷺ, and I sneezed, so I said: “Alhamdulillah—praise be to Allah—abundantly, good and blessed; blessed upon it as our Lord loves and is pleased with.” When the Messenger of Allah ﷺ finished the prayer, he turned and said: “Who was the one speaking in the prayer?” No one spoke. Then he said it a second time: “Who was the one speaking in the prayer?” No one spoke. Then he said it a third time: “Who was the one speaking in the prayer?” So Rifa‘ah ibn Rafi‘ ibn ‘Afra’ said: “It was me, O Messenger of Allah.” He said: “How did you say it?” He said: “I said: ‘Alhamdulillah—praise be to Allah—abundantly, good and blessed; blessed upon it as our Lord loves and is pleased with.’” The Prophet ﷺ said: “By the One in whose Hand is my soul, more than thirty angels rushed to it—each of them wanting to be the one to take it up.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (772)، والترمذي (404)، والنسائي (931)."},{"num":2653,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ قَالَ: : رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَفِي صَدْرِهِ أَزِيزٌ كَأَزِيزِ الْمِرْجَلِ مِنَ الْبُكَاءِ."],"takhrij":"صحيح: رواه أبو داود (904)، والنسائي (1214)، والترمذي في الشمائل (316) كلهم من طريق حماد بن سلمة، عن ثابت البناني، عن مطرف بن عبدالله بن الشَّخِّير، عن أبيه فذكر مثله.","grade":"صحيح","chapter_ar":"باب البكاء في الصّلاة من خشية الله","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (904), al-Nasa’i (1214), al-Tirmidhi in al-Shama’il (316), Ibn Khuzaymah (900).","chapter_en":"Crying in prayer out of fear of Allah.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":11,"content":{"translation":{"en":["‘Abdullah ibn al-Shikhkhir said: I saw the Messenger of Allah ﷺ praying, and from his chest came a sound like that of a boiling pot because of his weeping."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (904)، والنسائي (1214)، والترمذي في الشمائل (316). وابن خزيمة (900)."},{"num":2654,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: كَسَفَتِ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فصلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَطَالَ الْقِيَامَ، ثُمَّ رَكَعَ، فَأَطَالَ الرُّكُوعَ، ثُمَّ رَفَعَ فَأَطَالَ، قَالَ شُعْبَةُ: وَأَحْسِبُهُ قَالَ فِي السُّجُودِ نَحْوَ ذَلِكَ. وَجَعَلَ يَبْكِي فِي سُجُودِهِ، وَيَنْفُخُ وَيَقُولُ: رَبِّ لَمْ تعِدْني هَذَا، وَأَنَا استغفرك، لَمْ تعِدْني هَذَا وَأَنَا فِيهِمْ .","وفي رواية: ثم نفخ في آخر سجوده فقال: أف أف ثم قال: ربِّ ألم تعِدْني أن لا تعذِّبهم وأنا فيهم، ألم تعِدْني أن لا تعذبهم وهم يستغفرون؟ فرغ رسول الله صلى الله عليه وسلم مِن صلاته، وقد أمْحصتِ الشّمس. وساق الحديث بطوله وسيأتي في كتاب كسوف الشمس."],"takhrij":"صحيح: رواه النسائي (1496) من طريق غندر، عن شعبة، عن عطاء بن السائب، عن أبيه، عن عبدالله بن عمرو فذكر مثله. ورجاله كلهم ثقات إلا أن عطاء بن السائب قد اختلط، ولكن رواه شعبة عنه قبل الاختلاط. ومن هذا الوجه رواه أيضاً الإمام أحمد (6763) عن محمد بن جعفر وهو غندر عنه. كما رواه أيضاً (6868) عن عبد الرزاق، وهو في مصنفه (4938) عن سفيان، عن عطاء بن السائب به مختصراً.","grade":"صحيح","chapter_ar":"باب في النّفخ في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1496), ‘Abd al-Razzaq (4938).","chapter_en":"Blowing (exhaling) during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":12,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: The sun was eclipsed during the time of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ prayed: he prolonged the standing, then bowed and prolonged the bowing, then rose and prolonged (the standing again). Shu‘bah said: and I think he said that in prostration it was similar to that. He began to weep in his prostration and to blow (exhale), saying: “My Lord, You did not promise me this—while I am seeking Your forgiveness. You did not promise me this while they are among us.” And in another narration: Then he blew at the end of his prostration and said: “Af, af,” then he said: “My Lord, did You not promise me that You would not punish them while I am among them? Did You not promise me that You would not punish them while they are seeking forgiveness?” The Messenger of Allah ﷺ finished his prayer, and the sun had become clear again. The hadith continues at length and will come in the Book of the Solar Eclipse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1496)، وعبد الرزاق (4938)."},{"num":2655,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إنَّ عِفْرِيتًا مِنَ الجنِّ تفلَّتَ عليَّ الْبَارِحَةَ - أَوْ كلمة نحوها- لِيَقْطَعَ عليَّ صَلاَتِي. فَأَمْكَنَنِي اللَّهُ مِنْهُ فَأَخَذْتُهُ فَأَرَدْتُ أَنْ أرْبطَه عَلَى سَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ حَتَّى تَنْظُرُوا إِلَيْهِ كُلُّكم. فذكرْتُ دَعْوَةَ أَخِي سُلَيْمَانَ: ﴿رَبِّ اغْفِرْ لِي وَهَبْ لِي مُلْكًا لَا يَنْبَغِي لِأَحَدٍ مِنْ بَعْدِي﴾ [ سورة ص: 35] فَرَدَدْتُهُ خَاسِئًا. عِفْريت: مُتَمَرِّدٌ مِنْ إِنْسٍ أَوْ جَانٍّ مِثْلُ زَبْنِيَة جَمَاعَتُهَا الزَّبَانِيَةُ."],"takhrij":"متفق عليه: رواه البخاري في أحاديث الأنبياء (3423)، ومسلم في المساجد (541) كلاهما عن محمد بن بشار، حدثنا محمد بن جعفر، حدثنا شعبة، عن محمد ابن زياد، قال: سمعتُ أبا هريرة فذكر الحديث واللفظ للبخاريّ.","grade":"متفق عليه","chapter_ar":"باب دفع الجن وخنقه في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (3423) and Muslim (541) — wording is al-Bukhari’s.","chapter_en":"Repelling the jinn and choking/grappling him during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":13,"content":{"translation":{"en":["Abu Hurayrah reported that the Prophet ﷺ said: “An ‘ifrit from the jinn broke loose against me last night—or words to that effect—to cut off my prayer. Allah enabled me against him, so I seized him, and I wanted to tie him to one of the mosque’s pillars so that all of you could look at him. But I remembered the supplication of my brother Sulayman: ‘My Lord, forgive me and grant me a kingdom that will not belong to anyone after me’ (Surah Sad: 35), so I sent him back, disgraced.” “‘Ifrit” means a rebellious, defiant one from humans or jinn, like the zabaniyah, whose group are the zabaniyah."]},"buhuth":{"en":["The phrase “Then I remembered the saying/supplication of my brother Sulayman…” means: the Prophet ﷺ had the ability to tie him to a pillar in the mosque, but when he remembered the words of Sulayman عليه السلام, he refrained out of humility and good manners. His being enabled over the jinn in this incident does not contradict the verse: “Grant me a kingdom that will not belong to anyone after me” (Sad: 35), because Sulayman’s unique, complete kingship is not nullified by this limited ability.","The phrase “so that you could all look at him” is evidence that seeing the jinn is not impossible. As for Allah’s statement: “Indeed, he sees you—he and his tribe—from where you do not see them” (al-A‘raf: 27), it is a ruling about what is general and most common; people are tested with this so that they turn to Allah, seek refuge with Him, and ask His protection from their harm. See: Sharh al-Sunnah (3/270)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3423)، ومسلم (541) واللفظ للبخاري."},{"num":2656,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي، فَأَتَاهُ الشَّيْطَانُ فَأَخَذَهُ، فَصَرَعَهُ فَخَنَقَهُ، قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَتَّى وَجَدْتُ بَرْدَ لِسَانِهِ عَلَى يَدِي، وَلَوْلَا دَعْوَةُ أَخِي سُلَيْمَانَ عَلَيْهِ السَّلَام لَأَصْبَحَ مُوثَقًا حَتَّى يَرَاهُ النَّاسُ."],"takhrij":"صحيح: رواه النسائي في الكبرى (11375) عن إسحاق بن إبراهيم، قال: أخبرنا يحيى بن آدم، قال: حدثنا أبو بكر ابن عياش، عن حصين، عن عبيدالله، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب دفع الجن وخنقه في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i in al-Kubra (11375); also authenticated by Ibn Hibban (2350).","chapter_en":"Repelling the jinn and choking/grappling him during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":13,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ was praying when the devil came to him. The Prophet ﷺ seized him, threw him down, and choked him. The Messenger of Allah ﷺ said: “Until I felt the coolness of his tongue on my hand; and if not for the supplication of my brother Sulayman عليه السلام, he would have become bound by morning so that the people could see him.”"]}},"tuhfa":{},"voc":["kubranasai",11407],"full":1,"dr":1,"rep":[13182],"tks":"صحيح: رواه النسائي في الكبرى (11375)، وصححه ابن حبان (2350)."},{"num":2657,"demo":false,"sanad":"","matn":["عن جابر بْنِ سَمُرَةَ يَقُولُ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْفَجْرِ، فَجَعَلَ يَهْوِي بِيَدِهِ، قَالَ خَلَفٌ: يَهْوِي، فِي الصَّلَاةِ قُدَّامَهُ، فَسَأَلَهُ الْقَوْمُ حِينَ انْصَرَفَ فَقَالَ: إِنَّ الشَّيْطَانَ هُوَ كَانَ يُلْقِي عَلَيَّ شَرَرَ النَّارِ لِيَفْتِنَنِي عَنْ صَلَاتِي، فَتَنَاوَلْتُهُ، فَلَوْ أَخَذْتُهُ، مَا انْفَلَتَ مِنِّي حَتَّى يُنَاطَ إِلَى سَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، يَنْظُرُ إِلَيْهِ وِلْدَانُ أَهْلِ الْمَدِينَةِ."],"takhrij":"حسن: رواه الإمام أحمد (21000) عن عبدالرزاق وخَلف بن الوليد، قالا: حدثنا إسرائيل، عن سماك أنه سمع جابر بن سمرة فذكر مثله.","grade":"حسن","chapter_ar":"باب دفع الجن وخنقه في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (21000).","chapter_en":"Repelling the jinn and choking/grappling him during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":13,"content":{"translation":{"en":["Jabir ibn Samurah said: The Messenger of Allah ﷺ led us in the Fajr prayer, and he began to thrust/reach forward with his hand. Khalaf said: he was reaching forward in the prayer in front of him. When he finished and turned away, the people asked him, and he said: “The devil was throwing sparks of fire at me to tempt me away from my prayer, so I reached for him. If I had seized him, he would not have slipped away from me until he was tied to one of the mosque’s pillars, and the children of the people of Madinah would look at him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (21000)."},{"num":2658,"demo":false,"sanad":"","matn":["حَدَّثَنِي أَبُو سَعِيدٍ الْخُدْرِيُّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فَصَلَّى صَلَاةَ الصُّبْحِ، وَهُوَ خَلْفَهُ، فَقَرَأَ، فَالْتَبَسَتْ عَلَيْهِ الْقِرَاءَةُ، فَلَمَّا فَرَغَ مِنْ صَلَاتِهِ قَالَ: لَوْ رَأَيْتُمُونِي وَإِبْلِيسَ، فَأَهْوَيْتُ بِيَدِي، فَمَا زِلْتُ أَخْنُقُهُ حَتَّى وَجَدْتُ بَرْدَ لُعَابِهِ بَيْنَ إِصْبَعَيَّ هَاتَيْنِ - الْإِبْهَامِ وَالَّتِي تَلِيهَا - وَلَوْلَا دَعْوَةُ أَخِي سُلَيْمَانَ، لَأَصْبَحَ مَرْبُوطًا بِسَارِيَةٍ مِنْ سَوَارِي الْمَسْجِدِ، يَتَلَاعَبُ بِهِ صِبْيَانُ الْمَدِينَةِ، فَمَنْ اسْتَطَاعَ مِنْكُمْ أَنْ لَا يَحُولَ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ أَحَدٌ فَلْيَفْعَلْ."],"takhrij":"حسن: رواه الإمام أحمد (11780) عن أبي أحمد، حدثنا مسرَّة بن معبد، حدثني أبو عبيد حاجب سليمان، قال: رأيتُ عطاء بن يزيد الليثي قائماً يصلِّي، مُتعمماً بعمامةٍ سوداء، مرخى طرفَها من خلْفِه، مُصَفِّر اللحيةِ. فذهبتُ أمرُّ بين يديه فردَّني، ثم قال: حدثني أبو سعيد الخدري فذكر مثله.","grade":"حسن","chapter_ar":"باب دفع الجن وخنقه في الصّلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (11780).","chapter_en":"Repelling the jinn and choking/grappling him during prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":13,"content":{"translation":{"en":["Abu Sa‘id al-Khudri reported that the Messenger of Allah ﷺ stood and prayed the morning (Fajr) prayer while Abu Sa‘id was behind him, and his recitation became confused for him. When he finished his prayer, he said: “If you had seen me and Iblis: I reached down with my hand, and I kept choking him until I felt the coolness of his saliva between these two fingers of mine—the thumb and the one next to it. If not for the supplication of my brother Sulayman, he would have been tied by morning to one of the mosque’s pillars, and the children of Madinah would play with him. So whoever among you is able that nothing should come between him and the qiblah, let him do so.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (11780)."},{"num":2659,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: أَنَّهُ قَالَ:  كَانَ جُرَيْجٌ يَتَعَبَّدُ فِي صَوْمَعَةٍ، فَجَاءَتْ أُمُّهُ، قَالَ حُمَيْدٌ: فَوَصَفَ لَنَا أَبُو رَافِعٍ صِفَةَ أَبِي هُرَيْرَةَ لِصِفَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُمَّهُ حِينَ دَعَتْهُ. كَيْفَ جَعَلَتْ كَفَّهَا فَوْقَ حَاجِبِهَا، ثُمَّ رَفَعَتْ رَأْسَهَا إِلَيْهِ تَدْعُوهُ، فَقَالَتْ: يَا جُرَيْجُ! أَنَا أُمُّكَ. كَلِّمْنِي. فَصَادَفَتْهُ يُصَلِّي، فَقَالَ: اللَّهُمَّ أُمِّي وَصَلَاتِي. فَاخْتَارَ صَلَاتَهُ، فَرَجَعَتْ، ثُمَّ عَادَتْ فِي الثَّانِيَةِ، فَقَالَتْ: يَا جُرَيْجُ! أَنَا أُمُّكَ، فَكَلِّمْنِي. قَالَ: اللَّهُمَّ! أُمِّي وَصَلَاتِي. فَاخْتَارَ صَلَاتَهُ، فَقَالَتِ: اللَّهُمَّ! إِنَّ هَذَا جُرَيْجٌ، وَهُوَ ابْنِي، وَإِنِّي كَلَّمْتُهُ، فَأَبَى أَنْ يُكَلِّمَنِي، اللَّهُمَّ! فَلَا تُمِتْهُ حَتَّى تُرِيَهُ الْمُومِسَاتِ."],"takhrij":"متفق عليه: رواه مسلم في البر والصلة (2550) عن شيبان بن فروخ، حدثنا سليمان بن المغيرة، حدثنا حميد بن هلال، عن أبي رافع، عن أبي هريرة فذكره. واللفظ له.","grade":"متفق عليه","chapter_ar":"باب إجابة الرجل أمَّه في صلاة التطوع","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Muslim (2550) — wording; and al-Bukhari (3436).","chapter_en":"A man responding to his mother during a voluntary (nafl) prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":14,"content":{"translation":{"en":["Abu Hurayrah said: Jurayj used to worship in a hermitage. His mother came to him. Humayd said: Abu Rafi‘ described to us the gesture Abu Hurayrah used—like the gesture of the Messenger of Allah ﷺ—showing how his mother called him: how she placed her palm above her eyebrow, then raised her head toward him while calling him. She said: “O Jurayj! I am your mother—speak to me.” She found him praying, and he said: “O Allah, my mother or my prayer.” He chose his prayer, so she went back. Then she returned a second time and said: “O Jurayj! I am your mother—speak to me.” He said: “O Allah, my mother or my prayer,” and he chose his prayer. Then she said: “O Allah, this is Jurayj, and he is my son; I spoke to him and he refused to speak to me. O Allah, do not let him die until You show him the prostitutes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2550) واللفظ له. والبخاري (3436)."},{"num":2660,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ قَالَ:  قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَمِعْنَاهُ يَقُولُ: أَعُوذُ بِاللهِ مِنْكَ. ثُمَّ قَالَ: أَلْعَنُكَ بِلَعْنَةِ اللهِ ثَلَاثًا، وَبَسَطَ يَدَهُ كَأَنَّهُ يَتَنَاوَلُ شَيْئًا. فَلَمَّا فَرَغَ مِنَ الصَّلَاةِ قُلْنَا: يَا رَسُولَ اللَّهِ، قَدْ سَمِعْنَاكَ تَقُولُ فِي الصَّلَاةِ شَيْئًا لَمْ نَسْمَعْكَ تَقُولُهُ قَبْلَ ذَلِكَ، وَرَأَيْنَاكَ بَسَطْتَ يَدَكَ. قَالَ: إِنَّ عَدُوَّ اللَّهِ إِبْلِيسَ جَاءَ بِشِهَابٍ مِنْ نَارٍ لِيَجْعَلَهُ فِي وَجْهِي، فَقُلْتُ: أَعُوذُ بِاللهِ مِنْكَ. ثَلَاثَ مَرَّاتٍ، ثُمَّ قُلْتُ: أَلْعَنُكَ بِلَعْنَةِ اللهِ التَّامَّةِ. فَلَمْ يَسْتَأْخِرْ ثَلَاثَ مَرَّاتٍ. ثُمَّ أَرَدْتُ أَخْذَهُ، وَاللهِ لَوْلَا دَعْوَةُ أَخِينَا سُلَيْمَانَ لَأَصْبَحَ مُوثَقًا يَلْعَبُ بِهِ وِلْدَانُ أَهْلِ الْمَدِينَةِ."],"takhrij":"صحيح: رواه مسلم في المساجد (542) من حديث عبدالله بن وهب، عن معاوية بن صالح، حدَّثني ربيعةُ بن يزيد، عن أبي إدريس الخولاني، عن أبي الدرداء، فذكره.","grade":"صحيح","chapter_ar":"باب لعن الشيطان في أثناء الصّلاة والتعوّذ منه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (542).","chapter_en":"Cursing the devil during prayer and seeking refuge from him.","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب أن العمل القليل لا يُفْسِد الصلاةَ","group_en":"Collected chapters: That small (limited) actions do not invalidate the prayer.","part_no":9,"group_no":15,"chapter_no":15,"content":{"translation":{"en":["Abu al-Darda’ said: The Messenger of Allah ﷺ stood (to pray), and we heard him saying: “I seek refuge in Allah from you,” then he said: “I curse you with Allah’s curse,” three times. And he stretched out his hand as if he were reaching for something. When he finished the prayer, we said: “O Messenger of Allah, we heard you say something in the prayer that we never heard you say before, and we saw you stretch out your hand.” He said: “The enemy of Allah, Iblis, came with a flaming brand of fire to put it in my face. So I said: ‘I seek refuge in Allah from you,’ three times. Then I said: ‘I curse you with Allah’s complete curse,’ but he did not withdraw—three times. Then I intended to seize him. By Allah, if not for the supplication of our brother Sulayman, he would have been bound by morning, and the children of the people of Madinah would play with him.”"]},"buhuth":{"en":["It is understood from these hadiths mentioned in the preceding chapters that a small amount of action during prayer does not invalidate the prayer, unlike a large amount of action, such as eating and drinking, turning one’s back to the qiblah, playing with mobile phones, laughing out loud (like loud guffawing), speaking deliberately, excessive turning around, and frequent fidgeting, and similar behaviors—because they preoccupy the heart from turning to Allah and from the khushu‘ (humble focus) required in prayer.","Allah the Exalted says: “And from the night, pray with it as extra worship for you; it may be that your Lord will raise you to a praised station.” (Al-Isra’: 79)","And He says: “And those who spend the night before their Lord, prostrating and standing.” (Al-Furqan: 64)","And He says: “Their sides forsake their beds; they call upon their Lord in fear and hope, and from what We have provided them they spend.” (As-Sajdah: 16)"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8458,13181],"tks":"صحيح: رواه مسلم (542)."},{"num":2661,"demo":false,"sanad":"","matn":["عَنْ الْمُغِيرَةِ بن شُعْبَةَ قَالَ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيَقُومُ -أَوْ لَيُصلّي- حَتَّى تَرِم قَدَمَاهُ- أَوْ -سَاقَاهُ- فَيُقَالُ لَهُ: فَيَقُولُ: أَفَلاَ أَكُونُ عَبْدًا شَكُورًا ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1130)، ومسلم في كتاب صفة القيامة والجنّة والنار (2819) كلاهما من حديث زياد بن عِلاقة، عن المغيرة بن شعبة فذكره.","grade":"متفق عليه","chapter_ar":"باب في اجتهاد النبي ﷺ في قيام الليل لرفع الدرجات وعلو المراتب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1130), Muslim (2819). In Muslim’s wording: The Prophet ﷺ prayed until his feet swelled, and it was said to him: “Do you take on this hardship when Allah has forgiven for you what came before of your sin and what came after?” He said: “Should I not be a grateful servant?”","chapter_en":"The Prophet’s ﷺ striving in standing at night to raise ranks and attain lofty stations.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":1,"content":{"translation":{"en":["Al-Mughirah ibn Shu‘bah said: The Messenger of Allah ﷺ would stand—or pray—until his feet—or his legs—became swollen. It was said to him, and he said: “Should I not be a grateful servant?”"]},"intro_majmu":{"ar":["قال اللّٰه تعالى: ( وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِ نَافِلَةً لَكَ عَسَى أَن يَبْعَثَكَ رَبِّكَ مَقَامًا مَحْمُودًا ) [الإسراء: ٧٩].","وقال تعالى: (وَالَّذِينَ يَبِيتُونَ لِرَبّهِمْ سُجَّدًا وَقِيَمَا) [الفرقان: ٦٤].","وقال: ( تَتَجَافَىٰ جُنُوبُهُمْ عَنِ ٱلْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَـٰهُمْ يُنفِقُونَ ) [سورة السجدة: ١٦]."],"en":["Allah the Exalted says: “And from the night, pray with it as extra worship for you; it may be that your Lord will raise you to a praised station.” (Al-Isra’: 79)","And He says: “And those who spend the night before their Lord, prostrating and standing.” (Al-Furqan: 64)","And He says: “Their sides forsake their beds; they call upon their Lord in fear and hope, and from what We have provided them they spend.” (As-Sajdah: 16)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1130)، ومسلم (2819). وفي لفظ مسلم: أن النبي ﷺ صلى حتى انتفخت قدماه. فقيل له: أتكلف هذا وقد غفر الله لك ما تقدم من ذنبك وما تأخر؟. فقال: (( أفلا أكون عبدا شكورا))."},{"num":2662,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُومُ مِنَ اللَّيْلِ حَتَّى تَتَفَطَّرَ قَدَمَاهُ، فَقَالَتْ عَائِشَةُ: لِمَ تَصْنَعُ هَذَا يَا رَسُولَ اللَّهِ، وَقَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ؟ قَالَ: أَفَلاَ أُحِبُّ أَنْ أَكُونَ عَبْدًا شَكُورًا. فَلَمَّا كَثُرَ لَحْمُهُ صَلَّى جَالِسًا، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ، فَقَرَأَ، ثُمَّ رَكَعَ."],"takhrij":"متفق عليه: رواه البخاري في تفسير سورة الفتح (4837)، ومسلم في كتاب صفة القيامة (2820) كلاهما من حديث عروة بن الزبير، عن عائشة واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب في اجتهاد النبي ﷺ في قيام الليل لرفع الدرجات وعلو المراتب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (4837) — wording; Muslim (2820) with similar wording.","chapter_en":"The Prophet’s ﷺ striving in standing at night to raise ranks and attain lofty stations.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":1,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ would stand (in prayer) at night until his feet became cracked. ‘A’ishah said: “Why do you do this, O Messenger of Allah, when Allah has forgiven for you what came before of your sin and what came after?” He said: “Should I not love to be a grateful servant?” When his flesh increased (he became heavier), he would pray sitting; and when he wanted to bow, he would stand, recite, then bow."]},"buhuth":{"en":["Her statement “until his feet became cracked” means: until they split/chapped from standing so long."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13312],"tks":"متفق عليه: رواه البخاري (4837)، ومسلم (2820) واللفظ للبخاري، ولفظ مسلم قريب منه."},{"num":2663,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يُصَلِّي حَتَّى تَرِمَ قَدَمَاهُ، قَالَ: فَقِيلَ لَهُ: أَتَفْعَلُ هَذَا وَقَدْ جَاءَكَ: أَنَّ اللَّهَ تَعَالَى قَدْ غَفَرَ لَكَ ﴿مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ﴾. [سورة الفتح: 2]؟ قَالَ: أَفَلا أَكُونُ عَبْدًا شَكُورًا."],"takhrij":"صحيح: رواه الترمذي في الشمائل (260) عن أبي عمَّار (الحسين بن حُرَيث) حدثنا الفضل بن موسى، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب في اجتهاد النبي ﷺ في قيام الليل لرفع الدرجات وعلو المراتب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Tirmidhi in al-Shama’il (260); authenticated by Ibn Khuzaymah (1184).","chapter_en":"The Prophet’s ﷺ striving in standing at night to raise ranks and attain lofty stations.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ used to pray until his feet became swollen. It was said to him: “Do you do this when it has come to you that Allah has forgiven for you what came before of your sin and what came after?” He said: “Should I not be a grateful servant?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي في الشمائل (260)، وصححه ابن خزيمة (1184)."},{"num":2664,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: قَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَوَرَّمَتْ قَدَمَاهُ، أَوْ سَاقَاهُ، فَقِيلَ: لَهُ: أَلَيْسَ قَدْ غَفَرَ اللَّهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، قَالَ: أَفَلَا أَكُونُ عَبْدًا شَكُورًا."],"takhrij":"صحيح: رواه أبو يعلى (2900) عن عبدالله بن عون الخرّاز، حدّثنا محمد بن بشر، عن مسعر بن كدام، عن قتادة، عن أنس، فذكره.","grade":"صحيح","chapter_ar":"باب في اجتهاد النبي ﷺ في قيام الليل لرفع الدرجات وعلو المراتب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Ya‘la (2900).","chapter_en":"The Prophet’s ﷺ striving in standing at night to raise ranks and attain lofty stations.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ stood (in prayer) until his feet—or his legs—became swollen. It was said: “O Messenger of Allah ﷺ, Allah has forgiven you what came before of your sin and what came after.” He said: “Should I not be a grateful servant?”"]},"buhuth":{"en":["Ibn Khuzaymah said: “In this is evidence that gratitude to Allah, Mighty and Majestic, can be by doing deeds for Him—because all gratitude belongs to Allah—and it can also be by the tongue. Allah Most High said: ‘Work, O family of Dawud, in gratitude’ (Saba’: 13), so He commanded them to work as gratitude. Thus gratitude can be by speech and by action together—not as the common people imagine, that gratitude is only by the tongue.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو يعلى (2900)."},{"num":2665,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن هِشَامٍ بن عَامِرٍ قَالَ: قُلْتُ لأم الْمُؤْمِنِينَ عَائِشَةَ: أَنْبِئِينِي عَنْ خُلُقِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَتْ: أما تَقْرَأُ الْقُرْآنَ؟ قُلْتُ: بَلَى، قَالَتْ: فَإِنَّ خُلُقَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ الْقُرْآنَ. قَالَ: فَهَمَمْتُ أَنْ أَقُومَ فبدا لِي فَقُلْتُ لَهَا: أَنْبِئِينِي عَنْ قِيَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالَتْ: أما تَقْرَأُ هَذِهِ السُّورَةِ يَا أَيُّهَا الْمُزَّمِّلُ ؟ قَالَ: قُلْتُ: بَلَى. قَالَتْ: فَإِنَّ اللَّهَ افْتَرَضَ القيام فِي أَوَّلِ هَذِهِ السُّورَةِ، فَقَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ حَوْلًا، حَتَّى انتفخت أقدامُهم، وَأَمْسَكَ اللهُ خَاتِمَتَهَا اثنى عَشَرَ شَهْرًا، ثُمَّ أَنْزَلَ اللَّهُ التَّخْفِيفَ فِي آخِرِ السُّورَةِ، فَصَارَ قِيَامُ اللَّيْلِ تَطَوُّعًا بَعْدَ فَرِيضَةٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) من طريق عبد الرزاق -وهو في مصنفه (4714) عن عمر، عن قتادة، عن زرارة بن أوفى، عن سعد ابن هشام بن عامر فذكره في حديث طويل كما سيـأتي في جامـع صلاة النبي صلى الله عليه وسلم في الليل.","grade":"صحيح","chapter_ar":"باب في نسخ قيام الليل من الفرض إلى النافلة إلا في حق النبي ﷺ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (746).","chapter_en":"The abrogation of night prayer from being obligatory to being voluntary—except in the case of the Prophet ﷺ.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":2,"content":{"translation":{"en":["Sa‘d ibn Hisham ibn ‘Amir said: I said to the Mother of the Believers ‘A’ishah: “Tell me about the character of the Messenger of Allah ﷺ.” She said: “Do you not read the Qur’an?” I said: “Yes.” She said: “Then the character of the Messenger of Allah ﷺ was the Qur’an.” He said: I intended to stand up, then I thought better of it and said to her: “Tell me about the night prayer of the Messenger of Allah ﷺ.” She said: “Do you not read this surah: O you who wraps himself (Ya ayyuhal-muzzammil)?” I said: “Yes.” She said: “Allah made standing (at night) obligatory at the beginning of this surah, so the Prophet of Allah ﷺ and his Companions stood (in night prayer) for a year, until their feet became swollen. And Allah held back its ending for twelve months; then Allah revealed the easing at the end of the surah, so night prayer became voluntary after having been obligatory.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746).."},{"num":2666,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِآيَةٍ مِنَ الْقُرْآنِ لَيْلَةً."],"takhrij":"صحيح: رواه الترمذي (448) عن أبي بكر محمد بن نافع البصري، حدثنا عبدالصمد بن عبدالوارث، عن إسماعيل بن مسلم العبدي، عن أبي المتوكِّل الناجي، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء في قيام النبي باية من القرآن ليلةً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ (as stated here)\nal-Tirmidhi (448). al-Tirmidhi said: “This hadith is hasan gharib.”","chapter_en":"What is narrated about the Prophet ﷺ standing (in prayer) with a single verse of the Qur’an for a night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ stood (in prayer) with a verse from the Qur’an for a night."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (448) قال الترمذي: (( هذا حديث حسن غريب)) ."},{"num":2667,"demo":false,"sanad":"","matn":["عن أبي ذر قال: قام النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بآية حتى أصبح يردِّدُها. والآية: ﴿إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ﴾ [سورة المائدة: 118]."],"takhrij":"حسن: رواه النسائي (1010)، وابن ماجه (1350) كلاهما من حديث يحيى بن سعيد القطان، قال: حدثنا قُدامة بن عبدالله، قال: حدثتني جَسرة بنتُ رجاجةَ، قالت: سمعتُ أبا ذر فذكره.","grade":"حسن","chapter_ar":"باب ماجاء في قيام النبي باية من القرآن ليلةً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nal-Nasa’i (1010), Ibn Majah (1350), and al-Hakim (1/241).","chapter_en":"What is narrated about the Prophet ﷺ standing (in prayer) with a single verse of the Qur’an for a night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":3,"content":{"translation":{"en":["Abu Dharr said: The Prophet ﷺ stood (in prayer) with a verse until morning, repeating it. The verse is: “If You punish them, they are Your servants; and if You forgive them, then You are the Mighty, the Wise.” (Al-Ma’idah: 118)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1010)، وابن ماجه (1350)، والحاكم (879)."},{"num":2668,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَتَهَجَّدُ قَالَ: اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ قَيِّمُ السماوات وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ لَكَ ملكُ السماوات وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ نورُ السماوات وَالأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ مالك السماوات وَالأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، ولقاءُك حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ حَقٌّ، وَالسَّاعَةُ حَقٌّ. اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قدَّمتُ وَمَا أخَّرتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، أَنْتَ المقَدِّم، وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ أنتَ لاَ إِلَهَ غَيْرُكَ .","قَالَ سُفْيَانُ: وَزَادَ عَبْدُ الْكَرِيمِ أَبُو أُمَيَّةَ: ولاحولَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ .."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1120)، ومسلم في صلاة المسافرين (769) كلاهما من حديث سفيان، عن سليمان بن أبي مسلم الأحول، عن طاوسٍ، سمع ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1120), Muslim (769).","chapter_en":"Recommended remembrance (dhikr) when rising for night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Abbas said: When the Prophet ﷺ rose at night for tahajjud, he would say: “O Allah, to You belongs all praise. You are the Sustainer of the heavens and the earth and all who are in them, and to You belongs all praise. To You belongs the dominion of the heavens and the earth and all who are in them, and to You belongs all praise. You are the Light of the heavens and the earth, and to You belongs all praise. You are the Owner of the heavens and the earth, and to You belongs all praise. You are the Truth; Your promise is true; meeting You is true; Your word is true; Paradise is true; the Fire is true; the prophets are true; Muhammad is true; and the Hour is true. O Allah, to You I submit; in You I believe; upon You I rely; to You I turn in repentance; through You I dispute; and to You I seek judgment—so forgive me what I have sent ahead and what I have left behind, what I have concealed and what I have made public. You are the One who brings forward and the One who puts back. There is no god but You; there is no god other than You.”","Sufyan said: ‘Abd al-Karim Abu Umayyah added: “And there is no might nor power except with Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11065],"tks":"متفق عليه: رواه البخاري (1120)، ومسلم (769)."},{"num":2669,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَعَارَّ مِنَ اللَّيْلِ فَقَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ. الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ. ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِي. أَوْ دَعَا، اسْتُجِيبَ، فَإِنْ تَوَضَّأَ وَصَلَّى قُبِلَتْ صَلاَتُهُ."],"takhrij":"صحيح: رواه البخاري في التهجد (1154) عن صَدَقَة بن الفضل، أخبرنا الوليد، عن الأوزاعي، قال: حدثني عُمير بن هانئ -قال: حدثني جنادةُ ابن أبي أمية، حدثني عُبادة بن الصامت فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhari (1154).","chapter_en":"Recommended remembrance (dhikr) when rising for night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":4,"content":{"translation":{"en":["‘Ubadah ibn al-Samit reported that the Prophet ﷺ said: “Whoever wakes up during the night and says: ‘There is no god but Allah alone with no partner; to Him belongs the dominion and to Him belongs praise, and He is over all things capable. Praise be to Allah. Glory be to Allah. There is no god but Allah. Allah is the Greatest. And there is no might nor power except with Allah,’ then says: ‘O Allah, forgive me,’ or makes supplication—he will be answered. And if he performs wudu’ and prays, his prayer will be accepted.”"]},"buhuth":{"en":["Al-Baghawi said: “His statement ‘ta‘arra’ (تعارّ)’ means: he woke up from sleep. The origin of ta‘arra’ is wakefulness and turning over on the bed. It is said that ta‘arra’ is only with speech and sound, taken from the ‘irar of the male ostrich—meaning its cry.” (Sharh al-Sunnah, 4/72)","Ibn al-Tin said: The apparent meaning of the hadith is that ta‘arra’ means “woke up,” because he said: “Whoever ta‘arra’ then says…” so he attached the saying to waking up."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11066,11263],"tks":"صحيح: رواه البخاري (1154)."},{"num":2670,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بن عبدالرحمن بن عَوْفٍ قَالَ: سَأَلْتُ عَائِشَةَ أُمَّ المؤمين: بأيّ شَيْءٍ كَانَ نبيُّ اللَّهِ يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنَ اللَّيْلِ؟ قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ: اللَّهُمَّ ربَّ جَبْرَائيل وَمِيكَائِيلَ وَإِسْرَافِيلَ. فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اختُلِف فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (770) من طرق عن عمر بن يونس، حدثنا عكرمة بن عمار، حدثنا يحيى بن أبي كثير، حدثني أبو سلمة بن عبدالرحمن فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (770).","chapter_en":"Recommended remembrance (dhikr) when rising for night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":4,"content":{"translation":{"en":["Abu Salamah ibn ‘Abd al-Rahman ibn ‘Awf said: I asked ‘A’ishah, the Mother of the Believers: “With what did the Prophet of Allah ﷺ begin his prayer when he stood at night?” She said: When he rose at night, he would begin his prayer with: “O Allah, Lord of Jibril, Mikail, and Israfil; Creator of the heavens and the earth; Knower of the unseen and the seen; You judge between Your servants concerning that in which they used to differ. Guide me, by Your permission, to the truth regarding that in which there is disagreement. Indeed You guide whom You will to a straight path.”"]}},"tuhfa":{},"full":1,"rep":[11067],"tks":"صحيح: رواه مسلم (770)."},{"num":2671,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ حُمَيْدٍ، قَالَ: سَأَلْتُ عَائِشَةَ: بِأَىِّ شَىْءٍ كَانَ يَفْتَتِحُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِيَامَ اللَّيْلِ؟ فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَىْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا قَامَ كَبَّرَ عَشْرًا، وَحَمِدَ اللَّهَ عَشْرًا، وَسَبَّحَ عَشْرًا، وَهَلَّلَ عَشْرًا، وَاسْتَغْفَرَ عَشْرًا، وَقَالَ: اللَّهُمَّ اغْفِرْ لِي، وَاهْدِنِي، وَارْزُقْنِي وَعَافِنِي. وَيَتَعَوَّذُ مِنْ ضِيقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أبو داود (766)، والنسائي (1618)، وابن ماجه (1356) كلّهم من حديث زيد بن الحُباب، عن معاوية بن صالح، قال: حدثني أزهر بن سعيد، عن عاصم بن حُميد فذكره.","grade":"حسن","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (766), al-Nasa’i (1618), Ibn Majah (1356).","chapter_en":"Recommended remembrance (dhikr) when rising for night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":4,"content":{"translation":{"en":["‘Asim ibn Humayd said: I asked ‘A’ishah: “With what did the Messenger of Allah ﷺ begin his night prayer?” She said: “You have asked me about something no one asked me before you. When he rose, he would say ‘Allahu Akbar’ ten times, praise Allah ten times, say ‘Subhan Allah’ ten times, say ‘La ilaha illa Allah’ ten times, and seek forgiveness ten times. And he would say: ‘O Allah, forgive me, guide me, and provide for me,’ and he would seek refuge from the tightness of standing on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11068,13693],"tks":"حسن: رواه أبو داود (766)، والنسائي (1618)، وابن ماجه (1356)."},{"num":2672,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّهُ بَاتَ لَيْلَةً عِنْدَ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهِيَ خَالَتُهُ، قـال: فَاضْطَجَعْتُ فِي عَرْضِ الْوِسَادَةِ، وَاضْطَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَهْلُهُ فِي طُولِهَا. فَنَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا انْتَصَفَ اللَّيْلُ، أَوْ قَبْلَهُ بِقَلِيلٍ أَوْ بَعْدَهُ بِقَلِيلٍ اسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَلَسَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ بِيَدِهِ ثُمَّ قَرَأَ الْعَشْرَ الآيَاتِ الْخَوَاتِمَ مِنْ سُورَةِ آلِ عِمْرَانَ وَهِيَ قوله تَعَالَى: ﴿إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ﴾ [سورة البقرة: 164] اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لِأُولِي الْأَلْبَابِ إِلَى قَوْلِهِ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اصْبِرُوا وَصَابِرُوا وَرَابِطُوا وَاتَّقُوا اللَّهَ لَعَلَّكُمْ تُفْلِحُونَ﴾. [سورة آل عمران: 200] . [سُورَةِ آلِ عِمْرَانَ: 190-200]."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (11) عن مخرمة بن سليمان، عن كريب مولى ابن عباس به في حديث طويل سيأتي في باب عدد صلاة الليل.","grade":"متفق عليه","chapter_ar":"باب قراءة العشر الآيات الخواتم من سورة آل عمران لمن قام لصلاة التهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (11), al-Bukhari (183), Muslim (182/763).","chapter_en":"Reciting the last ten verses of Surah آل عمران for the one who rises for tahajjud.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":5,"content":{"translation":{"en":["Ibn ‘Abbas said that he spent a night at the home of Maymunah, the Prophet’s ﷺ wife, and she was his maternal aunt. He said: I lay across the pillow, and the Messenger of Allah ﷺ and his family lay lengthwise along it. The Messenger of Allah ﷺ slept until midway through the night—or a little before it or a little after it—then he woke up, sat up, wiped the sleep from his face with his hand, and then recited the last ten verses of Surah Āl ʿImrān, which are Allah’s words: “Indeed, in the creation of the heavens and the earth and the alternation of the night and the day are signs for people of understanding…” up to His words: “O you who believe, be patient, and outdo others in patience, and remain stationed, and fear Allah so that you may succeed.” (Al ‘Imran: 190–200)"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (11) والبخاري (183)، ومسلم (182/763)."},{"num":2673,"demo":false,"sanad":"","matn":["عَنْ علي بن أَبِي طَالِبٍ أخبر أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَرَقَهُ وَفَاطِمَةَ بنتَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً فَقَالَ: أَلاَ تُصلِّيان؟ فَقُلْتُ: يَا رَسُولَ اللَّهِ أَنْفُسُنَا بِيَدِ اللَّهِ، فَإِذَا شَاءَ أَنْ يَبْعَثَنا بَعَثَنا. فَانْصَرَفَ حِينَ قُلْتُ ذَلِكَ وَلَمْ يَرْجِعْ إليَّ شَيْئًا، ثُمَّ سَمِعْتُهُ وَهْوَ مُوَلٍّ يَضْرِبُ فَخِذَهُ وَهْوَ يَقُولُ: ﴿وَكَانَ الْإِنْسَانُ أَكْثَرَ شَيْءٍ جَدَلًا﴾ [ سورة الْكَهْفِ: 54]."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1127)، ومسلم في صلاة المسافرين (775) كلاهما من حديث الزهري، عن علي بن الحسين، أن حسين بن علي أخبره، عن علي بن أبي طالب فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1127), Muslim (775).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn Abi Talib reported that the Messenger of Allah ﷺ came to him and to Fatimah, the daughter of the Prophet ﷺ, at night and said: “Will you not pray?” I said: “O Messenger of Allah ﷺ, our souls are in the Hand of Allah; if He wills to raise us, He will raise us.” So he turned away when I said that and did not reply to me. Then I heard him as he was leaving, striking his thigh and saying: “And man is, most of all things, argumentative.” (Al-Kahf: 54)"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1127)، ومسلم (775)."},{"num":2674,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: كَانَ الرَّجُلُ فِي حَيَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَأَى رُؤْيَا قصَّها عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فتمنَّيتُ أَنْ أَرَى رُؤْيَا فَأَقُصَّهَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وَكُنْتُ غُلاَمًا شَابًّا، وَكُنْتُ أَنَامُ فِي الْمَسْجِدِ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَيْتُ فِي النَّوْمِ كأنَّ مَلَكَيْنِ أَخَذَانِي فَذَهَبَا بِي إِلَى النَّارِ، فَإِذَا هِيَ مَطْوِيَّةٌ كطيّ الْبِئْرِ، وَإِذَا لَهَا قَرْنَانِ، وَإِذَا فِيهَا أُنَاسٌ قَدْ عَرَفْتُهُمْ فَجَعَلْتُ أَقُولُ: أَعُوذُ بِاللَّهِ مِنَ النَّارِ. قَالَ: فَلَقِيَنَا مَلَكٌ آخَرُ فَقَالَ لِي: لِم تُرَعْ. فَقَصَصْتُهَا عَلَى حَفْصَةَ، فقصَّتْها حَفْصَةُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: نِعْمَ الرَّجُلُ عبدالله لَوْ كَانَ يُصَلِّي مِنَ اللَّيْلِ . فَكَانَ بعدُ لاَ يَنَامُ مِنَ اللَّيْلِ إِلاَّ قَلِيلاً."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1121،1122)، ومسلم في كتاب فضائل الصحابة (2479) كلاهما من طريق عبد الرزاق، قال: أخبرنا معمر، عن الزهري، عن سالم، عن أبيه، فذكره. ولفظهما سواء. إلا أن مسلماً كرر: أعوذ بالله من النار -ثلاث مرات. وكذا عند البخاري أيضاً (3738) والقائل: فكان بعدُ لا ينام من الليل إلا قليلاً هو سالم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1121, 1122), Muslim (2479).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar said: In the lifetime of the Messenger of Allah ﷺ, if someone saw a dream, he would relate it to the Messenger of Allah ﷺ. I wished that I would see a dream and relate it to the Messenger of Allah ﷺ. I was a young boy, and I used to sleep in the mosque during the time of the Messenger of Allah ﷺ. I saw in a dream that two angels took me and brought me to the Fire, and it was folded like the folding of a well; it had two horns, and in it were people I recognized. I began to say: “I seek refuge with Allah from the Fire.” Then we met another angel who said to me: “Do not be afraid.” I told it to Hafsah, and Hafsah told it to the Messenger of Allah ﷺ, and he said: “What a good man ‘Abdullah is—if only he would pray at night.” After that, he would sleep only a little of the night."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1121،1122)، ومسلم (2479)."},{"num":2675,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: اسْتَيْقَظَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةً فَقَالَ: سُبْحَانَ اللَّهِ مَاذَا أُنزِل اللَّيْلَةَ مِنَ الْفِتَنِ، وَمَاذَا فُتح مِنَ الْخَزَائِنِ، مَنْ يُوقِظُ صَوَاحِبَ الْحُجُرَاتِ؟ يَا رُبَّ كَاسِيَةٍ فِي الدُّنْيَا، عَارِيَةٍ فِي الآخِرَةِ ."],"takhrij":"صحيح: رواه البخاري في التهجد (1126) عن ابن مقاتل، حدثنا عبدالله (هو ابن المبارك)، أخبرنا معمر، عن الزهري، عن هند بنت الحارث، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Bukhari (1126).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Umm Salamah said: The Prophet ﷺ woke up one night and said: “Subhan Allah! What trials have been sent down tonight, and what treasures have been opened! Who will wake the women of the chambers? Many a woman clothed in this world will be naked in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1126)."},{"num":2676,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللهِ الْمُحَرَّمُ، وَأَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ."],"takhrij":"صحيح: رواه مسلم في الصيام (1163) عن قتيبة بن سعيد، ثنا أبو عوانة، عن أبي بشر، عن حُميد بن عبدالرحمن الحِمْيري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (1163).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “The best fasting after Ramadan is the month of Allah, al-Muharram, and the best prayer after the obligatory prayer is the night prayer.”"]}},"tuhfa":{},"full":1,"rep":[4438,10718],"tks":"صحيح: رواه مسلم (1163)."},{"num":2677,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، وَأَبِي، هُرَيْرَةَ قَالاَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَيْقَظَ الرَّجُلُ أَهْلَهُ مِنَ اللَّيْلِ، فَصَلَّيَا، أَوْ صَلَّى رَكْعَتَيْنِ جَمِيعًا كُتِبَا فِي الذَّاكِرِينَ وَالذَّاكِرَاتِ."],"takhrij":"صحيح: رواه أبو داود (1309)، وابن ماجه (1335) كلاهما من طريق شيبان أبي معاوية، عن الأعمش، عن علي بن الأقمر، عن الأغرِّ، عن أبي سعيد وأبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAbu Dawud (1309), Ibn Majah (1335); authenticated by Ibn Hibban (2568) and al-Hakim (1/316).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Sa‘id and Abu Hurayrah (may Allah be pleased with them) said: The Messenger of Allah ﷺ said: “If a man wakes his family at night and they pray, or if they both pray two rak‘ahs together, they are written among the men and women who remember Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12745],"tks":"صحيح: رواه أبو داود (1309)، وابن ماجه (1335)، وقد صححه ابن حبان (2568)، والحاكم (1189)."},{"num":2678,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَحِمَ اللَّهُ رَجُلاً قَامَ مِنَ اللَّيْلِ، فَصَلَّى وَأَيْقَظَ امْرَأَتَهُ، فَإِنْ أَبَتْ نَضَحَ فِي وَجْهِهَا الْمَاءَ، رَحِمَ اللَّهُ امْرَأَةً قَامَتْ مِنَ اللَّيْلِ فَصَلَّتْ وَأَيْقَظَتْ زَوْجَهَا، فَإِنْ أَبَى نَضَحَتْ فِي وَجْهِهِ الْمَاءَ."],"takhrij":"حسن: رواه أبو داود (1308)، والنسائي (1610)، وابن ماجه (1336) كلّهم من طريق يحيى بن سعيد، عن محمد بن عجلان، قال: حدثني القعقاع بن حكيم، عن أبي صالح، عن أبي هريرة فذكره ولفظه سواء عند الجميع.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (1308), al-Nasa’i (1610), Ibn Majah (1336); authenticated by Ibn Khuzaymah (1148).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “May Allah have mercy on a man who stands at night to pray and wakes his wife; if she refuses, he sprinkles water on her face. May Allah have mercy on a woman who stands at night to pray and wakes her husband; if he refuses, she sprinkles water on his face.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12744],"tks":"حسن: رواه أبو داود (1308)، والنسائي (1610)، وابن ماجه (1336)، وصححه ابن خزيمة (1148)."},{"num":2679,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ حَافَظَ عَلَى هَؤُلَاءِ الصَّلَوَاتِ الْمَكْتُوبَاتِ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ، وَمَنْ قَرَأَ فِي لَيْلَةٍ مِائَةَ آيَّةٍ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ، أَوْ كُتِبَ مِنَ الْقَانِتِينَ."],"takhrij":"صحيح: رواه ابن خزيمة (1142)، والحاكم (1160) كلاهما من طريق أبي حمزة السكري، عن الأعمش، عن أبي صالح، عن أبي هريرة واللفظ لابن خزيمة، وأما الحاكم فرواه بدون شك وهو قوله: ومن قرأ في ليلة مائة آية كتب من القانتين . وقال: صحيح على شرط الشيخين .","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nIbn Khuzaymah (1142) (wording his), and al-Hakim (1/308).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “Whoever guards these obligatory prayers will not be written among the heedless. And whoever recites one hundred verses in a night will not be written among the heedless—or he will be written among the devoutly obedient.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11836],"tks":"صحيح: رواه ابن خزيمة (1142)، والحاكم (1160) واللفظ لابن خزيمة،."},{"num":2680,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي إِذَا رَأَيْتُكَ طَابَتْ نَفْسِي وَقَرَّتْ عَيْنِي، فَأَنْبِئْنِي عَنْ كُلِّ شَيْءٍ. فَقَالَ: كُلُّ شَيْءٍ خُلِقَ مِنْ مَاءٍ قَالَ: قُلْتُ: أَنْبِئْنِي عَنْ أَمْرٍ إِذَا أَخَذْتُ بِهِ دَخَلْتُ الْجَنَّةَ.","قال: أفْشِ السلامَ، وأَطْعِم الطعامَ، وصِلِ الأَرْحَام، وقُم بالليلِ والناسُ نِيام، ثم ادخُلِ الجنّةَ بسلامٍ ."],"takhrij":"صحيح: رواه الإمام أحمد (7932) عن يزيد بن هارون، أخبرنا هَمَّام، عن قتادة، عن أبي ميمونة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAhmad (7932); authenticated by Ibn Hibban (508, 2559) and al-Hakim (4/129).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Hurayrah said: I said, “O Messenger of Allah ﷺ, when I see you my soul feels good and my eyes find comfort. So inform me about everything.” He said: “Everything was created from water.” I said: “Tell me of an action—if I hold to it, I will enter Paradise.” He said: “Spread peace, feed food, maintain ties of kinship, and stand (in prayer) at night while the people are sleeping; then you will enter Paradise in peace.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[63,8194,12750,13660,13725,14216],"tks":"صحيح: رواه الإمام أحمد (7932)، وصححه ابن حبان (508،2559)، والحاكم (7278)."},{"num":2681,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي قيس قَالَ: قَالَتْ عَائِشَةُ رَضِيَ اللَّهِ عَنْهَا: : لاَ تدعْ قِيَامَ اللَّيْلِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يَدَعُهُ، وَكَانَ إِذَا مَرِضَ أَوْ كَسِلَ صَلَّى قَاعِدًا."],"takhrij":"حسن: رواه أبو داود (1307) عن محمد بن بشار، قال: حدثنا أبو داود، قال: حدثنا شعبةُ، عن يزيد بن خُمير قال: سمعت عبدالله بن أبي قيس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (1307).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn Abi Qays said: ‘A’ishah (may Allah be pleased with her) said: “Do not leave off the night prayer, for the Messenger of Allah ﷺ would not leave it. And when he was ill or tired, he prayed sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2754],"tks":"حسن: رواه أبو داود (1307)."},{"num":2682,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن سَلام قَالَ: لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ انْجَفَلَ النَّاسُ إِلَيْهِ، وَقِيلَ: قَدِم رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَدِم رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، قَدِم رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَجِئْتُ فِي النَّاسِ لأَنْظُرَ إِلَيْهِ، فَلَمَّا استثبتُ وجهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَفْتُ أَنَّ وَجْهَهُ لَيْسَ بِوَجْهِ كَذَّابٍ، وَكَانَ أوّلَ شيء تَكَلَّمَ بِهِ أَنْ قَالَ: أَيُّهَا النَّاسُ! أَفْشوا السَّلاَمَ، أَطْعِموا الطَّعَامَ، وصلُّوا وَالنَّاسُ نِيَامٌ، تَدْخُلُوا الْجَنَّةَ بِسَلاَمٍ ."],"takhrij":"صحيح: رواه الترمذي (2485)، وابن ماجه (1334) كلاهما من حديث يحيى بن سعيد وغيره، عن عوف بن أبي جميلة، عن زرارة بن أوفى، عن عبدالله بن سلام فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Tirmidhi (2485) (he said: “Sahih”), Ibn Majah (1334).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn Salam said: When the Messenger of Allah ﷺ arrived in Madinah, people rushed toward him, and it was said: “The Messenger of Allah has arrived! The Messenger of Allah has arrived!” I came among the people to look at him. When I looked closely at the face of the Messenger of Allah ﷺ, I knew his face was not the face of a liar. The first thing he said was: “O people! Spread peace, feed food, and pray at night while people are sleeping; you will enter Paradise in peace.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13398],"tks":"صحيح: رواه الترمذي (2485)، وابن ماجه (1334) قال الترمذي: (( صحيح))."},{"num":2683,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَالِكٍ الْأَشْعَرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ فِي الْجَنَّةِ غُرْفَةً يُرَى ظَاهِرُهَا مِنْ بَاطِنِهَا، وَبَاطِنُهَا مِنْ ظَاهِرِهَا، أَعَدَّهَا اللَّهُ لِمَنْ أَطْعَمَ الطَّعَامَ، وَأَلَانَ الْكَلَامَ، وَتَابَعَ الصِّيَامَ، وَصَلَّى وَالنَّاسُ نِيَامٌ."],"takhrij":"حسن: رواه أحمد (22905)، والطبراني في الكبير (3466) كلاهما من طريق عبد الرزاق -وهو في مصنفه (20883) عن معمر، عن يحيى ابن أبي كثير، عن ابن معانق أو أبي معانق، عن أبي مالك الأشعري فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (22905), al-Tabarani in al-Kabir (3466), and ‘Abd al-Razzaq in al-Musannaf (20883).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Malik al-Ash‘ari said: The Messenger of Allah ﷺ said: “In Paradise there is a chamber whose outside can be seen from its inside and whose inside can be seen from its outside. Allah has prepared it for the one who feeds food, softens speech, keeps up fasting, and prays while people are asleep.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12989,16276],"tks":"حسن: رواه أحمد (22905)، والطبراني في الكبير (3466) وعبد الرزاق في مصنفه (20883)."},{"num":2684,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَنْ قَامَ بِعَشْرِ آيَاتٍ لَمْ يُكْتَبْ مِنَ الْغَافِلِينَ، وَمَنْ قَامَ بِمِائَةِ آيَةٍ كُتِبَ مِنَ الْقَانِتِينَ، وَمَنْ قَامَ بِأَلْفِ آيَةٍ كُتِبَ مِنَ الْمُقَنْطَرِينَ."],"takhrij":"حسن: رواه أبو داود (1398) عن أحمد بن صالح، حدثنا ابن وهب، أخبرنا عمرو، أن أبا سَويَّة حدَّثه أنه سمع ابن حُجيرة يخبر عن عبدالله بن عمرو بن العاص فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (1398); authenticated by Ibn Khuzaymah (1144) and Ibn Hibban (2572).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: The Messenger of Allah ﷺ said: “Whoever stands (in night prayer) with ten verses will not be written among the heedless. Whoever stands with one hundred verses will be written among the devoutly obedient. And whoever stands with one thousand verses will be written among the muqantirin (those with great reward).”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11835,13189],"tks":"حسن: رواه أبو داود (1398)، وصححه ابن خزيمة (1144)، وابن حبان (2572)."},{"num":2685,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ فِي الْجَنَّةِ غُرْفَةً يُرى ظَاهِرُهَا مِنْ بَاطِنِهَا، وَبَاطِنُهَا مِنْ ظَاهِرِهَا . فَقَالَ أَبُو مُوسَى الْأَشْعَرِيُّ: لِمَنْ هِيَ يَا رَسُولَ اللَّهِ؟ قَالَ: لِمَنْ أَلانَ الْكَلَامَ، وَأَطْعَمَ الطَّعَامَ، وَبَاتَ لِلَّهِ قَائِمًا وَالنَّاسُ نِيَامٌ ."],"takhrij":"حسن: رواه أحمد (6615) عن حسن، حدثنا ابن لهيعة، حدثني حُيَي بن عبدالله، عن أبي عبدالرحمن الحُبُلي، حدَّثه عن عبدالله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (6615), al-Hakim (1/321).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr said: The Messenger of Allah ﷺ said: “In Paradise there is a chamber whose outside can be seen from its inside and whose inside can be seen from its outside.” Abu Musa al-Ash‘ari said: “For whom is it, O Messenger of Allah?” He said: “For the one who softens speech, feeds food, and spends the night standing for Allah while people are asleep.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[16275],"tks":"حسن: رواه أحمد (6615)، والحاكم (270)."},{"num":2686,"demo":false,"sanad":"","matn":["عن أَبِي ذَرٍّ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلاَثَةٌ يُحِبُّهُمُ اللَّهُ عَزَّ وَجَلَّ، وَثَلاَثَةٌ يُبْغِضُهُمُ اللَّهُ عَزَّ وَجَلَّ، أَمَّا الَّذِينَ يُحِبُّهُمُ اللَّهُ عَزَّ وَجَلَّ فَرَجُلٌ أَتَى قَوْمًا فَسَأَلَهُمْ بِاللَّهِ، عَزَّ وَجَلَّ وَلَمْ يَسْأَلْهُمْ بِقَرَابَةٍ بَيْنَهُ وَبَيْنَهُمْ فَمَنَعُوهُ، فَتَخَلَّفَهُ رَجُلٌ بِأَعْقَابِهِمْ فَأَعْطَاهُ سِرًّا لاَ يَعْلَمُ بِعَطِيَّتِهِ إِلاَّ اللَّهُ عَزَّ وَجَلَّ وَالَّذِي أَعْطَاهُ، وَقَوْمٌ سَارُوا لَيْلَتَهُمْ حَتَّى إِذَا كَانَ النَّوْمُ أَحَبَّ إِلَيْهِمْ مِمَّا يُعْدَلُ بِهِ نَزَلُوا فَوَضَعُوا رُءُوسَهُمْ فَقَامَ يَتَمَلَّقُنِي وَيَتْلُو آيَاتِي، وَرَجُلٌ كَانَ فِي سَرِيَّةٍ فَلَقُوا الْعَدُوَّ، فَهُزِمُوا فَأَقْبَلَ بِصَدْرِهِ حَتَّى يُقْتَلَ أَوْ يَفْتَحَ اللَّهُ لَهُ، وَالثَّلاَثَةُ الَّذِينَ يُبْغِضُهُمُ اللَّهُ عَزَّ وَجَلَّ: الشَّيْخُ الزَّانِي وَالْفَقِيرُ الْمُخْتَالُ، وَالْغَنِيُّ الظَّلُومُ."],"takhrij":"حسن: روا النسائي (2570)، والترمذي (2568) كلاهما عن محمد بن المثنى، حدثنا محمد بن جعفر، حدثنا شعبة، عن منصور بن المعتمر قال: سمعت ربعي بن حِراش يحدث عن زيد بن ظبيان يرفعه إلى أبي ذر فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nal-Nasa’i (2570), al-Tirmidhi (2568), Ibn Khuzaymah (2456, 2564), Ibn Hibban (3350). al-Tirmidhi said: “This hadith is sahih.”","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Dharr reported that the Prophet ﷺ said: “Three are loved by Allah, Mighty and Majestic, and three are hated by Allah, Mighty and Majestic. As for those whom Allah loves: (1) A man who came to some people and asked them by Allah (i.e., for Allah’s sake), and did not ask them because of any kinship between him and them—yet they refused him; then a man stayed behind them and gave him secretly, and none knows of his gift except Allah, Mighty and Majestic, and the one who gave it. (2) A group who traveled through the night until sleep became more beloved to them than anything comparable, so they stopped and laid their heads down; then a man stood up, humbling himself before Me and reciting My verses. (3) A man who was in a detachment that met the enemy; they fled, but he advanced with his chest forward until he is killed—or Allah grants him victory. And the three whom Allah hates: an old man who commits zina, a poor person who is arrogant, and a rich person who is oppressive.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (2570)، والترمذي (2568)، وابن خزيمة (2456، 2564)، وابن حبان ( 3350)."},{"num":2687,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ الْبَاهِلِيِّ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ: عَلَيْكُمْ بِقِيَامِ اللَّيْلِ، فَإِنَّهُ دَأْبُ الصَّالِحِينَ قَبْلَكُمْ، وَهُوَ قُرْبَةٌ لَكُمْ إِلَى رَبِّكُمْ، وَمُكَفِّرَةٌ لِلسَّيِّئَاتِ، وَمَنْهَاةٌ عَنِ الْإِثْمِ."],"takhrij":"حسن: رواه ابن خزيمة (1135)، والحاكم (1156) وعنه البيهقي (4648) كلهم من طريق عبدالله بن صالح، قال: حدثني معاوية بن صالح، عن ثور بن يزيد، عن أبي إدريس الخولاني، عن أبي أمامة الباهلي فذكره. غير أن ابن خزيمة قال: ربيعة بن يزيد.","grade":"حسن","chapter_ar":"باب ما جاء في الحثّ على قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nIbn Khuzaymah (1135), al-Hakim (1/308) (and al-Bayhaqi narrated it from him: 2/502).","chapter_en":"What has been narrated encouraging the night prayer (qiyām al-layl).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":6,"content":{"translation":{"en":["Abu Umamah reported that the Messenger of Allah ﷺ said: “Hold fast to standing in prayer at night, for it was the practice of the righteous before you. It is a means of drawing near to your Lord, an expiation for bad deeds, and a restraint from sin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة (1135)، والحاكم (1156) وعنه البيهقي (4648)."},{"num":2688,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: قـــــــال لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا عبدالله، لاَ تَكُنْ مثلَ فُلاَنٍ كَانَ يَقُومُ من اللَّيْلَ فَتَرَكَ قِيَامَ اللَّيْلِ ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1152) من طريق مبشر، وعبدالله بن المبارك، كلاهما عن الأوزاعي، حدثنا يحيى بن أبي كثير، قال: حدثني أبو سلمة بن عبدالرحمن، حدثني عبدالله بن عمرو بن العاص فذكره.","grade":"متفق عليه","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Muttafaq ‘alayh)\nal-Bukhari (1152), Muslim (in the Book of Fasting: 1159).","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As reported: The Messenger of Allah ﷺ said to me: “O ‘Abdullah, do not be like so-and-so; he used to stand (in prayer) at night, then he abandoned the night prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1152)، ومسلم (في الصيام 185/1159) ."},{"num":2689,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: ذُكر عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقِيلَ: مَا زَالَ نَائِمًا حَتَّى أَصْبَحَ، مَا قَامَ إِلَى الصَّلاَةِ. فَقَالَ: ذَاكَ رَجُلٌ بَالَ الشَّيْطَانُ فِي أُذُنِه - أَوْ قَالَ: فِي أذُنَيه ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1144)، ومسلم في صلاة المسافرين (774) كلاهما من طريق منصور، عن أبي وائل، عن عبدالله بن مسعود فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Muttafaq ‘alayh)\nal-Bukhari (1144), Muslim (774).","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud reported: A man was mentioned in the presence of the Messenger of Allah ﷺ, and it was said: “He kept sleeping until morning—he did not get up for prayer.” He ﷺ said: “That is a man in whose ear the devil has urinated”—or he said: “in his two ears.”"]},"buhuth":{"en":["His statement, “he did not get up for prayer,” may refer to the night prayer, and it may also refer to the obligatory Fajr prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري ( 1144)، ومسلم (774)."},{"num":2690,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَعْقِدُ الشَّيْطَانُ عَلَى قَافِيَةِ رَأْسِ أَحَدِكُمْ إِذَا هُوَ نَامَ ثَلاَثَ عُقَدٍ، يَضْرِبُ كُلَّ عُقْدَةٍ: عَلَيْكَ لَيْلٌ طَوِيلٌ فَارْقُدْ، فَإِنِ اسْتَيْقَظَ فَذَكَرَ اللَّهَ انْحَلَّتْ عُقْدَةٌ، فَإِنْ تَوَضَّأَ انْحَلَّتْ عُقْدَةٌ، فَإِنْ صَلَّى انْحَلَّتْ عُقْدَةٌ. فَأَصْبَحَ نَشِيطًا طَيِّبَ النَّفْسِ، وَإِلاَّ أَصْبَحَ خَبِيثَ النَّفْسِ كَسْلاَنَ."],"takhrij":"متفق عليه: رواه مالك في قصر الصلاة (95) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon (Muttafaq ‘alayh)\nMalik (95), al-Bukhari (1142), Muslim (776). In Muslim’s wording: “If he performs wudu’, two knots are undone; and if he prays, the knots are undone.”","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["Abu Hurayrah reported that the Messenger of Allah ﷺ said: “When one of you sleeps, the devil ties three knots at the back of his head. At each knot he strikes and says: ‘You have a long night, so sleep.’ If he wakes and remembers Allah, one knot is undone. If he performs wudu’, another knot is undone. If he prays, all his knots are undone, and he awakens energetic and in good spirits; otherwise, he awakens in a foul mood and lazy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (95)، والبخاري (1142)، ومسلم (776) وفيه: (( وإذا توضأ انحلت عقدتان. فإذا صلى انحلت العقد))."},{"num":2691,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ ذَكَرٍ وَلَا أُنْثَى، إِلَّا وَعَلَى رَأْسِهِ جَرِيرٌ مَعْقُودٌ ثَلَاثَ عُقَدٍ، حِينَ يَرْقُدُ، فَإِنْ اسْتَيْقَظَ فَذَكَرَ اللهَ، انْحَلَّتْ عُقْدَةٌ، فَإِذَا قَامَ فَتَوَضَّأَ، انْحَلَّتْ عُقْدَةٌ، فَإِذَا قَامَ إِلَى الصَّلَاةِ، انْحَلَّتْ عُقَدُهُ كُلُّهَا."],"takhrij":"صحيح: رواه الإمام أحمد (14387) عن أبي معاوية، حدثنا الأعمش، عن أبي سفيان، عن جابر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abdullah reported: The Messenger of Allah ﷺ said: “There is no male or female except that when he (or she) sleeps, a cord is tied on the head with three knots. If one awakens and remembers Allah, a knot is undone. If one gets up and performs wudu’, a knot is undone. If one stands for prayer, all the knots are undone.”"]},"buhuth":{"en":["Ahmad (14387). Also narrated by Ibn Khuzaymah (1133) and by Ibn Hibban (2554) through him, with wording: “A cord is tied on his head when he sleeps; if he awakens and remembers Allah, a knot is undone; if he gets up and performs wudu’ and prays, the knots are undone.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (14387). ورواه ابن خزيمة (1133) وعنه ابن حبان (2554) وفيه: (( على رأسه جرير معقود حين يرقد، فإن استيقظ فذكر الله انحلت عقدة، فإذا قام فتوضأ وصلى انحلت العقد ))."},{"num":2692,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: رَجُلَانِ مِنْ أُمَّتِي يَقُومُ أَحَدُهُمَا مِنَ اللَّيْلَ يُعَالِجُ نَفْسَهُ إِلَى الطَّهُورِ، وَعَلَيْهِ عُقَدٌ فَيَتَوَضَّأُ، فَإِذَا وَضَّأَ يَدَيْهِ انْحَلَّتْ عُقْدَةٌ، وَإِذَا وَضَّأَ وَجْهَهُ انْحَلَّتْ عُقْدَةٌ، وَإِذَا مَسَحَ بِرَأْسِهِ انْحَلَّتْ عُقْدَةٌ، وَإِذَا وَضَّأَ رِجْلَيْهِ انْحَلَّتْ عُقْدَةٌ، فَيَقُولُ اللَّهُ لِلَّذِينَ وَرَاءَ الْحِجَابِ: انْظُرُوا إِلَى عَبْدِي هَذَا يُعَالِجُ نَفْسَهُ يَسْأَلُنِي، مَا سَأَلَنِي عَبْدِي فَهُوَ لَهُ."],"takhrij":"صحيح: رواه الإمام أحمد (17790) عن هارون، قال: حدثنا عبدالله بن وهب، عن عمرو بن الحارث، أن أبا عُشَّانة حدَّثه، أنه سمع عقبة بن عامر فذكر الحديث وصحّحه ابن حبان (2555) ورواه عن طريق ابن وهب به مثله.","grade":"صحيح","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nAhmad (17790); authenticated by Ibn Hibban (2555).","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir reported: I heard the Messenger of Allah ﷺ say: “Two men from my Ummah—one of them stands at night struggling with himself to reach purification while knots are upon him, so he performs wudu’. When he washes his hands, a knot is undone; when he washes his face, a knot is undone; when he wipes his head, a knot is undone; and when he washes his feet, a knot is undone. Then Allah says to those behind the veil: ‘Look at this servant of Mine—he is struggling with himself, asking Me; whatever My servant asks of Me is his.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد ( 17790)، وصححه ابن حبان ( 2555)."},{"num":2693,"demo":false,"sanad":"","matn":["عَنِ السَّائِبِ بْنِ يَزِيدَ، أَنَّ شُرَيْحًا الْحَضْرَمِيَّ، ذُكِرَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: ذَاكَ رَجُلٌ لَا يَتَوَسَّدُ الْقُرْآنَ."],"takhrij":"صحيح: رواه النسائي (1873) عن سويد بن نصر، قال: حدثنا عبدالله، قال: أنبأنا يونس، عن الزهري، قال: أخبرني السائب بن يزيد، فذكره.","grade":"صحيح","chapter_ar":"باب في ذمّ من ترك قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1873), Ahmad (15724), and al-Tabarani in al-Kabir (7/176). Ahmad’s wording is: “That is a man who does not use the Qur’an as a pillow.”","chapter_en":"Condemning the one who abandons the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":7,"content":{"translation":{"en":["Al-Sa’ib ibn Yazid reported that Shurayh al-Hadrami was mentioned in the presence of the Messenger of Allah ﷺ, so he said: “He does not use the Qur’an as a pillow.”"]},"buhuth":{"en":["His statement, “He does not use the Qur’an as a pillow,” with “the Qur’an” in the accusative as the direct object, means: he does not place the Qur’an under his head and sleep on it. Rather, he stands in night prayer with what he has of the Qur’an, maintaining its recitation. In it is a criticism of the one who treats the Qur’an like a pillow and becomes heedless of night prayer and tahajjud."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1873)، وأحمد (15724)، والطبراني في الكبير (7/176)، ولفظ أحمد: (( ذاك رجل لا يتوسد القرآن ))."},{"num":2694,"demo":false,"sanad":"","matn":["عن سَعْدِ بن هِشَامٍ بن عَامِرٍ أَرَادَ أَنْ يَغْزُوَ فِي سَبِيلِ اللَّهِ، فَقَدِمَ الْمَدِينَةَ. فَأَرَادَ أَنْ يَبِيعَ عَقَارًا لَهُ بِهَا، فَيَجْعَلَهُ فِي السِّلَاحِ وَالْكُرَاعِ، وَيُجَاهِدَ الرُّومَ حَتَّى يَمُوتَ، فَلَمَّا قَدِمَ الْمَدِينَةَ لَقِيَ أُنَاسًا مِنْ أَهْلِ الْمَدِينَةِ، فَنَهَوْهُ عَنْ ذَلِكَ، وَأَخْبَرُوهُ أَنَّ رَهْطًا سِتَّةً أَرَادُوا ذَلِكَ فِي حَيَاةِ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَهَاهُمْ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ: أَلَيْسَ لَكُمْ فِيَّ أُسْوَةٌ؟ فَلَمَّا حَدَّثُوهُ بِذَلِكَ رَاجَعَ امْرَأَتَهُ وَقَدْ كَانَ طَلَّقَهَا وَأَشْهَدَ عَلَى رَجْعَتِهَا، فَأَتَى ابْنَ عَبَّاسٍ، فَسَأَلَهُ عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ ابْنُ عَبَّاسٍ: أَلَا أَدُلُّكَ عَلَى أَعْلَمِ أَهْلِ الْأَرْضِ بِوِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَنْ؟ قَالَ: عَائِشَةُ، فَأْتِهَا فَاسْأَلْهَا، ثُمَّ ائْتِنِي فَأَخْبِرْنِي بِرَدِّهَا عَلَيْكَ. فَانْطَلَقْتُ إِلَيْهَا، فَأَتَيْتُ عَلَى حَكِيمِ بْنِ أَفْلَحَ، فَاسْتَلْحَقْتُهُ إِلَيْهَا، فَقَالَ: مَا أَنَا بِقَارِبِهَا، لِأَنِّي نَهَيْتُهَا أَنْ تَقُولَ فِي هَاتَيْنِ الشِّيعَتَيْنِ شَيْئًا، فَأَبَتْ فِيهِمَا إِلَّا مُضِيًّا. قَالَ: فَأَقْسَمْتُ عَلَيْهِ فَجَاءَ، فَانْطَلَقْنَا إِلَى عَائِشَةَ، فَاسْتَأْذَنَّا عَلَيْهَا، فَأَذِنَتْ لَنَا، فَدَخَلْنَا عَلَيْهَا، فَقَالَتْ: أَحَكِيمٌ؟ فَعَرَفَتْهُ، فَقَالَ: نَعَمْ. فَقَالَتْ: مَنْ مَعَكَ؟ قَالَ: سَعْدُ بْنُ هِشَامٍ. قَالَتْ: مَنْ هِشَامٌ؟ قَالَ: ابْنُ عَامِرٍ، فَتَرَحَّمَتْ عَلَيْهِ، وَقَالَتْ خَيْرًا - قَالَ قَتَادَةُ: وَكَانَ أُصِيبَ يَوْمَ أُحُدٍ - فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، أَنْبِئِينِي عَنْ خُلُقِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: أَلَسْتَ تَقْرَأُ الْقُرْآنَ؟ قُلْتُ: بَلَى. قَالَتْ: فَإِنَّ خُلُقَ نَبِيِّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ الْقُرْآنَ. قَالَ: فَهَمَمْتُ أَنْ أَقُومَ، وَلَا أَسْأَلَ أَحَدًا عَنْ شَيْءٍ حَتَّى أَمُوتَ، ثُمَّ بَدَا لِي، فَقُلْتُ: أَنْبِئِينِي عَنْ قِيَامِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: أَلَسْتَ تَقْرَأُ: ﴿يَا أَيُّهَا الْمُزَّمِّلُ﴾؟ قُلْتُ: بَلَى. قَالَتْ: فَإِنَّ اللَّهَ عَزَّ وَجَلَّ افْتَرَضَ قِيَامَ اللَّيْلِ فِي أَوَّلِ هَذِهِ السُّورَةِ، فَقَامَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابُهُ حَوْلًا، وَأَمْسَكَ اللهُ خَاتِمَتَهَا اثْنَيْ عَشَرَ شَهْرًا فِي السَّمَاءِ، حَتَّى أَنْزَلَ اللَّهُ فِي آخِرِ هَذِهِ السُّورَةِ التَّخْفِيفَ، فَصَارَ قِيَامُ اللَّيْلِ تَطَوُّعًا بَعْدَ فَرِيضَةٍ. قَالَ: قُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، أَنْبِئِينِي عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ، وَطَهُورَهُ، فَيَبْعَثُهُ اللهُ مَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ وَيَتَوَضَّأُ، وَيُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ، فَيَذْكُرُ اللهَ وَيَحْمَدُهُ وَيَدْعُوهُ. ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ، ثُمَّ يَقُومُ فَيُصَلِّي التَّاسِعَةَ، ثُمَّ يَقْعُدُ فَيَذْكُرُ اللهَ وَيَحْمَدُهُ وَيَدْعُوهُ، ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنَا، ثُمَّ يُصَلِّي رَكْعَتَيْنِ بَعْدَمَا يُسَلِّمُ وَهُوَ قَاعِدٌ. فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً يَا بُنَيَّ. فَلَمَّا أَسَنَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَخَذَ اللَّحْمَ، أَوْتَرَ بِسَبْعٍ، وَصَنَعَ فِي الرَّكْعَتَيْنِ مِثْلَ صَنِيعِهِ الْأَوَّلِ، فَتِلْكَ تِسْعٌ يَا بُنَيَّ. وَكَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَحَبَّ أَنْ يُدَاوِمَ عَلَيْهَا، وَكَانَ إِذَا غَلَبَهُ نَوْمٌ أَوْ وَجَعٌ عَنْ قِيَامِ اللَّيْلِ صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً. وَلَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا صَلَّى لَيْلَةً إِلَى الصُّبْحِ، وَلَا صَامَ شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ. قَالَ: فَانْطَلَقْتُ إِلَى ابْنِ عَبَّاسٍ فَحَدَّثْتُهُ بِحَدِيثِهَا، فَقَالَ: صَدَقَتْ. لَوْ كُنْتُ أَقْرَبُهَا، أَوْ أَدْخُلُ عَلَيْهَا، لَأَتَيْتُهَا حَتَّى تُشَافِهَنِي بِهِ. قَالَ: قُلْتُ: لَوْ عَلِمْتُ أَنَّكَ لَا تَدْخُلُ عَلَيْهَا مَا حَدَّثْتُكَ حَدِيثَهَا.","وفي رواية قَالَ: انْطَلَقْتُ إِلَى عبدالله بْنِ عَبَّاسٍ، فَسَأَلْتُهُ عَنِ الْوِتْرِ؟ ـ وَسَاقَ الْحَدِيثَ بِقِصَّتِهِ ـ وَقَالَ فِيهِ: قَالَتْ: مَنْ هِشَامٌ؟ قُلْتُ: ابْنُ عَامِرٍ، قَالَتْ: نِعْمَ الْمَرْءُ كَانَ عَامِرٌ، أُصِيبَ يَوْمَ أُحُدٍ .."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) عن محمد بن المثنى ، حدثنا محمد بن أبي عدي، عن سعيد، عن قتادة، عن زُرارة، أن سعد بن هشام بن عامر أراد فذكره.","grade":"صحيح","chapter_ar":"باب جامع صلاة النبي في الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (746).","chapter_en":"A comprehensive description of the Prophet’s ﷺ night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":8,"content":{"translation":{"en":["Sa‘d ibn Hisham ibn ‘Amir wanted to go out to fight in the cause of Allah. So he came to Madinah and wanted to sell some property there, to spend it on weapons and riding-beasts, and to fight the Romans until he died. When he arrived in Madinah, he met some people from the people of Madinah who forbade him from doing that. They informed him that a group of six men had intended the same thing during the lifetime of the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ forbade them and said: “Is there not for you an example in me?” When they told him that, he took back his wife—whom he had divorced—and had witnesses to her return. Then he went to Ibn ‘Abbas and asked him about the Witr of the Messenger of Allah ﷺ. Ibn ‘Abbas said: “Shall I direct you to the one who is the most knowledgeable of the people of the earth about the Witr of the Messenger of Allah ﷺ?” He said: “Who?” He said: “’A’ishah. So go to her and ask her, then come back to me and tell me what she answers you.” He said: So I went to her, and I came upon Hakim ibn Aflah and asked him to accompany me to her. He said: “I will not approach her, because I forbade her from speaking about those two groups (two factions), but she insisted on continuing.” He said: I swore to him, so he came. We went to ‘A’ishah and asked permission to enter; she gave us permission. We entered upon her and she said: “Hakim?”—and she recognized him. He said: “Yes.” She said: “Who is with you?” He said: “Sa‘d ibn Hisham.” She said: “Who is Hisham?” He said: “The son of ‘Amir.” So she asked Allah’s mercy for him and spoke well of him—Qatadah said: and he was martyred on the Day of Uhud. I said: “O Mother of the Believers, inform me about the character of the Messenger of Allah ﷺ.” She said: “Do you not read the Qur’an?” I said: “Yes.” She said: “Then the character of the Prophet of Allah ﷺ was the Qur’an.” He said: I was about to stand up and not ask anyone about anything until I died, then it occurred to me and I said: “Inform me about the night standing (qiyam) of the Messenger of Allah ﷺ.” She said: “Do you not read: (يَا أَيُّهَا الْمُزَّمِّلُ)?” I said: “Yes.” She said: “Allah, Mighty and Majestic, made standing (in prayer at night) obligatory at the beginning of this surah; so the Prophet of Allah ﷺ and his companions stood for a year, and Allah withheld its ending for twelve months [in the heaven] until Allah, Mighty and Majestic, revealed the easing at the end of the surah—so night prayer became voluntary after having been an obligation.” He said: I said: “O Mother of the Believers, inform me about the Witr of the Messenger of Allah ﷺ.” She said: “We used to prepare his siwak and his water for purification. Then Allah would awaken him whenever He willed—or awaken him—from the night. He would use the siwak, make wudu’, and pray nine rak‘ahs. He would not sit in them except in the eighth; he would mention Allah and praise Him [and supplicate], then he would rise without saying salam; then he would stand and pray the ninth; then he would sit and mention Allah and praise Him and supplicate; then he would give salam with a salutation that we could hear. Then he would pray two rak‘ahs after giving salam while sitting—so that is eleven rak‘ahs, my son. When the Messenger of Allah ﷺ grew older and his body took on flesh, he performed Witr with seven, and he did in the two rak‘ahs (after it) as he used to do before; so that is nine, my son. And the Prophet of Allah ﷺ, when he prayed a prayer, he loved to remain consistent upon it. And when sleep or pain overcame him from standing at night, he would pray twelve rak‘ahs by day. And I do not know that the Prophet of Allah ﷺ ever recited the whole Qur’an in a single night, nor that he prayed an entire night until morning, nor that he fasted a complete month other than Ramadan.” He said: I went to Ibn ‘Abbas and told him her hadith. He said: “She spoke the truth. If I could go to her, or enter upon her, I would go to her so that she could tell it to me directly.” I said: “If I had known you would not enter upon her, I would not have told you her narration.” And in another narration he said: “I went to ‘Abdullah ibn ‘Abbas and asked him about Witr …” and he related the hadith with its story; and in it: she said, “Who is Hisham?” I said, “The son of ‘Amir.” She said: “What an excellent man ‘Amir was; he was martyred on the Day of Uhud.”"]},"buhuth":{"en":["And Abu Dawud narrated it (1343), and in it: He used to pray eight rak‘ahs, not sitting in them except at the eighth; then he would sit, remember Allah, and supplicate; then he would give salam that we could hear; then he would pray two rak‘ahs while sitting after giving salam; then he would pray one rak‘ah—so that is eleven rak‘ahs.","But what is in Sahih Muslim is that he did not give salam at the eighth; rather, he prayed the ninth, then gave salam, then prayed two rak‘ahs while sitting—so that is eleven rak‘ahs. So it may be that he did this at one time and that at another time.","Her statement, “Then he would pray two rak‘ahs after giving salam while sitting,” may indicate he did that once or twice—or multiple times—to show the permissibility of praying after Witr and to show the permissibility of voluntary prayer while sitting; and some scholars held this view."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2695,"demo":false,"sanad":"","matn":["اللهِ بْنِ عَبَّاسٍ، قَالَ: قَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ فِي بُرْدٍ لَهُ حَضْرَمِيٍّ مُتَوَشِّحًا بِهِ، مَا عَلَيْهِ غَيْرُهُ."],"takhrij":"حسن: أخرجه الإمام أحمد (2384) عن يعقوب، ثنا أبي، عن ابن إسحاق حدّثني سلمة بن كُهَيل الحضرمي، ومحمد بن الوليد بن نويفع مولى آل الزبير، كلاهما حدّثني عن كُرَيبٍ مولى عبدالله بن عبَّاسٍ، عن عبدالله بن عبَّاسٍ فذكره.","grade":"حسن","chapter_ar":"باب التزين لقيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAhmad (2384); and it was authenticated by Ibn Hibban (2570).","chapter_en":"Adorning oneself for the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":9,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: “I saw the Messenger of Allah ﷺ praying at night in a Hadrami cloak (burd), wrapped around himself (mutawashshiḥan bihi), with nothing else on him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: أخرجه الإمام أحمد (2384)، وصححه ابن حبان (2570)."},{"num":2696,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهُ ا: أي الْعَمَلِ كَانَ أحبَّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ قَالَتِ: الدَّائِمُ، قُلْتُ: مَتَى كَانَ يَقُومُ؟ قَالَتْ: إِذَا سَمِعَ الصَّارِخَ قَامَ فصَلَّى."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1132)، ومسلم في صلاة المسافرين (741) كلاهما من طريق أبي الأحوص، عن الأشعث، عن أبيه، عن مسروق فذكره.","grade":"متفق عليه","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1132) and Muslim (741).","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["Masruq said: I asked ‘A’ishah (may Allah be pleased with her): “Which deed was most beloved to the Prophet ﷺ?” She said: “The one done consistently.” I said: “When would he stand (for prayer)?” She said: “When he heard the crier, he would stand and pray.”"]},"buhuth":{"en":["Regarding the phrase “the crier”: al-Nawawi said: “Here it means the rooster, by agreement of the scholars. They said it was called that because of its frequent crowing.” End.","And al-Hafiz said: “The cry (al-sarkhah) is a loud shout, and it is customary that the rooster crows around the middle of the night most often.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1132)، ومسلم (741)."},{"num":2697,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: مَا أَلْفَاهُ السَّحَرُ عِنْدِي إِلاَّ نَائِمًا. تَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1133) عن موسى بن إسماعيل، قال: حدثنا إبراهيم بن سعد، قال: ذكر أبي، عن أبي سلمة، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1133), and Muslim (742). In Muslim’s wording: She said: “I never found the Messenger of Allah ﷺ at the upper sahar in my house—or with me—except that he was sleeping.”","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah said: “I never found him at the time of sahar with me except that he was sleeping”—meaning the Prophet ﷺ."]},"buhuth":{"en":["“Upper sahar” refers to the end of the night just before dawn. And “I never found him” (ma alfaytuhu—with the letter fa) means: I never encountered him / I never saw him in that state."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1133)، ورواه مسلم (742) وفيه: قالت: ما ألفى رسول الله ﷺ السحر الأعلى في بيتي، أو عندي إلا نائما."},{"num":2698,"demo":false,"sanad":"","matn":["عَنْ الأسود بن يَزِيدَ قَالَ: سَأَلْتُ عَائِشَةُ رَضِيَ اللَّهُ عَنْهُ ا: كَيْفَ كَانَتْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ قَالَتْ: كَانَ يَنَامُ أَوَّلَه، وَيُحْيِي آخِرَهُ، ثُمَّ إِنْ كَانَتْ لَهُ حَاجَةٌ إِلَى أَهْلِهِ قَضَى حَاجَتَهُ، ثُمَّ يَنَامُ. فَإِذَا كَانَ عِنْدَ النِّدَاءِ الْأَوَّلِ وَثَبَ فَأَفَاضَ عَلَيْهِ الْمَاءَ، وَإِنْ لَمْ يَكُنْ جُنباً تَوَضَّأَ وَضوءَ الرَّجُلِ لِلصَّلاةِ ثُمَّ صلَّى الرَّكْعَتَيْنِ.","وفي رواية: كَانَ رَسُولُ اللهِ صلى الله عليه وسلم يُصَلِّي مِنَ اللَّيْلِ حَتَّى يَكُونَ آخِرَ صَلَاتِهِ الْوِتْرُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (739) من طريق أبي إسحاق، قال: سألت الأسود بن يزيد عما حدَّثتْه عائشة عن صلاة رسول الله صلى الله عليه وسلم فذكرته.","grade":"صحيح","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nMuslim (739).","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: I asked ‘A’ishah (may Allah be pleased with her): “How was the prayer of the Messenger of Allah ﷺ at night?” She said: “He would sleep at its beginning and keep awake at its end. Then if he had a need with his family, he fulfilled his need, then he would sleep. When it was at the first call (of the night), if he had become junub, he would pour water over himself (ghusl). If he was not junub, he would make wudu’ like the wudu’ of a man for prayer, then he would pray the two rak‘ahs.”","And in a narration: “The Messenger of Allah ﷺ would pray at night until the last of his prayer was Witr.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (739)."},{"num":2699,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: إِنْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيُوقِظُهُ اللَّهُ عَزَّ وَجَلَّ بِاللَّيْلِ، فَمَا يَجِيءُ السَّحَرُ حَتَّى يَفْرُغَ مِنْ حِزْبِهِ."],"takhrij":"حسن: رواه أبو داود (1316) عن حسين بن يزيد الكوفيّ، حدّثنا حفص، عن هشام بن عروة، عن أبيه، عن عائشة، فذكرته.","grade":"حسن","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ḥasan\nAbu Dawud (1316).","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: “If Allah—Mighty and Majestic—awakened the Messenger of Allah ﷺ at night, then the time of sahar would not come until he had finished his portion (ḥizb).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1316)."},{"num":2700,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: مَا كُنَّا نَشَاءُ أَنْ نَرَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي اللَّيْلِ مُصَلِّيًا إِلاَّ رَأَيْنَاهُ، وَلاَ نَشَاءُ أَنْ نَرَاهُ نَائِمًا إِلاَّ رَأَيْنَاهُ."],"takhrij":"صحيح: رواه النسائي (1628) عن إسحاق بن إبراهيم، قال: حدثنا يزيد، عن حُميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["Anas ibn Malik said: “We would not wish to see the Messenger of Allah ﷺ at night praying except that we would see him; and we would not wish to see him sleeping except that we would see him.”"]},"buhuth":{"en":["al-Nasa’i (1628). This is an abridgment. Its full source basis is in Sahih al-Bukhari (1141) from Humayd, who heard Anas say: “The Messenger of Allah ﷺ would break his fast during a month until we thought he would not fast any of it; and he would fast until we thought he would not break his fast at all. And we would not wish to see him at night praying except that we would see him, and not sleeping except that we would see him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1628) وهذا مختصر، وأصله في صحيح البخاري (1141) عن حميد أنه سمع أنسا يقول: كان رسول الله ﷺ يفطر من الشهر حتى نظن أن لا يصوم منه، ويصوم حتى نظن أن لا يفطر منه شيئا، وكان لا نشاء أن نراه من الليل مصليا إلا رأيته، ولا نائما إلا رأيته."},{"num":2701,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: قُلْتُ وَأَنَا فِي سَفَرٍ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : وَاللَّهِ لأَرْقُبَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِصَلاَةٍ حَتَّى أَرَى فِعلَه، فَلَمَّا صَلَّى صَلاَةَ الْعِشَاءِ وَهِيَ الْعَتَمَةُ اضْطَجَعَ هَوِيًّا مِنَ اللَّيْلِ، ثُمَّ اسْتَيْقَظَ فَنَظَرَ فِي الأُفُقِ فَقَالَ: رَبَّنَا مَا خَلَقْتَ هَذَا بَاطِلًا... حَتَّى بَلَغَ: إِنَّكَ لَا تُخْلِفُ الْمِيعَادَ [سورة آلِ عِمْرَانَ: 191-194] ثُمَّ أَهْوَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى فِرَاشِهِ، فاستلَّ مِنْهُ سِوَاكًا، ثُمَّ أَفْرَغَ فِي قَدَحٍ مِنْ إِدَاوَةٍ عِنْدَهُ ماءً، فاستنَّ، ثُمَّ قَامَ فصَلَّى حَتَّى قُلْتُ: قَدْ صَلَّى قَدْرَ مَا نَامَ، ثُمَّ اضْطَجَعَ حَتَّى قُلْتُ: قَدْ نَامَ قَدْرَ مَا صَلَّى، ثُمَّ اسْتَيْقَظَ فَفَعَلَ كَمَا فَعَلَ أوَّل مرّة، وَقَالَ مِثْلَ مَا قَالَ: فَفَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثَ مَرَّاتٍ قَبْلَ الْفَجْرِ."],"takhrij":"صحيح: رواه النسائي في قيام الليل (1627) عن محمد بن مسلمة، حدثنا ابن وهب، عن يونس، عن ابن شهاب، قال: حدثني حُميد بن عبدالرحمن بن عوف أن رجلاً من أصحاب النبي صلى الله عليه وسلم قال فذكره.","grade":"صحيح","chapter_ar":"باب قيام النبي في أوقات مختلفة من الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Ṣaḥīḥ\nal-Nasa’i (1627); also in ‘Amal al-Yawm wa’l-Laylah (307); and in al-Sunan al-Kubra (10066).","chapter_en":"The Prophet صلى الله عليه وسلم standing (for prayer) at different times of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":10,"content":{"translation":{"en":["A man from the Companions of the Prophet ﷺ said: I said—while I was traveling with the Messenger of Allah ﷺ—“By Allah, I will watch the Messenger of Allah ﷺ in prayer until I see what he does.” After he prayed the ‘Isha’ prayer (which is al-‘atamah), he lay down for a part of the night. Then he awoke and looked toward the horizon and said: “Our Lord, You did not create this in vain…” until he reached: “…indeed, You do not fail in Your promise.” [Surah Al ‘Imran: 191–194]. Then the Messenger of Allah ﷺ returned to his bed, pulled out a siwak from it, poured water into a cup from a water-skin (idawah) that he had, cleaned his teeth with it (istanna), then stood and prayed until I said: “He has prayed about as long as he slept.” Then he lay down until I said: “He has slept about as long as he prayed.” Then he awoke and did as he had done the first time, and said the same as he had said—so the Messenger of Allah ﷺ did that three times before Fajr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1627)، وفي عمل اليوم والليلة (307) وفي السنن الكبرى (10066)."},{"num":2702,"demo":false,"sanad":"","matn":["عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا أَخْبَرَهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لَهُ: أَحَبُّ الصَّلاَةِ إِلَى اللَّهِ صَلاَةُ دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ وَأَحَبُّ الصِّيَامِ إِلَى اللَّهِ صِيَامُ دَاوُدَ، وَكَانَ يَنَامُ نِصْفَ اللَّيْلِ، وَيَقُومُ ثُلُثَهُ، وَيَنَامُ سُدُسَهُ، وَيَصُومُ يَوْمًا وَيُفْطِرُ يَوْمًا."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1131)، ومسلم في الصوم (1159/189) كلاهما من حديث سفيان بن عيينة، عن عمرو بن دينار، عن عمرو بن أوس، عن عبدالله بن عمرو بن العاص فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في القيام في ثلث الليل بعد شطره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1131) and Muslim (1159, hadith 189).","chapter_en":"What has come regarding standing (for prayer) in the third of the night after half of it has passed.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":11,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As reported that the Messenger of Allah ﷺ said to him: “The most beloved prayer to Allah is the prayer of Dawud (David), peace be upon him, and the most beloved fasting to Allah is the fasting of Dawud.” He would sleep half the night, stand for a third of it, and sleep a sixth of it; and he would fast one day and break his fast one day."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1131)، ومسلم (1159/189)."},{"num":2703,"demo":false,"sanad":"","matn":["عَنِ الأَسْوَدِ، قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا كَيْفَ صَلاَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ؟ قَالَتْ: كَانَ يَنَامُ أَوَّلَهُ وَيَقُومُ آخِرَهُ، فَيُصَلِّي، ثُمَّ يَرْجِعُ إِلَى فِرَاشِهِ، فَإِذَا أَذَّنَ الْمُؤَذِّنُ وَثَبَ، فَإِنْ كَانَ بِهِ حَاجَةٌ اغْتَسَلَ، وَإِلاَّ تَوَضَّأَ وَخَرَجَ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1146)، ومسلم في صلاة المسافرين (739) كلاهما من حديث أبي إسحاق، عن الأسود بن يزيد به واللفظ للبخاريِ.","grade":"متفق عليه","chapter_ar":"باب من نام أول الليل وأحيا آخِره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1146) and Muslim (739); the wording is al-Bukhari’s.","chapter_en":"Whoever sleeps at the beginning of the night and keeps the end of it alive (with worship).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":12,"content":{"translation":{"en":["Al-Aswad ibn Yazid said: I asked ‘A’ishah: “How was the Prophet’s ﷺ prayer at night?” She said: “He would sleep at its beginning and stand at its end and pray, then return to his bed. When the caller to prayer gave the adhan, he would rise; if he had a need (i.e., if he was junub) he would bathe, otherwise he would make wudu’ and go out.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1146)، ومسلم (739) واللفظ للبخاري."},{"num":2704,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَنْزِلُ رَبُّنَا تَبَارَكَ وَتَعَالَى كُلَّ لَيْلَةٍ إِلَى السَّمَاءِ الدُّنْيَا حِينَ يَبْقَى ثُلُثُ اللَّيْلِ الآخِرُ. يَقُولُ مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ، مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ."],"takhrij":"متفق عليه: رواه مالك في القرآن (30) عن ابن شهاب، عن أبي عبدالله الأغر وأبي سلمة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الصّلاة والدّعاء في آخر الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (30), al-Bukhari (1145), and Muslim (758).","chapter_en":"What has come regarding prayer and supplication in the last part of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":13,"content":{"translation":{"en":["Abu Hurairah reported that the Messenger of Allah ﷺ said: “Our Lord—Blessed and Exalted—descends every night to the lowest heaven when the last third of the night remains, and He says: ‘Who is calling upon Me so I may answer him? Who is asking Me so I may give him? Who is seeking My forgiveness so I may forgive him?’”"]},"buhuth":{"en":["And Muslim also narrated a wording in which: “Allah descends to the lowest heaven every night when the first third of the night has passed, and He says: ‘I am the King. I am the King. Who is the one calling upon Me so I may answer him? Who is the one asking Me so I may give him? Who is the one seeking My forgiveness so I may forgive him?’ And He continues like that until dawn becomes bright.”","And in another wording: The Messenger of Allah ﷺ said: “Allah descends to the lowest heaven at the middle of the night, or in the last third of the night, and He says: ‘Who is calling upon Me so I may answer him, or asking Me so I may give him?’ Then He says: ‘Who will lend (to Allah), neither destitute nor wronged?’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[299,10758,10926,13399],"tks":"متفق عليه: رواه مالك (30)، ورواه البخاري (1145)، ومسلم (758)."},{"num":2705,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَرْفَعُهُ قَالَ:  سُئِلَ: أَيُّ الصَّلَاةِ أَفْضَلُ بَعْدَ الْمَكْتُوبَةِ؟ وَأَيُّ الصِّيَامِ أَفْضَلُ بَعْدَ شَهْرِ رَمَضَانَ، فَقَالَ: أَفْضَلُ الصَّلَاةِ بَعْدَ الصَّلَاةِ الْمَكْتُوبَةِ، الصَّلَاةُ فِي جَوْفِ اللَّيْلِ، وَأَفْضَلُ الصِّيَامِ بَعْدَ شَهْرِ رَمَضَانَ صِيَامُ شَهْرِ اللهِ الْمُحَرَّمِ."],"takhrij":"صحيح: رواه مسلم في الصيام (1163/203) عن زهير بن حرب، حدثنا جرير، عن عبدالملك بن عُمير، عن محمد بن المُنْتَشِر، عن حُميد بن عبدالرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصلاة في جوف الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (1163, hadith 203).","chapter_en":"What has come regarding the virtue of praying in the depth of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":14,"content":{"translation":{"en":["Abu Hurairah narrated it as marfu‘ (raised to the Prophet ﷺ): He was asked: “Which prayer is best after the obligatory (prayer)? And which fasting is best after the month of Ramadan?” He said: “The best prayer after the obligatory prayer is prayer in the depth of the night, and the best fasting after the month of Ramadan is fasting in Allah’s month al-Muharram.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1163/203)."},{"num":2706,"demo":false,"sanad":"","matn":["عن عَمْرِو بْنِ عَبَسَةَ يَقُولُ: قُلْتُ: يَا رَسُولَ اللَّهِ! هَلْ مِنْ سَاعَةٍ أَقْرَبُ مِنَ الأُخْرَى؟ أَوْ هَلْ مِنْ سَاعَةٍ يُبْتَغَى ذِكْرُهَا؟ قَالَ: نَعَمْ، إِنَّ أَقْرَبَ مَا يَكُونُ الرَّبُّ عَزَّ وَجَلَّ مِنَ الْعَبْدِ جَوْفُ اللَّيْلِ الآخِرِ، فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ عَزَّ وَجَلَّ فِي تِلْكَ السَّاعَةِ فَكُنْ، فَإِنَّ الصَّلاَةَ مَحْضُورَةٌ مَشْهُودَةٌ إِلَى طُلُوعِ الشَّمْسِ."],"takhrij":"صحيح: رواه النسائي (572) عن عمرو بن منصور، أخبرنا آدم بن أبي إياس، حدثنا الليث بن سعد، حدثنا معاوية بن صالح، قال: أخبرني أبو يحيى سُليم بن عامر وضمرة بن حبيب وأبو طلحة نعيم بن زياد قالوا: سمعنا أبا أمامة الباهلي يقول: سمعت عمرو بن عَبَسَة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فضل الصلاة في جوف الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSources: al-Nasa’i (572); al-Tirmidhi (3579) — he said: “Hasan Sahih Gharib”; and Abu Dawud (1277), where it states: “Which part of the night is most ‘heard’?” He replied: “The depth of the last part of the night—so pray whatever you wish, for indeed the prayer is witnessed and recorded.”","chapter_en":"What has come regarding the virtue of praying in the depth of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":14,"content":{"translation":{"en":["‘Amr ibn ‘Abasah said: I said, “O Messenger of Allah ﷺ, is there any time that is closer (than another), or is there any hour that should be sought out for remembrance?” He said: “Yes. Indeed, the closest that the Lord—Mighty and Majestic—is to the servant is the depth of the last part of the night. So if you are able to be among those who remember Allah—Mighty and Majestic—at that hour, then be so; for indeed the prayer is attended and witnessed until the sun rises.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10929],"tks":"صحيح: رواه النسائي (572)، والترمذي (3579) وقال: (( حسن صحيح غريب)). ورواه أبو داود (1277) وفيه: أي الليل أسمع؟ فقال: (( جوف الليل الآخر، فصل ما شئت، فإن الصلاة مشهودة مكتوبة))."},{"num":2707,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُسْلِمٍ قُلْتُ لِأَبِي ذَرٍّ: أَيُّ قِيَامِ اللَّيْلِ أَفْضَلُ؟ قَالَ أَبُو ذَرٍّ: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا سَأَلْتَنِي فَقَالَ: جَوْفُ اللَّيْلِ الْغَابِرِ-أَوْ نِصْفُ اللَّيْلِ وَقَلِيلٌ فَاعِلُهُ ."],"takhrij":"حسن: رواه الإمام أحمد (21555)، والنسائي في الكبرى (1310)، وابن حبان (2564)، كلهم من طرق عن عوف (هو الأعرابي)، عن مهاجر أبي خالد، حدثني أبو العالية، حدثني أبو مسلم، قال فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في فضل الصلاة في جوف الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Ahmad (21555); al-Nasa’i in al-Kubra (1310); Ibn Hibban (2564).","chapter_en":"What has come regarding the virtue of praying in the depth of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":14,"content":{"translation":{"en":["Abu Muslim said: I said to Abu Dharr, “Which standing (in prayer) at night is best?” Abu Dharr said: I asked the Messenger of Allah ﷺ as you asked me, and he said: “The depth of the remaining (latter) part of the night—or (he said) half of the night—and few are those who do it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (21555)، والنسائي في الكبرى ( 1310)، وابن حبان (2564)."},{"num":2708,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّ فِي اللَّيْلِ لَسَاعَةً، لَا يُوَافِقُهَا رَجُلٌ مُسْلِمٌ يَسْأَلُ اللَّهَ خَيْرًا مِنْ أَمْرِ الدُّنْيَا وَالْآخِرَةِ إِلَّا أَعْطَاهُ إِيَّاهُ، وَذَلِكَ كُلَّ لَيْلَةٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (757) عن عثمان بن أبي شيبة، حدّثنا جرير، عن الأعمش، عن أبي سفيان، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"باب في اللّيل ساعة مستجاب فيها الدّعاء","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (757).","chapter_en":"In the night there is an hour in which supplication is answered.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":15,"content":{"translation":{"en":["Jabir said: I heard the Prophet ﷺ say: “Indeed, in the night there is an hour—no Muslim man coincides with it while asking Allah for something good of the affairs of this world and the Hereafter except that He grants it to him—and that is every night.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10761,10927],"tks":"صحيح: رواه مسلم (757)."},{"num":2709,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلاً يَقْرَأُ فِي الْمَسْجِدِ، فَقَالَ: رَحِمَهُ اللَّهُ، لَقَدْ أَذْكَرَنِي كَذَا وَكَذَا آيَةً، أَسْقَطْتُهُنَّ مِنْ سُورَةِ كَذَا وَكَذَا. وَزَادَ عَبَّادُ بْنُ عَبْدِ اللَّهِ عَنْ عَائِشَةَ: تَهَجَّدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِي، فَسَمِعَ صَوْتَ عَبَّادٍ يُصَلِّي فِي الْمَسْجِدِ فَقَالَ: يَا عَائِشَةُ، أَصَوْتُ عَبَّادٍ هَذَا. قُلْتُ نَعَمْ. قَالَ: اللَّهُمَّ ارْحَمْ عَبَّادًا."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2655) عن محمد بن عبيد بن ميمون، أخبرنا عيسى بن يونس، عن هشام، عن أبيه، عن عائشة فذكرت الحديث.","grade":"متفق عليه","chapter_ar":"باب رفع الصوت بالقراءة في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (2655) and Muslim (788).","chapter_en":"Raising the voice with recitation in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":16,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ heard a man reciting in the mosque, and he said: “May Allah have mercy on him. He has reminded me of such-and-such verses that I had dropped (forgotten) from such-and-such surah.” And ‘Abbad ibn ‘Abdullah added—narrating from ‘A’ishah: The Prophet ﷺ stood for tahajjud in my house, then he heard the voice of ‘Abbad praying in the mosque, so he said: “O ‘A’ishah, is that the voice of ‘Abbad?” She said: Yes. He said: “O Allah, have mercy on ‘Abbad.”"]},"buhuth":{"en":["And Muslim also narrates: The Prophet ﷺ listened to a man reciting in the mosque and said: “May Allah have mercy on him. He has reminded me of a verse that I had been made to forget.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2655)، ومسلم (788)."},{"num":2710,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: كَانَتْ قِرَاءَةُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى قَدْرِ مَا يَسْمَعُهُ مَنْ فِي الْحُجْرَةِ، وَهُوَ فِي الْبَيْتِ."],"takhrij":"حسن: رواه أبو داود (1327)، وأحمد (2446) كلاهما من حديث ابن أبي الزّناد، عن عمرو بن أبي عمرو مولى المطلب، عن عِكرمة، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب رفع الصوت بالقراءة في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Abu Dawud (1327); Ahmad (2446); Ibn Khuzaymah (1157); Ibn Hibban (2581). In it: I asked Ibn ‘Abbas, “How was the night prayer of the Messenger of Allah ﷺ?” He said: “He would recite in one of his rooms, and whoever was outside could hear.”","chapter_en":"Raising the voice with recitation in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":16,"content":{"translation":{"en":["‘Abdullah ibn ‘Abbas said: The recitation of the Prophet ﷺ would be at a level that those in the room could hear while he was in the house."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1327)، وأحمد (2446) ورواه ابن خزيمة (1157) وابن حبان (2581) قال: سألت بن عباس فقلت: ما صلاة رسول الله ﷺ بالليل؟ قال: (( كان يقرأ في بعض حجره، فيسمع من كان خارجا ))."},{"num":2711,"demo":false,"sanad":"","matn":["عَنْ أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ، قَالَتْ: كُنْتُ أَسْمَعُ قِرَاءَةَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ وَأَنَا عَلَى عَرِيشِي."],"takhrij":"حسن: رواه النسائي (1013)، وابن ماجه (1349)، والترمذي في \"الشّمائل\" (318)، وأحمد (26905) كلهم من حديث وكيع، قال: حدثنا مسعر بن كدام، عن أبي العلاء العبدي، عن يحيى بن جعدة، عن أمّ هانئ، فذكرته.","grade":"حسن","chapter_ar":"باب رفع الصوت بالقراءة في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: al-Nasa’i (1013); Ibn Majah (1349); al-Tirmidhi in al-Shama’il (318); Ahmad (26905).","chapter_en":"Raising the voice with recitation in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":16,"content":{"translation":{"en":["Umm Hani’ bint Abi Talib said: I used to hear the Prophet’s ﷺ recitation at night while I was on my bed/couch."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1013)، وابن ماجه (1349)، والترمذي في “الشمائل” (318)، وأحمد (26905)."},{"num":2712,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ مَرْوَانَ، أَنَّهُ أَتَى عُمَرَ - فَقَالَ: جِئْتُ يَا أَمِيرَ الْمُؤْمِنِينَ مِنَ الْكُوفَةِ، وَتَرَكْتُ بِهَا رَجُلًا يُمْلِي الْمَصَاحِفَ عَنْ ظَهْرِ قَلْبِهِ، فَغَضِبَ وَانْتَفَخَ حَتَّى كَادَ يَمْلَأُ مَا بَيْنَ شُعْبَتَيِ الرَّحْلِ، فَقَالَ: وَمَنْ هُوَ وَيْحَكَ؟ قَالَ: عَبْدُ اللَّهِ بْنُ مَسْعُودٍ. فَمَا زَالَ يُطْفَأُ وَيُسَرَّى عَنْهُ الْغَضَبُ، حَتَّى عَادَ إِلَى حَالِهِ الَّتِي كَانَ عَلَيْهَا. ثُمَّ قَالَ: وَيْحَكَ، وَاللهِ مَا أَعْلَمُهُ بَقِيَ مِنَ النَّاسِ أَحَدٌ هُوَ أَحَقُّ بِذَلِكَ مِنْهُ، وَسَأُحَدِّثُكَ عَنْ ذَلِكَ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَزَالُ يَسْمُرُ عِنْدَ أَبِي بَكْرٍ اللَّيْلَةَ كَذَاكَ فِي الْأَمْرِ مِنْ أَمْرِ الْمُسْلِمِينَ، وَإِنَّهُ سَمَرَ عِنْدَهُ ذَاتَ لَيْلَةٍ، وَأَنَا مَعَهُ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَخَرَجْنَا مَعَهُ، فَإِذَا رَجُلٌ قَائِمٌ يُصَلِّي فِي الْمَسْجِدِ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَمِعُ قِرَاءَتَهُ، فَلَمَّا كِدْنَا أَنْ نَعْرِفَهُ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ سَرَّهُ أَنْ يَقْرَأَ الْقُرْآنَ رَطْبًا كَمَا أُنْزِلَ، فَلْيَقْرَأْهُ عَلَى قِرَاءَةِ ابْنِ أُمِّ عَبْدٍ. قَالَ: ثُمَّ جَلَسَ الرَّجُلُ يَدْعُو، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لَهُ: سَلْ تُعْطَهْ، سَلْ تُعْطَهْ، قَالَ عُمَرُ: قُلْتُ: وَاللهِ لَأَغْدُوَنَّ إِلَيْهِ فَلَأُبَشِّرَنَّهُ، قَالَ: فَغَدَوْتُ إِلَيْهِ لِأُبَشِّرَهُ فَوَجَدْتُ أَبَا بَكْرٍ قَدْ سَبَقَنِي إِلَيْهِ فَبَشَّرَهُ، وَلا وَاللهِ مَا سَابَقْتُهُ إِلَى خَيْرٍ قَطُّ إِلَّا سَبَقَنِي إِلَيْهِ."],"takhrij":"صحيح: رواه الإمام أحمد (175) عن أبي معاوية، حدثنا الأعمش، عن إبراهيم، عن علقمة قال: جاء رجل إلى عمر وهو بعرفة.","grade":"صحيح","chapter_ar":"باب رفع الصوت بالقراءة في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSources: Ahmad (175); and Ibn Khuzaymah graded it sahih (1156).","chapter_en":"Raising the voice with recitation in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":16,"content":{"translation":{"en":["Qays ibn Marwan said that he came to ‘Umar and said: “O Commander of the Believers, I have come to you from Kufah, and I left there a man who dictates (writes/teaches) the mushafs from the strength of his memory.” ‘Umar became angry and swelled up with anger until he nearly filled the space between the two sides of the saddle, and he said: “Who is he—woe to you?” He said: “‘Abdullah ibn Mas‘ud.” Then ‘Umar’s anger kept being calmed and eased until he returned to the state he had been in. Then he said: “Woe to you! By Allah, I do not know that there remains among the people anyone more deserving of that than him. And I will tell you why. The Messenger of Allah ﷺ used to stay up at night with Abu Bakr discussing matters of the Muslims, and one night he stayed up with him, and I was with them. The Messenger of Allah ﷺ went out and we went out with him, and there was a man standing praying in the mosque. The Messenger of Allah ﷺ stood listening to his recitation. When we were about to recognize who it was, the Messenger of Allah ﷺ said: ‘Whoever would be pleased to recite the Qur’an fresh (as if newly revealed) as it was revealed, let him recite it according to the recitation of Ibn Umm ‘Abd.’ Then the man sat making du‘a, and the Messenger of Allah ﷺ began saying to him: ‘Ask and you will be given. Ask and you will be given.’ ‘Umar said: I said, ‘By Allah, I will go to him in the morning and give him glad tidings.’ He said: So I went to him in the morning to give him glad tidings, but I found that Abu Bakr had already beaten me to him and had already given him glad tidings. And by Allah, I never raced Abu Bakr to any good except that he beat me to it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10262],"tks":"صحيح: رواه الإمام أحمد (175 )، وصححه ابن خزيمة (1156)."},{"num":2713,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي قيس قَالَ: سَأَلْتُ عَائِشَةَ: كَيْفَ كَانَ قِرَاءَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ يَجْهَرُ أَمْ يُسِرُّ؟ قَالَتْ: كُلُّ ذَلِكَ قَدْ كَانَ يَفْعَلُ رُبَّمَا جَهَرَ، وربَّما أسَرَّ."],"takhrij":"حسن: رواه النسائي (1662)، وابن خزيمة (1160)، والحاكم (1/310) كلهم من حديث معاوية بن صالح، عن عبدالله بن أبي قيس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الجهر والسر في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: al-Nasa’i (1662); Ibn Khuzaymah (1160); al-Hakim (1/310).","chapter_en":"What has been reported regarding reciting aloud and silently in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":17,"content":{"translation":{"en":["‘Abdullah ibn Abi Qays said: I asked ‘A’ishah, “How was the recitation of the Messenger of Allah ﷺ at night—aloud or silently?” She said: “He used to do all of that: sometimes he recited aloud, and sometimes he recited quietly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1662)، وابن خزيمة ( 1160)، والحاكم (1/310)."},{"num":2714,"demo":false,"sanad":"","matn":["عَنْ غُضَيْفِ بْنِ الْحَارِثِ ، قَالَ: : قُلْتُ : يَا أُمَّ الْمُؤْمِنِينَ ، أَرَأَيْتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، أَكَانَ يَجْهَرُ بِصَلاتِهِ أَمْ يُخَافِتُ بِهَا؟ ؟ قَالَتْ: : رُبَّمَا جَهَرَ بِصَلاتِهِ، ، وَرُبَّمَا خَافَتَ بِهَا، ، قُلْتُ: : اللَّهُ أَكْبَرُ، ، الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الأَمْرِ سَعَةً."],"takhrij":"حسن: رواه أبو داود (226)، والنسائي (222)، وابن ماجه (1354)، كلهم من حديث برد بن سنان أبي العلاء، عن عُبادة بن نُسَيِّ، عن غُضيف ابن الحارث في حديث طويل سبق تخريجه في كتاب الغسل، باب غسل الجنابة قبل النوم وبعده.","grade":"حسن","chapter_ar":"باب ما جاء في الجهر والسر في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Abu Dawud (226); al-Nasa’i (222); Ibn Majah (1354).","chapter_en":"What has been reported regarding reciting aloud and silently in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":17,"content":{"translation":{"en":["Ghudayf ibn al-Harith said: I said to ‘A’ishah, “O Mother of the Believers, tell me about the Prophet ﷺ: would he recite aloud in his prayer or keep it quiet?” She said: “Sometimes he would recite aloud in his prayer, and sometimes he would recite quietly.” I said: “Allahu Akbar! Praise be to Allah who has made the matter broad (with flexibility).”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (226)، والنسائي (222)، وابن ماجه ( 1354)."},{"num":2715,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا فِي قَوْلِهِ تَعَالَى: ﴿وَلاَ تَجْهَرْ بِصَلاَتِكَ وَلاَ تُخَافِتْ بِهَا﴾ [سورة الإسراء: 110]} قَالَ: نَزَلَتْ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُخْتَفٍ بِمَكَّةَ، كَانَ إِذَا صَلَّى بِأَصْحَابِهِ رَفَعَ صَوْتَهُ بِالْقُرْآنِ، فَإِذَا سَمِعَهُ الْمُشْرِكُونَ سَبُّوا الْقُرْآنَ، وَمَنْ أَنْزَلَهُ، وَمَنْ جَاءَ بِهِ، فَقَالَ اللَّهُ تَعَالَى لِنَبِيِّهِ: صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ {وَلاَ تَجْهَرْ بِصَلاَتِكَ} أَىْ بِقِرَاءَتِكَ، فَيَسْمَعَ الْمُشْرِكُونَ، فَيَسُبُّوا الْقُرْآنَ، {وَلاَ تُخَافِتْ بِهَا} عَنْ أَصْحَابِكَ فَلاَ تُسْمِعُهُمْ {وَابْتَغِ بَيْنَ ذَلِكَ سَبِيلاً}."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4722)، ومسلم في الصلاة (446) كلاهما من حديث هُشيم، حدثنا أبو بشر (هو جعفر بن إياس)، عن سعيد بن جبير، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الجهر والسر في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (4722) and Muslim (446).","chapter_en":"What has been reported regarding reciting aloud and silently in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":17,"content":{"translation":{"en":["Ibn ‘Abbas, regarding the saying of Allah Most High: (وَلَا تَجْهَرْ بِصَلَاتِكَ وَلَا تُخَافِتْ بِهَا) [Surah al-Isra’: 110], said: It was revealed while the Messenger of Allah ﷺ was hiding in Makkah. When he prayed with his companions, he would raise his voice with the Qur’an; when the polytheists heard it, they would insult the Qur’an, and the One who revealed it, and the one who brought it. So Allah Most High said to His Prophet ﷺ: (وَلَا تَجْهَرْ بِصَلَاتِكَ)—meaning: do not raise your voice with your recitation so the polytheists hear and then insult the Qur’an; (وَلَا تُخَافِتْ بِهَا)—do not make it so quiet from your companions that they cannot hear; (وَابْتَغِ بَيْنَ ذَٰلِكَ سَبِيلًا)—seek a way in between."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12679],"tks":"متفق عليه: رواه البخاري (4722)، ومسلم (446)."},{"num":2716,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ لَيْلَةً فَإِذَا هُوَ بِأَبِي بَكْرٍ يُصَلِّي يَخْفِضُ مِنْ صَوْتِهِ، قَالَ: وَمَرَّ بِعُمَرَ بْنِ الْخَطَّابِ وَهُوَ يُصَلِّي رَافِعًا صَوْتَهُ، قَالَ: فَلَمَّا اجْتَمَعَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا أَبَا بَكْرٍ مَرَرْتُ بِكَ، وَأَنْتَ تُصَلِّي تَخْفِضُ صَوْتَكَ قَالَ: قَدْ أَسْمَعْتُ مَنْ نَاجَيْتُ يَا رَسُولَ اللَّهِ. قَالَ: وَقَالَ لِعُمَرَ: مَرَرْتُ بِكَ وَأَنْتَ تُصَلِّي رَافِعًا صَوْتَكَ قَالَ: فَقَالَ: يَا رَسُولَ اللَّهِ أُوقِظُ الْوَسْنَانَ، وَأَطْرُدُ الشَّيْطَانَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : يَا أَبَا بَكْرٍ ارْفَعْ مِنْ صَوْتِكَ شَيْئًا وَقَالَ لِعُمَرَ: اخفِضْ مِنْ صَوْتِكَ شَيْئًا ."],"takhrij":"حسن: رواه أبو داود (1329)، والترمذي (447) كلاهما من طريق يحيى بن إسحاق، أخبرنا حماد بن سلمة، عن ثابت البناني، عن عبدالله بن رباح، عن أبي قتادة قال: فذكره. وقد صحّحه ابن خزيمة (1161) ومن طريقه رواه ابن حبان (733)، والحاكم (1168) كلهم من طريق يحيى بن إسحاق.","grade":"حسن","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Abu Dawud (1329); al-Tirmidhi (447); Ibn Khuzaymah (1161) (who authenticated it); Ibn Hibban (733).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["Abu Qatadah said: The Prophet ﷺ went out one night and found Abu Bakr praying, lowering his voice. He passed by ‘Umar ibn al-Khattab while he was praying, raising his voice. When they gathered with the Prophet ﷺ, he said: “O Abu Bakr, I passed by you while you were praying and you were lowering your voice.” Abu Bakr said: “I made the One I was privately speaking to hear, O Messenger of Allah.” He said to ‘Umar: “And I passed by you while you were praying and you were raising your voice.” ‘Umar said: “O Messenger of Allah ﷺ, I wake the sleepy and drive away the devil.” So the Prophet ﷺ said: “O Abu Bakr, raise your voice a little.” And he said to ‘Umar: “Lower your voice a little.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1329)، والترمذي (447) وصححه ابن خزيمة (1161) وابن حبان (733)."},{"num":2717,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ بِهَذِهِ الْقِصَّةِ، وَلَمْ يَذْكُرْ: فَقَالَ لأَبِي بَكْرٍ ارْفَعْ مِنْ صَوْتِكَ شَيْئًا، وَلِعُمَرَ اخْفِضْ شَيْئًا زَادَ: وَقَدْ سَمِعْتُكَ يَا بِلاَلُ وَأَنْتَ تَقْرَأُ مِنْ هَذِهِ السُّورَةِ، وَمِنْ هَذِهِ السُّورَةِ، قَالَ: كَلاَمٌ طَيِّبٌ يَجْمَعُ اللَّهُ تَعَالَى بَعْضَهُ إِلَى بَعْضٍ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : كلُّهم قَدْ أَصَابَ ."],"takhrij":"حسن: رواه أبو داود (1330) عن أبي حصين بن يحيى الرازي، حدثنا أسباط بن محمد، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSource: Abu Dawud (1330).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["Abu Hurayrah narrated this same story, but he did not mention: “So he said to Abu Bakr: raise your voice a little, and to ‘Umar: lower it a little.” He added: “And I also heard you, O Bilal, while you were reciting from this surah and from this surah.” He said: “Good speech—Allah, Most High, gathers some of it to some.” So the Prophet ﷺ said: “All of them have done correctly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود ( 1330)."},{"num":2718,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ الْجُهَنِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْجَاهِرُ بِالْقُرْآنِ كَالْجَاهِرِ بِالصَّدَقَةِ، وَالْمُسِرُّ بِالْقُرْآنِ كَالْمُسِرِّ بِالصَّدَقَةِ."],"takhrij":"حسن: رواه أبو داود (1333)، والترمذي (2919) كلاهما من حديث إسماعيل بن عياش، عن بَحير بن سعد، عن خالد بن معدان، عن كثير ابن مرة الحضرمي، عن عقبة بن عامر الجُهني فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Abu Dawud (1333); al-Tirmidhi (2919).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["‘Uqbah ibn ‘Amir al-Juhani said: The Messenger of Allah ﷺ said: “The one who recites the Qur’an aloud is like the one who gives charity openly, and the one who recites the Qur’an quietly is like the one who gives charity secretly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1333)، والترمذي (2919)."},{"num":2719,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ، قَالَ: اعْتَكَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَسَمِعَهُمْ يَجْهَرُونَ بِالْقِرَاءَةِ، فَكَشَفَ السِّتْرَ وَقَالَ: أَلاَ إِنَّ كُلَّكُمْ مُنَاجٍ رَبَّهُ، فَلاَ يُؤْذِيَنَّ بَعْضُكُمْ بَعْضًا، وَلاَ يَرْفَعْ بَعْضُكُمْ عَلَى بَعْضٍ فِي الْقِرَاءَةِ. أَوْ قَالَ: فِي الصَّلاَةِ."],"takhrij":"صحيح: رواه أبو داود (1332) عن الحسن بن علي، حدثنا عبد الرزاق، أخبرنا معمر، عن إسماعيل بن أمية، عن أبي سلمة، عن أبي سعيد فذكره، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSources: Abu Dawud (1332); ‘Abd al-Razzaq (4216); Ahmad (11896); Ibn Khuzaymah (1162) (who authenticated it).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["Abu Sa‘id said: The Messenger of Allah ﷺ made i‘tikaf in the mosque and heard them reciting aloud. He uncovered the curtain and said: “Indeed, each of you is privately conversing with his Lord. So do not harm one another, and do not raise your voices over one another in recitation”—or he said: “in prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4712],"tks":"صحيح: رواه أبو داود (1332). وعبد الرزاق (4216) وأحمد (11896) وصححه ابن خزيمة (1162)."},{"num":2720,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: اعْتَكَفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْعَشْرِ الْأَوَاخِرِ مِنْ رَمَضَانَ، فَاتُّخِذَ لَهُ فِيهِ بَيْتٌ مِنْ سَعَفٍ، قَالَ: فَأَخْرَجَ رَأْسَهُ ذَاتَ يَوْمٍ، فَقَالَ: إِنَّ الْمُصَلِّيَ يُنَاجِي رَبَّهُ عَزَّ وَجَلَّ، فَلْيَنْظُرْ أَحَدُكُمْ بِمَا يُنَاجِي رَبَّهُ، وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقِرَاءَةِ."],"takhrij":"حسن: رواه الإمام أحمد (5349) عن عتَّاب، حدثنا أبو حمزة -يعني السكري-، عن ابن أبي ليلى، عن صدقة المكي، عن ابن عمرَ فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Ahmad (5349); al-Bazzar, Kashf al-Astar (726); Ibn Khuzaymah (2237).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["Ibn ‘Umar said: The Messenger of Allah ﷺ made i‘tikaf in the last ten nights of Ramadan, and a small enclosure of palm leaves was made for him. One day he put his head out and said: “Indeed, the one who is praying is privately conversing with his Lord—Mighty and Majestic—so let each of you look at how he converses with his Lord, and let not some of you recite aloud over others.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (5349)، والبزار في كشف الأستار (726)، وابن خزيمة (2237)."},{"num":2721,"demo":false,"sanad":"","matn":["عَنِ الْبَيَاضِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ عَلَى النَّاسِ وَهُمْ يُصَلُّونَ، وَقَدْ عَلَتْ أَصْوَاتُهُمْ بِالْقِرَاءَةِ، فَقَالَ: إِنَّ الْمُصَلِّي يُنَاجِي رَبَّهُ، عَزَّ وَجَلَّ، فَلْيَنْظُرْ مَا يُنَاجِيهِ، وَلَا يَجْهَرْ بَعْضُكُمْ عَلَى بَعْضٍ بِالْقُرْآنِ."],"takhrij":"حسن: رواه مالك في الصلاة (29) عن يحيى بن سعيد، عن محمد بن إبراهيم بن الحارث التيمي، عن أبي حازم التَمَّار، عن البياضي فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الاعتدال في رفع الصوت في صلاة الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Malik (29); Ahmad (19022); al-Nasa’i in al-Kubra (3364,8091).","chapter_en":"What has been reported about moderation in raising the voice in the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":18,"content":{"translation":{"en":["Al-Biyadi reported that the Messenger of Allah ﷺ came out to the people while they were praying, and their voices had risen in recitation. He said: “Indeed, the one who is praying is privately conversing with his Lord, so let him consider what he converses with Him by; and do not raise your voices over one another with the Qur’an.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4711],"tks":"حسن: رواه مالك (29) والإمام أحمد (19022)، والنسائي في الكبرى (3364,8091)."},{"num":2722,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ لِلتَّهَجُّدِ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1136)، ومسلم في الطهارة (255) كلاهما من حديث حصين، عن أبي وائل، عن حذيفة فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب السواك لمن قام لصلاة التهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1136) and Muslim (255).","chapter_en":"The recommendation of using the tooth-stick (siwak) for one who gets up for the night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":19,"content":{"translation":{"en":["Hudhayfah reported that when the Prophet ﷺ would rise for tahajjud at night, he would cleanse his mouth thoroughly with the siwak."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري ( 1136)، ومسلم (255)."},{"num":2723,"demo":false,"sanad":"","matn":["عن سَعْدِ بن هِشَامٍ بن عَامِرٍ قَالَ: قُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ، أَنْبِئِينِي عَنْ وِتْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: كُنَّا نُعِدُّ لَهُ سِوَاكَهُ وَطَهُورَهُ، فَيَبْعَثُهُ اللهُ مَا شَاءَ أَنْ يَبْعَثَهُ مِنَ اللَّيْلِ، فَيَتَسَوَّكُ، وَيَتَوَضَّأُ، وَيُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ.. فَيَذْكُرُ اللهَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) من حديث قتادة، عن","grade":"صحيح","chapter_ar":"باب استحباب السواك لمن قام لصلاة التهجد","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (746).","chapter_en":"The recommendation of using the tooth-stick (siwak) for one who gets up for the night prayer (tahajjud).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":19,"content":{"translation":{"en":["Sa‘d ibn Hisham ibn ‘Amir said: I said, “O Mother of the Believers (‘A’ishah), tell me about the witr of the Messenger of Allah ﷺ.” She said: “We would prepare for him his siwak and his water for purification. Then Allah would awaken him for as much of the night as He willed. He would use the siwak, perform wudu’, and pray nine rak‘ahs, not sitting except in the eighth…” (in a lengthy hadith)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2724,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ لِيُصَلِّيَ افْتَتَحَ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (767) من طريق هُشَيم قال: أخبرنا أبو حُرَّة، عن الحسن، عن سعد بن هِشام، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب افتتاح صلاة الليل بركعتين خفيفتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (767).","chapter_en":"Beginning the night prayer with two light rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":20,"content":{"translation":{"en":["‘A’ishah said: When the Messenger of Allah ﷺ rose at night to pray, he would begin his prayer with two light rak‘ahs."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (767)."},{"num":2725,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَتَهَجَّدُ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ."],"takhrij":"صحيح: رواه أبو عوانة في \"صحيحه\" (2239)، ومن طريقه البغوي في \"شرح السنة\" (4/18) من طريق سليمان بن حيان، عن هشام بن حسان، عن محمد بن سيرين، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب افتتاح صلاة الليل بركعتين خفيفتين","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSources: Abu ‘Awanah in his Sahih (2239); al-Baghawi in Sharh al-Sunnah (18/4).","chapter_en":"Beginning the night prayer with two light rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":20,"content":{"translation":{"en":["Abu Hurayrah said: When the Prophet ﷺ rose at night for tahajjud, he would pray two light rak‘ahs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو عوانة في “صحيحه” (2239)، والبغوي في “شرح السنة” (18/4)."},{"num":2726,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ بْنِ عبـدالله أن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَفْضَلُ الصَّلَاةِ طُولُ الْقُنُوتِ ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (756) من حديث أبي الزبير، عن جابر فذكره. ورواه من طريق أبي سفيان عن جابر قال: سئل رسول الله صلى الله عليه وسلم : أي الصلاة أفضل؟ فقال: طول القنوت .","grade":"صحيح","chapter_ar":"باب أفضل الصلاة طول القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (756). In another wording: The Messenger of Allah ﷺ was asked, “Which prayer is best?” He said: “The longest standing.”","chapter_en":"The best prayer is the one with the longest standing (qunut here meaning standing).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":21,"content":{"translation":{"en":["Jabir ibn ‘Abdullah reported that the Prophet ﷺ said: “The best prayer is the one with the longest qunut (standing).”"]},"buhuth":{"en":["Commentary (al-Nawawi): The intended meaning of “qunut” here is standing, by agreement of the scholars as far as I know.","Commentary (author’s note): What is meant here is the night prayer, because in the obligatory prayers it is recommended to keep them light (not overly long)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (756). وفي رواية: سئل رسول الله ﷺ: أي الصلاة أفضل؟ فقال: (( طول القنوت))."},{"num":2727,"demo":false,"sanad":"","matn":["عن عبدالله بن مَسْعُودٍ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَطَالَ حَتَّى هَمَمْتُ بِأَمْرِ سَوْءٍ. قَالَ: قِيلَ: وَمَا هَمَمْتَ بِهِ؟ قَالَ: هَمَمْتُ أَنْ أَجْلِسَ وَأَدَعَهُ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1135)، ومسلم في صلاة المسافرين (773) كلاهما من حديث الأعمش، عن أبي وائل، عن عبدالله فذكره، واللفظ لمسلم. ولفظ البخاري نحوه أيضاً.","grade":"متفق عليه","chapter_ar":"باب أفضل الصلاة طول القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1135) and Muslim (773), wording from Muslim.","chapter_en":"The best prayer is the one with the longest standing (qunut here meaning standing).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":21,"content":{"translation":{"en":["‘Abdullah ibn Mas‘ud said: I prayed with the Messenger of Allah ﷺ one night, and he stood for so long that I contemplated something bad. He was asked: “What did you contemplate?” He said: “I thought about sitting down and leaving him.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1135)، ومسلم (773)، واللفظ لمسلم."},{"num":2728,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ:  صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَافْتَتَحَ الْبَقَرَةَ. فَقُلْتُ: يَرْكَعُ عِنْدَ الْمِائَةِ. ثُمَّ مَضَى. فَقُلْتُ: يُصَلِّي بِهَا فِي رَكْعَةٍ! فَمَضَى، فَقُلْتُ: يَرْكَعُ بِهَا! ثُمَّ افْتَتَحَ النِّسَاءَ فَقَرَأَهَا، ثُمَّ افْتَتَحَ آلَ عِمْرَانَ فَقَرَأَهَا. يَقْرَأُ مُتَرَسِّلًا، إِذَا مَرَّ بِآيَةٍ فِيهَا تَسْبِيحٌ سَبَّحَ، وَإِذَا مَرَّ بِسُؤَالٍ سَأَلَ، وَإِذَا مَرَّ بِتَعَوُّذٍ تَعَوَّذَ. ثُمَّ رَكَعَ فَجَعَلَ يَقُولُ: سُبْحَانَ رَبِّيَ الْعَظِيمِ. فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ. ثُمَّ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. ثُمَّ قَامَ طَوِيلًا قَرِيبًا مِمَّا رَكَعَ، ثُمَّ سَجَدَ فَقَالَ: سُبْحَانَ رَبِّيَ الْأَعْلَى، فَكَانَ سُجُودُهُ قَرِيبًا مِنْ قِيَامِهِ.","وَفِي رواية مِنَ الزِّيَادَةِ: فَقَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ رَبَّنَا لَكَ الْحَمْدُ .."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (772) من طرق عن الأعمش، عن سَعْد بن عبيدة، عن المستورِد بن الأحَنف، عن صِلة بن زفر، عن حذيفة فذكره.","grade":"صحيح","chapter_ar":"باب أفضل الصلاة طول القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSource: Muslim (772).","chapter_en":"The best prayer is the one with the longest standing (qunut here meaning standing).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":21,"content":{"translation":{"en":["Hudhayfah said: I prayed with the Prophet ﷺ one night. He began with al-Baqarah, and I thought he would bow at one hundred (verses), but he continued. I thought he would finish it in a single rak‘ah, but he continued. Then I thought he would bow after completing it, but he began al-Nisa’ and recited it, then began Al ‘Imran and recited it. He recited slowly and deliberately: whenever he passed a verse of glorification, he glorified Allah; whenever he passed a verse of supplication, he asked; and whenever he passed a verse seeking refuge, he sought refuge. Then he bowed and began saying: “Subhana Rabbi al-‘Azim,” and his bowing was about as long as his standing. Then he said: “Sami‘a Allahu liman hamidah,” then he stood for a long time, nearly as long as his bowing. Then he prostrated and said: “Subhana Rabbi al-A‘la,” and his prostration was nearly as long as his standing.","In an added wording: he said: “Sami‘a Allahu liman hamidah, Rabbana laka al-hamd.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (772)."},{"num":2729,"demo":false,"sanad":"","matn":["عن رَبِيعَةَ بْنِ كَعْبٍ الأسلمي قَالَ: كُنْتُ أَبِيتُ عِنْدَ بَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأُعْطِيهِ وَضُوءَهُ فَأَسْمَعُهُ الْهَوِيَّ مِنَ اللَّيْلِ يَقُولُ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. وَأَسْمَعُهُ الْهَوِيَّ مِنَ اللَّيْلِ يَقُولُ: الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ."],"takhrij":"صحيح: رواه الترمذي (3416) عن إسحاق بن منصور، أخبرنا النضر ابن شُميل ووهب بن جرير وأبو عامر العقدي وعبد الصمد بن عبد الوارث قالوا: حدثنا هشام الدستوائي، عن يحيى بن أبي كثير، عن أبي سلمة، حدثني ربيعة بن كعب فذكره، قال الترمذي: حسن صحيح.","grade":"صحيح","chapter_ar":"باب أفضل الصلاة طول القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Sahih\nSources: al-Tirmidhi (3416); Ahmad (16576, 16575).","chapter_en":"The best prayer is the one with the longest standing (qunut here meaning standing).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":21,"content":{"translation":{"en":["Rabi‘ah ibn Ka‘b al-Aslami said: I used to spend the night at the door of the Prophet ﷺ and provide him with his water for ablution. I would hear him for a long period of the night saying: “Sami‘a Allahu liman hamidah,” and I would hear him for a long period of the night saying: “Al-hamdu lillahi Rabbil-‘alamin.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3416)، والإمام أحمد (16576،16575)."},{"num":2730,"demo":false,"sanad":"","matn":["عن عَائِشَةَأَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ سُورَةَ الْبَقَرَةِ فِي رَكْعَتَيْنِ."],"takhrij":"حسن: رواه أبو يعلى المقصد العلي (405) عن الحسن بن حماد، حدثنا سجَّادة، ثنا حفص بن غياث، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب أفضل الصلاة طول القنوت","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSource: Abu Ya‘la, al-Maqsad al-‘Ali (405).","chapter_en":"The best prayer is the one with the longest standing (qunut here meaning standing).","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":21,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ divided Surah al-Baqarah between two rak‘ahs (reciting it across two rak‘ahs)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى في المقصد العلي (405)."},{"num":2731,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً، كَانَتْ تِلْكَ صَلاَتَهُ، يَسْجُدُ السَّجْدَةَ مِنْ ذَلِكَ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1123) عن أبي اليمان قال: أخبرنا شُعيب، عن الزهري، قال: أخبرني عروة، أن عائشة أخبرتْه. ورواه مسلم في صلاة المسافرين (736) من وجه آخر عن ابن شهاب بإسناده إلا أنه لم يذكر قولها: يسجد السجدة من ذلك قَدْرَ ما يقرأُ أحدكم خمسين آية قبل أن يرفع رأسه .","grade":"متفق عليه","chapter_ar":"باب ماجاء في طول السجود في قيام الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1123) and Muslim (736).","chapter_en":"What has been reported about lengthening the prostration during the night prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":22,"content":{"translation":{"en":["‘A’ishah reported that the Messenger of Allah ﷺ used to pray eleven rak‘ahs—this was his prayer—and he would prostrate in one of those prostrations for as long as one of you would take to recite fifty verses before raising his head."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1123)، ورواه مسلم (736)."},{"num":2732,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَيْهِمْ فِي رَمَضَانَ فَخَفَّفَ بِهِمْ، ثُمَّ دَخَلَ فَأَطَالَ، ثُمَّ خَرَجَ فَخَفَّفَ بِهِمْ، ثُمَّ دَخَلَ فَأَطَالَ، فَلَمَّا أَصْبَحْنَا قُلْنَا: يَا نَبِيَّ اللَّهِ، جَلَسْنَا اللَّيْلَةَ فَخَرَجْتَ إِلَيْنَا فَخَفَّفْتَ، ثُمَّ دَخَلْتَ فَأَطَلْتَ؟ قَالَ: مِنْ أَجْلِكُمْ فَعَلْتُ."],"takhrij":"حسن: رواه الإمام أحمد (12570) والحارث بغية الباحث (238) كلاهما عن أسود بن عامر، حدثنا حماد بن سلمة، عن ثُمامة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب فيمن يخفف صلاة الليل لأجل غيره، ويُطيل لنفسه","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Grading: Hasan\nSources: Ahmad (12570); al-Harith, Bughyat al-Bahith (238).","chapter_en":"Regarding one who shortens the night prayer for the sake of others, but lengthens it when praying alone.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":23,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ came out to them in Ramadan and made the prayer light for them; then he went inside and lengthened it. Then he came out and made it light for them; then he went inside and lengthened it. When morning came, we said: “O Prophet of Allah ﷺ! We stayed up last night—then you came out to us and made it light, then you went inside and lengthened it?” He said: “I did that for your sake.”"]},"buhuth":{"en":["Commentary (about ‘his chamber’): al-Sindi said: What is apparent is that what is meant by “his chamber” is the enclosure he made from a mat in the mosque to pray in at night, not the room of his house."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (12570) والحارث في بغية الباحث (238). قوله: (( حجرته ) قال السندي:."},{"num":2733,"demo":false,"sanad":"","matn":["عَنْ كُرَيْبٍ، مَوْلَى ابْنِ عَبَّاسٍ، أَنَّ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ، أَخْبَرَهُ أَنَّهُ، بَاتَ لَيْلَةً عِنْدَ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَهِيَ خَالَتُهُ. - قَالَ: فَاضْطَجَعْتُ فِي عَرْضِ الْوِسَادَةِ، وَاضْطَجَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَهْلُهُ فِي طُولِهَا. فَنَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى إِذَا انْتَصَفَ اللَّيْلُ - أَوْ قَبْلَهُ بِقَلِيلٍ، أَوْ بَعْدَهُ بِقَلِيلٍ، - اسْتَيْقَظَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَلَسَ يَمْسَحُ النَّوْمَ عَنْ وَجْهِهِ بِيَدِهِ. ثُمَّ قَرَأَ الْعَشْرَ الآيَاتِ الْخَوَاتِمَ مِنْ سُورَةِ آلِ عِمْرَانَ، ثُمَّ قَامَ إِلَى شَنٍّ مُعَلَّقٍ فَتَوَضَّأَ مِنْهُ، فَأَحْسَنَ وُضُوءَهُ ثُمَّ قَامَ يُصَلِّي.","قَالَ ابْنُ عَبَّاسٍ: فَقُمْتُ فَصَنَعْتُ مِثْلَ مَا صَنَعَ، ثُمَّ ذَهَبْتُ فَقُمْتُ إِلَى جَنْبِهِ، فَوَضَعَ رَسُولُ اللهِ صلى الله عليه وسلم يَدَهُ الْيُمْنَى عَلَى رَأْسِي، وَأَخَذَ بِأُذُنِي الْيُمْنَى يَفْتِلُهَا، فَصَلَّى رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ رَكْعَتَيْنِ، ثُمَّ أَوْتَرَ، ثُمَّ اضْطَجَعَ حَتَّى أَتَاهُ الْمُؤَذِّنُ فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ، ثُمَّ خَرَجَ فَصَلَّى الصُّبْحَ. انتهى."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (11) عن مخرمة بن سليمان، عن كريب مولى ابن عباس به مثله.","grade":"متفق عليه","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (11); al-Bukhari in al-Wudu’ (183); Muslim (182 / 763).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Kurayb, the freed slave of Ibn ‘Abbas, reported that ‘Abdullah ibn ‘Abbas told him that he spent a night at the home of Maymunah, the wife of the Prophet ﷺ, and she was his maternal aunt. He said: I lay down across the pillow, and the Messenger of Allah ﷺ and his family lay along its length. The Messenger of Allah ﷺ slept until the middle of the night—or a little before it, or a little after it—then he awoke and sat up, wiping sleep from his face with his hand. Then he recited the last ten verses of Surah Al ‘Imran. Then he went to a hanging waterskin and performed wudu’ from it, doing his wudu’ well. Then he stood to pray. Ibn ‘Abbas said: I stood up and did the same as he did. Then I went and stood beside him. The Messenger of Allah ﷺ placed his right hand on my head and took hold of my right ear, twisting it. Then he prayed two rak‘ahs, then two, then two, then two, then two, then two; then he prayed witr. Then he lay down until the caller to prayer came to him, and he prayed two light rak‘ahs, then he went out and prayed Fajr. End."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (11)، والبخاري (183)، ومسلم (182/763)."},{"num":2734,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عشر رَكْعَةً."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1138)، ومسلم في صلاة المسافرين (764) كلاهما من حديث شعبة، قال: حدثني أبو جَمْرة، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1138) and Muslim (764).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Ibn ‘Abbas said: The Messenger of Allah ﷺ used to pray thirteen rak‘ahs at night."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1138)، ومسلم (764)."},{"num":2735,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَتْ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ عَشَرَ رَكَعَاتٍ. يوتر بِسَجْدَةٍ، وَيَرْكَعُ رَكْعَتَيِ الْفَجْرِ. فَتِلْكَ ثَلَاثَ عَشَرَ رَكْعَةً."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1140)، ومسلم في صلاة المسافرين (738/128) كلاهما من حديث حنظلة، عن القاسم بن محمد قال: سمعت عائشة تقول فذكرت مثله واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1140) and Muslim (128 / 738), wording from Muslim.","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: The night prayer of the Messenger of Allah ﷺ was ten rak‘ahs. He would perform witr with a single prostration (i.e., one rak‘ah), and he would pray the two rak‘ahs of Fajr. That makes thirteen rak‘ahs."]},"buhuth":{"en":["Al-Bukhari’s wording: He used to pray thirteen rak‘ahs at night, including witr and the two rak‘ahs of Fajr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1140)، ومسلم (738/128) واللفظ لمسلم."},{"num":2736,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، أَنَّهُ أَخْبَرَهُ أَنَّهُ، سَأَلَ عَائِشَةَ: رَضِيَ اللَّهُ عَنْهَا كَيْفَ كَانَتْ صَلاَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَمَضَانَ؟ فَقَالَتْ: مَا كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَزِيدُ فِي رَمَضَانَ وَلاَ فِي غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً، يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي أَرْبَعًا فَلاَ تَسَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ، ثُمَّ يُصَلِّي ثَلاَثًا، قَالَتْ عَائِشَةُ: فَقُلْتُ يَا رَسُولَ اللَّهِ أَتَنَامُ قَبْلَ أَنْ تُوتِرَ. فَقَالَ: يَا عَائِشَةُ، إِنَّ عَيْنَىَّ تَنَامَانِ، وَلاَ يَنَامُ قَلْبِي."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (9) عن سعيد بن أبي سعيد المقبري، عن أبي سلمة بن عبدالرحمن بن عوف أنه سأل عائشة كيف كانت صلاة رسول الله صلى الله عليه وسلم  الحديث.","grade":"متفق عليه","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (9); al-Bukhari (1147); Muslim (738).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Abu Salamah ibn ‘Abd al-Rahman reported that he asked ‘A’ishah (may Allah be pleased with her): “How was the prayer of the Messenger of Allah ﷺ in Ramadan?” She said: He would not increase in Ramadan or outside of it beyond eleven rak‘ahs. He would pray four—do not ask about their beauty and their length—then he would pray four—do not ask about their beauty and their length—then he would pray three. ‘A’ishah said: I said, “O Messenger of Allah ﷺ, do you sleep before you perform witr?” He said: “O ‘A’ishah, my eyes sleep, but my heart does not sleep.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (9)، والبخاري (1147)، ومسلم (738)."},{"num":2737,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ قَالَ:  سَأَلْتُ عَائِشَةَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: كَانَ يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً. يُصَلِّي ثَمَانَ رَكَعَاتٍ، ثُمَّ يُوتِرُ. ثُمَّ يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ، فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ. ثُمَّ يُصَلِّي رَكْعَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (738/126) عن محمد بن المثنى، حدثنا ابن أبي عدي، حدثنا هشام، عن يحيى، عن أبي سلمة فذكره.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (126 / 738). Muslim also narrated it (127) and in it: I came to ‘A’ishah and said: “O Mother (of the believers)! Tell me about the prayer of the Messenger of Allah ﷺ.” She said: His prayer in Ramadan and other than Ramadan was thirteen rak‘ahs at night, including the two rak‘ahs of Fajr.","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Abu Salamah said: I asked ‘A’ishah about the prayer of the Messenger of Allah ﷺ. She said: He would pray thirteen rak‘ahs: he would pray eight rak‘ahs, then perform witr, then pray two rak‘ahs while sitting; when he wanted to bow, he would stand and bow. Then he would pray two rak‘ahs between the call to prayer and the iqamah for the Fajr prayer."]},"buhuth":{"en":["Reconciliation between the two narrations: Abu Salamah narrates once that it is “thirteen” including the two rak‘ahs before Fajr, and another time “eleven,” meaning without the two rak‘ahs of Fajr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (738/126). ورواه أيضا muslim(127) وفيه: أتيت عائشة فقلت: أي أمه! أخبريني عن صلاة رسول الله ﷺ، فقالت: كانت صلاته في شهر رمضان وغيره ثلاث عشرة ركعة بالليل، منها ركعتا الفجر."},{"num":2738,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: كَانَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِحْدَى عَشْرَةَ رَكْعَةً. كَانَتْ تِلْكَ صَلاَتَهُ -تَعْنِي بِاللَّيْلِ- فَيَسْجُدُ السَّجْدَةَ مِنْ ذَلِكَ قَدْرَ مَا يَقْرَأُ أَحَدُكُمْ خَمْسِينَ آيَةً قَبْلَ أَنْ يَرْفَعَ رَأْسَهُ. وَيَرْكَعُ رَكْعَتَيْنِ قَبْلَ صَلاَةِ الْفَجْرِ، ثُمَّ يَضْطَجِعُ عَلَى شِقِّه الأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ لِلصَّلاَةِ."],"takhrij":"صحيح: رواه البخاري في الوتر (994) ومسلم في صلاة المسافرين (736) كلاهما من طريق الزهري، عن عروة، عن عائشة فذكرته، واللفظ للبخاري.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (994) and Muslim (736), wording from al-Bukhari.","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ used to pray eleven rak‘ahs—this was his prayer at night. In one prostration of it, he would remain for as long as one of you would take to recite fifty verses before raising his head. He would pray two rak‘ahs before the Fajr prayer, then lie down on his right side until the caller came to him for the prayer."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (994) ومسلم (736)، واللفظ للبخاري."},{"num":2739,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ، قَالَ: سَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا عَنْ صَلاَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ. فَقَالَتْ: سَبْعٌ وَتِسْعٌ وَإِحْدَى عَشْرَةَ سِوَى رَكْعَتَىِ الْفَجْرِ."],"takhrij":"صحيح: رواه البخاري في التهجد (1139) عن إسحاق قال: حدثنا عبيدالله، قال: أخبرنا إسرائيل، عن أبي حصين، عن يحيى بن وثَّاب، عن مسروق فذكره.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1139).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Masruq said: I asked ‘A’ishah about the night prayer of the Messenger of Allah ﷺ, and she said: Seven, nine, and eleven (rak‘ahs), not counting the two rak‘ahs of Fajr."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1139)."},{"num":2740,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: صَلَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ، ثُمَّ صَلَّى ثَمَانَ رَكَعَاتٍ، وَرَكْعَتَيْنِ جَالِسًا، وَرَكْعَتَيْنِ بَيْنَ النِّدَاءَيْنِ، وَلَمْ يَكُنْ يَدَعُهُمَا أَبَدًا."],"takhrij":"صحيح: رواه البخاري في التهجد (1159) عن عبدالله بن يزيد، حدثنا سعيد -وهو ابن أبي أيوب، قال: حدثني جعفر بن ربيعة، عن عِراك بن مالك، عن أبي سلمة، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1159).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ prayed ‘Isha’, then prayed eight rak‘ahs, and two rak‘ahs while sitting, and two rak‘ahs between the two calls (adhan and iqamah), and he never used to leave them."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1159)."},{"num":2741,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا أخبرت أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يصلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً بِرَكْعَتَيِ الْفَجْرِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (737/124) عن قتيبة بن سعيد، حدثنا ليث، عن يزيد بن أبي حبيب، عن عِراك بن مالك، عن عروة، أن عائشة أخبرته.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (124 / 737).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah reported that the Messenger of Allah ﷺ used to pray thirteen rak‘ahs, including the two rak‘ahs of Fajr."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (737/124)."},{"num":2742,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِاللَّيْلِ ثَلاَثَ عَشْرَةَ رَكْعَةً، ثُمَّ يُصَلِّي إِذَا سَمِعَ النِّدَاءَ بِالصُّبْحِ رَكْعَتَيْنِ خَفِيفَتَيْنِ."],"takhrij":"صحيح: رواه البخاري في التهجد (1170) عن عبدالله بن يوسف، عن مالك، عن هشام بن عروة، عن أبيه، عن عائشة فذكره.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1170).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ used to pray thirteen rak‘ahs at night, then when he heard the call for Fajr he would pray two light rak‘ahs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1170)."},{"num":2743,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْ ذَلِكَ بِخَمْسٍ، لَا يَجْلِسُ فِي شَيْءٍ إِلَّا فِي آخِرِهَا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (737) من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرت مثله.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (737).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ used to pray thirteen rak‘ahs at night; he would perform witr with five (rak‘ahs), and he would not sit in any of them except in the last of them."]}},"tuhfa":{},"full":1,"rep":[2819],"tks":"صحيح: رواه مسلم (737)."},{"num":2744,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ يُصَلِّي بِاللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً، يُوتِرُ مِنْهَا بِوَاحِدَةٍ. فَإِذَا فَرَغَ مِنْهَا اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (8) عن ابن شهاب، عن عروة بن الزبير، عن عائشة فذكرته. ورواه مسلم في صلاة المسافرين (736) من طريق مالك، فذكره.","grade":"متفق عليه","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (8) and Muslim (736).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["‘A’ishah reported that the Prophet ﷺ used to pray eleven rak‘ahs at night, making witr as one (rak‘ah) from them. When he finished, he would lie down on his right side."]},"buhuth":{"en":["Muslim also narrated it, and in it: The Messenger of Allah ﷺ used to pray between finishing ‘Isha’ and Fajr: eleven rak‘ahs, giving salam after every two rak‘ahs and making witr with one. When the caller finished the adhan for Fajr and Fajr became clear to him, and the caller came to him, he would stand and pray two light rak‘ahs, then lie down on his right side until the caller came to him for the iqamah.","Al-Bukhari (1123) also narrated it, and in it: He used to pray eleven rak‘ahs—this was his prayer—prostrating in one prostration of it for as long as one of you would take to recite fifty verses before raising his head. He would pray two rak‘ahs before Fajr, then lie down on his right side until the caller came to him for the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (8) ومسلم (736)،."},{"num":2745,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن هِشَامٍ بن عَامِرٍ عَنْ عَائِشَةَ فِي حَدِيثِ طَوِيلٍ وَفِيهِ قَالَتْ عَائِشَةُ: يُصَلِّي تِسْعَ رَكَعَاتٍ، لَا يَجْلِسُ فِيهَا إِلَّا فِي الثَّامِنَةِ فَيَذْكُرُ اللهَ، وَيَحْمَدُهُ وَيَدْعُوهُ. ثُمَّ يَنْهَضُ وَلَا يُسَلِّمُ. ثُمَّ يَقُومُ فيصلِّي التَّاسِعَةَ. ثُمَّ يَقْعُدُ فَيَذْكُرُ اللهَ وَيَحْمَدُهُ وَيَدْعُوهُ. ثُمَّ يُسَلِّمُ تَسْلِيمًا يُسْمِعُنا. ثُمَّ يُصَلِّي رَكْعَتَيْنِ بَعْدَ مَا يُسَلِّم وَهُوَ قَاعِدٌ. فَتِلْكَ إِحْدَى عَشْرَةَ رَكْعَةً يَا بُنيَّ. فَلَمَّا أسَنَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، وأخذه اللَّحْمَ، أَوْتَرَ بِسَبْعٍ. وَصَنَعَ فِي الرَّكْعَتَيْنِ مِثْلَ صَنِيعِهِ الْأَوَّلِ، فَتِلْكَ تسعٌ يَا بُنيَّ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) عن محمد بن المثنى العنـزي، حدثنا محمد بن أبي عدي، عن سعيد، عن قتادة، عن زرارة، عن سعد ابن هشام بن عامر فذكره في حديث طويل سبق ذكره في باب جامع صلاة رسول الله صلى الله عليه وسلم في الليل.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (746).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Sa‘d ibn Hisham ibn ‘Amir narrated from ‘A’ishah in a long hadith. In it, ‘A’ishah said: He would pray nine rak‘ahs, not sitting in them except in the eighth, in which he would remember Allah, praise Him, and supplicate. Then he would stand without giving salam. Then he would stand and pray the ninth. Then he would sit and remember Allah, praise Him, and supplicate, then he would give salam in a way that we could hear. Then he would pray two rak‘ahs after the salam while sitting. That makes eleven rak‘ahs, my son. Then when the Prophet of Allah ﷺ became older and his body grew heavier, he performed witr as seven (rak‘ahs), and he did in the two rak‘ahs (after the salam) as he used to do before—so that makes nine, my son."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2746,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ تِسْعًا، فَلَمَّا أَسَنَّ وَثَقُلَ صَلَّى سَبْعًا."],"takhrij":"حسن: رواه النسائي (1710) عن أحمد بن سليمان، قال: حدثنا حسين، عن زائدة، عن سليمان (الأعمش) عن عُمارة بن عُمَير، عن يحيى بن الجزَّار، عن عائشة فذكرت مثله.","grade":"حسن","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Nasa’i (1710), and Imam Ahmad (24042).","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah said: The Messenger of Allah ﷺ used to pray nine (rak‘ahs) at night, but when he became older and heavier, he prayed seven."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1710)، والإمام أحمد (24042)."},{"num":2747,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ أَنَّهُ قَالَ: لأرمُقَنَّ اللَّيْلَةَ صَلَاةَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قـال: فتوسدتُ عَتَبَتَه، أَوْ فُسْـطاطَه. فَقَامَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَلَّى رَكْعَتَيْنِ طَوِيلَتَيْنِ طَوِيلَتَيْنِ طَوِيلَتَيْنِ، ثُمَّ صلَّى رَكْعَتَيْنِ، وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا، ثُمَّ صلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا. ثُمَّ أَوْتَرَ. فَتِلْكَ ثَلَاثَ عَشْرَةَ رَكْعَةً."],"takhrij":"صحيح: رواه مالك في صلاة الليل (12) عن عبدالله بن أبي بكر، عن أبيه، أن عبدالله بن قيس بن مخرمة أخبره، عن زيد بن خالد الجُهني فذكره.","grade":"صحيح","chapter_ar":"باب في عدد صلاة رسول اللٰه ﷺ في الليل وأن الوتر من ركعة إلى تسع ركعات","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Malik (12) and Muslim (765), except that Muslim’s version begins: “Then he prayed two light rak‘ahs…”","chapter_en":"The number of the Messenger of Allah’s ﷺ prayers at night, and that witr may be from one rak‘ah up to nine rak‘ahs.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":24,"content":{"translation":{"en":["Zayd ibn Khalid al-Juhani said: “Tonight I will observe the prayer of the Messenger of Allah ﷺ.” He said: I placed my head on his threshold, or at his tent. The Messenger of Allah ﷺ stood and prayed two rak‘ahs—very long, very long, very long—then he prayed two rak‘ahs that were shorter than the two before them; then two rak‘ahs shorter than those before; then two rak‘ahs shorter than those before; then two rak‘ahs shorter than those before; then two rak‘ahs shorter than those before. Then he performed witr. That totals thirteen rak‘ahs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (12) ورواه مسلم (765) إلا أنه قال في أول الحديث: (( فصلى ركعتين خفيفتين … ))."},{"num":2748,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَجُلاً، سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلاَةِ اللَّيْلِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةُ اللَّيْلِ مَثْنَى مَثْنَى، فَإِذَا خَشِيَ أَحَدُكُمُ الصُّبْحَ صَلَّى رَكْعَةً وَاحِدَةً، تُوتِرُ لَهُ مَا قَدْ صَلَّى."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (13) عن نافع وعبدالله بن دينار، عن عبدالله بن عمر فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب صلاة الليل مثنى مثنى، والوتر ركعةٌ من آخر الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (13), al-Bukhari (990), and Muslim (749). Muslim also narrated a version in which a man asked the Prophet ﷺ while I was between him and the questioner, and he said: “Two-by-two. If you fear dawn will reach you, then pray one rak‘ah, and make the last of your prayer witr.”","chapter_en":"Night prayer is two-by-two, and witr is one rak‘ah at the end of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":25,"content":{"translation":{"en":["Ibn ‘Umar reported that a man asked the Messenger of Allah ﷺ about the night prayer. The Messenger of Allah ﷺ said: “The night prayer is two-by-two. If one of you fears the coming of dawn, let him pray one rak‘ah to make witr for what he has already prayed.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2813],"tks":"متفق عليه: رواه مالك (13) والبخاري (990)، ومسلم (749). ورواه مسلم أيضا وفيه: أن رجلا سأل النبي ﷺ، وأنا بينه وبين السائل. فقال: يا رسول الله! كيف صلاة الليل؟ قال: (( مثنى مثنى. فإذا خشيت الصبح فصل ركعة. واجعل آخر صلاتك وترا)).."},{"num":2749,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ سِيرِينَ قَالَ:  سَأَلْتُ ابْنَ عُمَرَ، قُلْتُ: أَرَأَيْتَ الرَّكْعَتَيْنِ قَبْلَ صَلَاةِ الْغَدَاةِ؟ أَأُطِيلُ فِيهِمَا الْقِرَاءَةَ؟ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى، وَيُوتِرُ بِرَكْعَةٍ. قَالَ: قُلْتُ: إِنِّي لَسْتُ عَنْ هَذَا أَسْأَلُكَ. قَالَ: إِنَّكَ لَضَخْمٌ! أَلَا تَدَعُنِي أَسْتَقْرِئُ لَكَ الْحَدِيثَ؟ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ مَثْنَى مَثْنَى وَيُوتِرُ بِرَكْعَةٍ، وَيُصَلِّي رَكْعَتَيْنِ قَبْلَ الْغَدَاةِ كَأَنَّ الْأَذَانَ بِأُذُنَيْهِ.","وفي رواية: فقال: بَهْ بَهْ إنك لضخمٌ.","وفي رواية: قَالَ رَسُولَ اللهِ صلى الله عليه وسلم : صَلَاةُ اللَّيْلِ مَثْنَى مَثْنَى. فَإِذَا رَأَيْتَ أَنَّ الصُّبْحَ يُدْرِكُكَ فَأَوْتِرْ بِوَاحِدَةٍ ، فَقِيلَ لِابْنِ عُمَرَ: مَا مَثْنَى مَثْنَى؟ قَالَ: أَنْ يُسَلِّمَ فِي كُلِّ رَكْعَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الوتر (995)، ومسلم في صلاة المسافرين (749/157) كلاهما من حديث حماد بن زيد، قال: حدثنا أنس بن سيرين، عن ابن عمر فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب صلاة الليل مثنى مثنى، والوتر ركعةٌ من آخر الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (995) and Muslim (157 / 749). The second narration is in Muslim.","chapter_en":"Night prayer is two-by-two, and witr is one rak‘ah at the end of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":25,"content":{"translation":{"en":["Anas ibn Sirin said: I asked Ibn ‘Umar, “What about the two rak‘ahs before the Fajr prayer—should I lengthen the recitation in them?” He said: The Messenger of Allah ﷺ used to pray at night two-by-two and perform witr with one rak‘ah. I said: “That is not what I am asking about.” He said: “You are certainly dull/heavy. Won’t you let me complete the hadith for you?” The Messenger of Allah ﷺ used to pray at night two-by-two and perform witr with one rak‘ah, and he would pray the two rak‘ahs before Fajr immediately after the adhan. In another narration he said: “Bah, bah! You are certainly dull.”","In another narration: The Messenger of Allah ﷺ said: “The night prayer is two-by-two. If you see that dawn will catch up with you, then perform witr with one.” It was said to Ibn ‘Umar: “What does ‘two-by-two’ mean?” He said: “That one gives salam after every two rak‘ahs.”"]},"buhuth":{"en":["His phrase “You are certainly ضخم” is taken as a rebuke indicating dullness/heaviness and poor etiquette; they said this description is often used for the “bulky/heavy” person. He said it because the questioner interrupted him before he finished the hadith.","“Bah, bah” (به به): with a bā’ followed by a still hā’, repeated; it is said to mean “Stop, stop”—a reprimand and a command to desist."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (995)، ومسلم (749/157). والرواية الثانية رواها مسلم."},{"num":2750,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ حَدَّثَهُمْ  أَنَّ رَجُلًا نَادَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي الْمَسْجِدِ، فَقَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ أُوتِرُ صَلَاةَ اللَّيْلِ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ صَلَّى فَلْيُصَلِّ مَثْنَى مَثْنَى، فَإِنْ أَحَسَّ أَنْ يُصْبِحَ سَجَدَ سَجْدَةً فَأَوْتَرَتْ لَهُ مَا صَلَّى."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (749) من حديث أبي أسامة، عن الوليد بن كثير، قال: حدثني عبيدالله بن عبدالله بن عمر، أن ابن عمر حدَّثهم، فذكره.","grade":"صحيح","chapter_ar":"باب صلاة الليل مثنى مثنى، والوتر ركعةٌ من آخر الليل","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (749).","chapter_en":"Night prayer is two-by-two, and witr is one rak‘ah at the end of the night.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":25,"content":{"translation":{"en":["‘Abdullah ibn ‘Umar reported that a man called out to the Messenger of Allah ﷺ while he was in the mosque and said: “O Messenger of Allah ﷺ! How should I perform witr for the night prayer?” The Messenger of Allah ﷺ said: “Whoever prays should pray two-by-two; then if he senses that morning is about to come, let him perform one prostration (i.e., one rak‘ah) and it will make witr for what he has prayed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (749)."},{"num":2751,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ:مَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي سُبْحَتِهِ قَاعِدًا قطُّ حَتَّى كَانَ قَبْلَ وَفَاتِهِ بِعَامٍ، فَكَانَ يُصَلِّي فِي سُبحتِـه قَاعِدًا، وَيَقْرَأُ بِالسُّورَةِ فيرتِّلُها، حَتَّى تَكُونَ أَطْوَلَ مِنْ أَطْوَلَ مِنْهَا."],"takhrij":"صحيح: رواه مالك في صلاة الجماعة (21) عن ابن شهاب، عن السائب بن يزيد، عن المطَّلِب بن أبي وداعة، السهمي، عن حفصة فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء من صلاة النبي النافلة قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Malik (21) and Muslim (733).","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary (nafl) prayer while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":26,"content":{"translation":{"en":["Hafsah, the wife of the Prophet ﷺ, said: I never saw the Messenger of Allah ﷺ pray his voluntary prayer while sitting at all—until a year before his death. Then he began to pray his voluntary prayer while sitting, and he would recite a surah slowly and distinctly, until its recitation would take longer than that of a surah longer than it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (21)، ومسلم (733)."},{"num":2752,"demo":false,"sanad":"","matn":["عن جابر بْنِ سَمُرَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَمُتْ حَتَّى صَلَّى قَاعِدًا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (734) عن أبي بكر بن أبي شيبة، حدثنا عبيدالله بن موسى، عن حسن بن صالح، عن سماك، قال: أخبرني جابر بن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء من صلاة النبي النافلة قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (734).","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary (nafl) prayer while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":26,"content":{"translation":{"en":["Jabir ibn Samurah reported that the Prophet ﷺ did not die until he had prayed while sitting."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (734)."},{"num":2753,"demo":false,"sanad":"","matn":["أَنَّ عَائِشَةَ أَخْبَرَتْهُ  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَمُتْ حَتَّى كَانَ كَثِيرٌ مِنْ صَلَاتِهِ وَهُوَ جَالِسٌ."],"takhrij":"صحيح: رواه مسلم في المسافرين (732/116) من حديث ابن جريج، قال: أخبرني عثمان بن أبي سليمان، أن أبا سلمة بن عبدالرحمن أخبره، أن عائشة أخبرته فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء من صلاة النبي النافلة قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (732) (hadith no. 116 in that section).","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary (nafl) prayer while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":26,"content":{"translation":{"en":["‘A’ishah informed that the Prophet ﷺ did not die until much of his prayer was while sitting."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (732/116)."},{"num":2754,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن أَبِي قيس قَالَ: قَالَتْ عَائِشَةُ رَضِيَ اللَّهِ عَنْهَا: : لاَ تدعْ قِيَامَ اللَّيْلِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يَدَعُهُ، وَكَانَ إِذَا مَرِضَ أَوْ كَسِلَ صَلَّى قَاعِدًا."],"takhrij":"صحيح: رواه أبو داود (1307) عن محمد بن بشار، قال: حدثنا أبو داود (وهو الطّيالسيّ) ـ والحديث في \"مسنده\" (1519) ـ، قال: حدثنا شعبةُ، عن يزيد بن خُمير قال: سمعت عبدالله بن أبي قيس فذكره.","grade":"صحيح","chapter_ar":"باب ماجاء من صلاة النبي النافلة قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Abu Dawud (1307). Also authenticated by Ibn Khuzaymah (1137) and al-Hakim (1/308).","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary (nafl) prayer while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":26,"content":{"translation":{"en":["‘Abdullah ibn Abi Qays said: ‘A’ishah (may Allah be pleased with her) said: Do not abandon night prayer, for the Messenger of Allah ﷺ never used to abandon it; and if he became ill or felt lazy, he would pray while sitting."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2681],"tks":"صحيح: رواه أبو داود (1307)، وقد صححه ابن خزيمة (1137)، والحاكم (1158)."},{"num":2755,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: مَا مَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى كَانَ أَكْثَرَ صَلَاتِهِ قَاعِدًا إِلَّا الْمَكْتُوبَةَ، وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ، مَا دَاوَمَ عَلَيْهِ الْعَبْدُ، وَإِنْ كَانَ يَسِيرًا."],"takhrij":"صحيح: رواه النسائي (1654)، والإمام أحمد (26709) كلاهما من حديث شعبة، عن أبي إسحاق قال: سمعت أبا سلمة، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ماجاء من صلاة النبي النافلة قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Nasa’i (1654), Imam Ahmad (26709), and Ibn Majah (1225).","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary (nafl) prayer while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":26,"content":{"translation":{"en":["Umm Salamah said: The Messenger of Allah ﷺ did not die until most of his prayer was while sitting—except the obligatory prayer. And the most beloved deeds to him were those a servant consistently maintained, even if small."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1654)، والإمام أحمد (26709)، وابن ماجه ( 1225)."},{"num":2756,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن شَقِيقٍ العُقيلي قَالَ: سَأَلْتُ عَائِشَةَ عَنْ صَلَاةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِاللَّيْلِ فَقَالَتْ: كَانَ يصلِّي لَيْلًا طَوِيلًا قَائِمًا. وَلَيْلًا طَوِيلًا قَاعِدًا، وَكَانَ إِذَا قَرَأَ قَائِمًا رَكَعَ قَائِمًا، وَإِذَا قَرَأَ قَاعِدًا رَكَعَ قَاعِدًا."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (730/109) عن أبي بكر بن أبي شيبة، حدثنا معاذ بن معاذ، عن حُميد، عن عبدالله بن شقيق العُقيلي فذكره. ورواه من حديث محمد بن سيرين، عن عبدالله بن شقيق عنها وفيه: كان رسول الله صلى الله عليه وسلم يُكثر الصلاة قائماً وقاعداً. فإذا افتتح الصلاة قائماً ركع قائماً، وإذا افتتح الصلاة قاعداً ركع قاعداً .","grade":"صحيح","chapter_ar":"باب في صلاة النبي إذا افتتح قائماً ركع قائماً وإذا افتتح قاعداً ركع قاعداً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (730) (hadith no. 109 in that section). Muslim also narrates: “The Messenger of Allah ﷺ used to pray frequently while standing and while sitting; if he began the prayer standing, he bowed standing; and if he began the prayer sitting, he bowed sitting.”","chapter_en":"Regarding the Prophet’s ﷺ prayer: if he began standing, he bowed while standing; and if he began sitting, he bowed while sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":27,"content":{"translation":{"en":["‘Abdullah ibn Shiqiq al-‘Uqayli said: I asked ‘A’ishah about the Messenger of Allah’s ﷺ prayer at night. She said: “He would pray long at night while standing, and long at night while sitting. If he recited while standing, he bowed while standing; and if he recited while sitting, he bowed while sitting.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (730/109)، ورواه أيضا وفيه: (( كان رسول الله ﷺ يكثر الصلاة قائما وقاعدا. فإذا افتتح الصلاة قائما ركع قائما، وإذا افتتح الصلاة قاعدا ركع قاعدا»."},{"num":2757,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أُمِّ الْمُؤْمِنِينَ أَنَّهَا أَخْبَرَتْهُ أَنَّهَا لَمْ تَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلاَةَ اللَّيْلِ قَاعِدًا قَطُّ حَتَّى أَسَنَّ، فَكَانَ يَقْرَأُ قَاعِدًا. حَتَّى إِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ، فَقَرَأَ نَحْوًا مِنْ ثَلاَثِينَ، آيَةً أَوْ أَرْبَعِينَ آيَةً، ثُمَّ رَكَعَ."],"takhrij":"متفق عليه: رواه مالك في صلاة الجماعة (22) عن هشام بن عروة، عن أبيه، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب ماجاء في صلاة النبي ﷺ النافلة بعضها قاعداً وبعضها قائماً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (22), al-Bukhari (1118), and Muslim (731). In it she said: I did not see the Messenger of Allah ﷺ recite while sitting in any of the night prayer until he became older; then he would recite sitting, and when about thirty or forty verses remained from the surah, he would stand to recite them, then bow.","chapter_en":"What has been narrated about the Prophet’s ﷺ voluntary prayer: some of it sitting and some of it standing.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":28,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, reported that she did not see the Messenger of Allah ﷺ pray the night prayer while sitting at all until he became older. Then he would recite while sitting; and when he wanted to bow, he would stand and recite about thirty or forty verses, then bow."]},"buhuth":{"en":["Malik (23), al-Bukhari (1119), and Muslim (731) (hadith no. 112) also narrate: The Messenger of Allah ﷺ used to pray sitting and recite while sitting; when about thirty or forty verses remained of his recitation, he would stand to recite while standing, then bow and prostrate, and he would do the same in the second rak‘ah.","Commentary: The hadiths of these two chapters indicate both ways are permissible: a person may begin standing and bow standing; or begin sitting and bow sitting or standing. There is no contradiction between the reports. All of this is regarding voluntary prayers. And Allah knows best."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (22) والبخاري (1118)، ومسلم (731) وفيه: قالت: ما رأيت رسول الله ﷺ يقرأ في شيء من صلاة الليل جالسا. حتى إذا كبر قرأ جالسا، حتى إذا بقي عليه من السورة ثلاثون أو أربعون آية قام فقرأهن، ثم ركع."},{"num":2758,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ-وَكَانَ مبسوراً- قـال: سَأَلْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ صَلاَةِ الرَّجُلِ قَاعِدًا فَقَالَ: إِنْ صَلَّى قَائِمًا فَهْوَ أَفْضَلُ، وَمَنْ صَلَّى قاعـــداً فَلَهُ نِصْفُ أَجْرِ القــــائم، وَمَنْ صَلَّى نَائِمًا فلــــه نِصْفُ أَجْرِ الْقَاعِدِ ."],"takhrij":"صحيح: رواه البخاري في تقصير الصلاة (1115،1116،1117) من طريق عن حسين المعلم، عن عبدالله بن بريدة، عن عمران بن حصين فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أجر صلاة القاعد على النصف من صلاة القائم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (1115, 1116, 1117). In another narration: “If you are not able, then (pray) on your side.”","chapter_en":"What has been narrated that the reward of the one who prays sitting is half the reward of the one who prays standing.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":29,"content":{"translation":{"en":["‘Imran ibn Husayn—who had hemorrhoids—said: I asked the Messenger of Allah ﷺ about a man praying while sitting. He said: “If he prays standing, that is better. Whoever prays sitting has half the reward of the one standing, and whoever prays lying down has half the reward of the one sitting.”"]},"buhuth":{"en":["His statement: “If he prays standing, that is better” is understood to refer to voluntary (nafl) prayer, because performing the obligatory prayers while sitting—when one is able to stand—is not permissible.","And his statement: “If you are not able, then (pray) on your side” applies to a sick person who is unable to stand. In that case, there is no reduction in reward for him, Allah willing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (1115،1116،1117). وفي رواية: (( فإن لم تستطع فعلى جنب»."},{"num":2759,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ عَمْرٍو قَالَ: حُدِّثْتُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  صَلَاةُ الرَّجُلِ قَاعِدًا نِصْفُ الصَّلَاةِ. قَالَ: فَأَتَيْتُهُ فَوَجَدْتُهُ يُصَلِّي جَالِسًا، فَوَضَعْتُ يَدِي عَلَى رَأْسِهِ فَقَالَ: مَا لَكَ يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو؟ قُلْتُ: حُدِّثْتُ يَا رَسُولَ اللَّهِ أَنَّكَ قُلْتَ: صَلَاةُ الرَّجُلِ قَاعِدًا عَلَى نِصْفِ الصَّلَاةِ، وَأَنْتَ تُصَلِّي قَاعِدًا؟ قَالَ: أَجَلْ، وَلَكِنِّي لَسْتُ كَأَحَدٍ مِنْكُمْ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (735) عن زهير بن حرب، حدثنا جرير، عن منصور، عن هلال بن يساف، عن أبي يحيى، عن عبدالله بن عمرو فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن أجر صلاة القاعد على النصف من صلاة القائم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (735).","chapter_en":"What has been narrated that the reward of the one who prays sitting is half the reward of the one who prays standing.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":29,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr said: I was told that the Messenger of Allah ﷺ said: “A man’s prayer while sitting is half of the prayer (i.e., half the reward).” He said: So I went to him and found him praying while sitting. I placed my hand on my head, and he said: “What is the matter, O ‘Abdullah ibn ‘Amr?” I said: O Messenger of Allah, I was told that you said: “A man’s prayer while sitting is half of the prayer,” yet you are praying while sitting. He said: “Yes, but I am not like any of you.”"]},"buhuth":{"en":["Commentary: His words “I am not like any of you” are among the special characteristics of the Prophet ﷺ: his voluntary prayer while sitting—despite being able to stand—was made equal to his voluntary prayer while standing, as an honor for him, just as he was given other special distinctions."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (735). وقوله: (( لست كأحد منكم)) هو من خصائص النبي ﷺ فجعلت نافلته قاعدا."},{"num":2760,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مُتَرَبِّعًا."],"takhrij":"صحيح: رواه النسائي (1661) عن هارون بن عبدالله قال: حدثنا أبو داود الحُفَري، عن حفص، عن حُميد، عن عبدالله بن شقيق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب التربُّع في الصلاةِ إذا صلى جالساً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Nasa’i (1661) and al-Bayhaqi (2/305).","chapter_en":"Sitting cross-legged in prayer when one prays sitting.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":30,"content":{"translation":{"en":["‘A’ishah said: I saw the Prophet ﷺ praying while sitting cross-legged."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3004],"tks":"صحيح: رواه النسائي (1661)، والبيهقي (3662)."},{"num":2761,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ نَامَ عَنْ حِزْبِهِ، أَوْ عَنْ شَيْءٍ مِنْهُ، فَقَرَأَهُ فِيمَا بَيْنَ صَلَاةِ الْفَجْرِ وَصَلَاةِ الظُّهْرِ، كُتِبَ لَهُ كَأَنَّمَا قَرَأَهُ مِنَ اللَّيْلِ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (747) من حديث ابن وهب، عن يونس بن يزيد، عن ابن شهاب، عن السائِب بن يزيد وعبيدالله بن عبدالله، أخبراه عن عبدالرحمن بن عبدٍ القاريُّ، قال: سمعت عمر بن الخطاب فذكره.","grade":"صحيح","chapter_ar":"باب ذكر من نوى قيام الليل فغلبه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (747).","chapter_en":"Mention of the one who intended to stand for night prayer but was overcome by sleep.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":31,"content":{"translation":{"en":["‘Umar ibn al-Khattab said: The Messenger of Allah ﷺ said: “Whoever sleeps and misses his regular portion (ḥizb), or part of it, then recites it between the Fajr prayer and the Dhuhr prayer, it will be written for him as though he recited it at night.”"]},"buhuth":{"en":["Commentary: “Ḥizb” means what a person assigns for himself as a regular portion of recitation or prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (747). والحزب: ما يجعله الرجل على نفسه من قراءة أو صلاة."},{"num":2762,"demo":false,"sanad":"","matn":["عَنْ أَبِي الدَّرْدَاءِ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَتَى فِرَاشَهُ، وَهُوَ يَنْوِي أَنْ يَقُومَ فَيُصَلِّيَ مِنَ اللَّيْلِ فَغَلَبَتْهُ عَيْنُهُ حَتَّى يُصْبِحَ - كُتِبَ لَهُ مَا نَوَى، وَكَانَ نَوْمُهُ صَدَقَةً عَلَيْهِ مِنْ رَبِّهِ."],"takhrij":"حسن: رواه النسائي (1787)، وابن ماجه (1344) كلاهما عن هارون بن عبدالله الحمَّال، قال: حدثنا الحسين بن علي الجُعفي، عن زائدة، عن سليمان الأعمش، عن حبيب بن أبي ثابت، عن عبدة بن أبي لُبابة، عن سُويد بن غَفَلَة، عن أبي الدرداء فذكره.","grade":"حسن","chapter_ar":"باب ذكر من نوى قيام الليل فغلبه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: al-Nasa’i (1787), Ibn Majah (1344), Ibn Khuzaymah (1172), and al-Hakim (1/311).","chapter_en":"Mention of the one who intended to stand for night prayer but was overcome by sleep.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":31,"content":{"translation":{"en":["Abu al-Darda’ narrated it up to the Prophet ﷺ: “Whoever goes to his bed intending to get up and pray at night, but his eyes overpower him until morning, will have written for him what he intended; and his sleep will be a charity for him from his Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1787)، وابن ماجه (1344) وابن خزيمة (1172)، والحاكم (1170)."},{"num":2763,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: قَالَ: رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : مَا مِنِ امْرِئٍ تَكُونُ لَهُ صَلاَةٌ بِلَيْلٍ يغلِبُه عَلَيْهَا نومٌ إِلاَّ كَتَبَ اللَّهُ لَهُ أَجْرَ صَلاَتِهِ، وَكَانَ نَوْمُهُ عَلَيْهِ صَدَقَةً ."],"takhrij":"حسن: رواه مالك في صلاة الليل (1) عن محمد بن المنكدر، عن سعيد بن جبير، عن رجل عنده رضاً، أنه أخبره أن عائشة أخبرت فذكرت الحديث.","grade":"حسن","chapter_ar":"باب ذكر من نوى قيام الليل فغلبه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: Malik (1), Abu Dawud (1314), and al-Nasa’i (1785).","chapter_en":"Mention of the one who intended to stand for night prayer but was overcome by sleep.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":31,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Messenger of Allah ﷺ said: “There is no person who has a night prayer, but sleep overcomes him (so he misses it), except that Allah writes for him the reward of his prayer; and his sleep is a charity for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (1) و أبو داود (1314)، والنسائي ( 1785)."},{"num":2764,"demo":false,"sanad":"","matn":["عَنْ جُنْدَبِ بْنِ عَبْدِ اللَّهِ الْبَجَلِيِّ قَالَ: اشْتَكَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَقُمْ لَيْلَةً أَوْ لَيْلَتَيْنِ.","متفق عليه: رواه البخاري في التهجد (1124) عن أبي نُعيم، قال: حدثنا سفيان، عن الأسود بن قيس قال: سمعتُ جندباً يقول فذكر الحديث هكذا مختصراً، وساقه في فضائل القرآن تاماً (4983) عن أبي نُعيم، حدثنا سفيان، عن الأسود بن قيس قال: سمعتُ جندباً يقول: اشتكى النبي صلى الله عليه وسلم فلم يَقُم ليلةً، أو ليلتين، فأتتْه امرأةٌ فقالت: يا محمد: ما أرى شيطانك إلا قد تركك. فأنزل الله عزوجل: ﴿وَالضُّحَى (1) وَاللَّيْلِ إِذَا سَجَى (2) مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى (3)﴾ [سورة الضحى:1-3]."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1124) عن أبي نُعيم، قال: حدثنا سفيان، عن الأسود بن قيس قال: سمعتُ جندباً يقول فذكر الحديث هكذا مختصراً، وساقه في فضائل القرآن تاماً (4983) عن أبي نُعيم، حدثنا سفيان، عن الأسود بن قيس قال: سمعتُ جندباً يقول: اشتكى النبي صلى الله عليه وسلم فلم يَقُم ليلةً، أو ليلتين، فأتتْه امرأةٌ فقالت: يا محمد: ما أرى شيطانك إلا قد تركك. فأنزل الله عزوجل: وَالضُّحَى (1) وَاللَّيْلِ إِذَا سَجَى (2) مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَى (3) [سورة الضحى:1-3].","grade":"متفق عليه","chapter_ar":"باب ترك القيام للمريض","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1124) and Muslim (1797) (hadith no. 115 in that section).","chapter_en":"Leaving off standing (in night prayer) for the sick person.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":32,"content":{"translation":{"en":["Jundub ibn ‘Abdullah al-Bajali said: The Prophet ﷺ became ill and did not stand (for night prayer) for one night or two."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1124) ومسلم (115/1797)."},{"num":2765,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا صَلَّى صَلَاةً أَحَبَّ أَنْ يُدَاوِمَ عَلَيْهَا، وَكَانَ إِذَا غَلَبَهُ نَوْمٌ، أَوْ وَجَعٌ عَنْ قِيَامِ اللَّيْلِ صَلَّى مِنَ النَّهَارِ ثِنْتَيْ عَشْرَةَ رَكْعَةً. وَلَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا صَلَّى لَيْلَةً إِلَى الصُّبْحِ، وَلَا صَامَ شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) عن محمد بن المثنى العنـزي، حدثنا محمد بن أبي عدي، عن سعيد، عن قتادة، عن زرارة، أن سعد بن هشام بن عامر أراد أن يغزو في سبيل الله، فقدم المدينة وسألَ أم المؤمنين عائشة عن أشياء منها عن صلاة رسول الله صلى الله عليه وسلم في الليل فذكرت مثله في حديث طويل.","grade":"صحيح","chapter_ar":"باب قضاء صلاة الليل بالنهار إذا فاتت لمرض أو شغل أو نوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (746).","chapter_en":"Making up the night prayer by day if it was missed due to illness, being occupied, or sleep.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":33,"content":{"translation":{"en":["‘A’ishah said: When the Prophet of Allah ﷺ prayed a prayer, he liked to continue doing it regularly. If sleep overcame him, or pain prevented him from standing for night prayer, he would pray twelve rak‘ahs during the day. And I do not know that the Prophet of Allah ﷺ ever recited the entire Qur’an in one night, nor that he prayed a whole night until morning, nor that he fasted a complete month other than Ramadan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2766,"demo":false,"sanad":"","matn":["عن خَبَّاب بْنِ الأرَتِّ عَنْ أَبِيهِ، قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلاَةً فَأَطَالَهَا قَالُوا يَا رَسُولَ اللَّهِ! صَلَّيْتَ صَلاَةً لَمْ تَكُنْ تُصَلِّيهَا. قَالَ: أَجَلْ، إِنَّهَا صَلاَةُ رَغْبَةٍ وَرَهْبَةٍ، إِنِّي سَأَلْتُ اللَّهَ فِيهَا ثَلاَثًا، فَأَعْطَانِي اثْنَتَيْنِ، وَمَنَعَنِي وَاحِدَةً، سَأَلْتُهُ أَنْ لاَ يُهْلِكَ أُمَّتِي بِسَنَةٍ فَأَعْطَانِيهَا، وَسَأَلْتُهُ أَنْ لاَ يُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ غَيْرِهِمْ، فَأَعْطَانِيهَا، وَسَأَلْتُهُ أَنْ لاَ يُذِيقَ بَعْضَهُمْ بَأْسَ بَعْضٍ فَمَنَعَنِيهَا."],"takhrij":"صحيح: رواه الترمذي (2175)، والنسائي (1638) كلاهما من حديث الزهري، قال: أخبرني عبيدالله بن عبدالله بن الحارث بن نوفل، عن عبدالله ابن خبَّاب بن الأَرَتِّ، عن أبيه فذكر الحديث واللفظ للترمذي.","grade":"صحيح","chapter_ar":"باب ما جاء في إحياء معظم الليلة أو كلّها أحياناً","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by al-Tirmidhi (2175) and al-Nasa’i (1638); the wording is al-Tirmidhi’s. He said: “Hasan Sahih Gharib.”","chapter_en":"What has been reported about reviving most of the night, or all of it, on some occasions.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":34,"content":{"translation":{"en":["Khabbab ibn al-Aratt said: The Messenger of Allah ﷺ prayed a prayer and prolonged it. They said: O Messenger of Allah, you have prayed a prayer you did not use to pray. He said: “Yes. It is a prayer of desire and fear. I asked Allah for three things in it: He granted me two and withheld one. I asked Him that He not destroy my ummah by a year (of drought/famine), so He granted it. I asked Him that He not allow an enemy from other than themselves to overpower them, so He granted it. And I asked Him that He not make some of them taste the violence of others, so He withheld it.”"]},"buhuth":{"en":["Wording of al-Nasa’i: He (Khabbab) watched the Messenger of Allah ﷺ the entire night until close to Fajr. When the Messenger of Allah ﷺ gave salam from his prayer, Khabbab came to him and said: O Messenger of Allah, may my father and mother be sacrificed for you—tonight you prayed a prayer the like of which I have never seen you pray. The Messenger of Allah ﷺ said: “Yes,” then mentioned the hadith, and in it: “I asked my Lord, Mighty and Majestic, that He not destroy us in the way He destroyed the nations before us—so He granted it. And I asked my Lord, Mighty and Majestic, that He not give an enemy other than ourselves dominance over us—so He granted it. And I asked my Lord that He not clothe us in factions (make us into sects/parties)—so He withheld it.”","Commentary: His phrase “a prayer of رغبة and رهبة” means: a prayer in which I supplicated with hopeful desire for acceptance and with fearful dread of rejection."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15853],"tks":"صحيح: رواه الترمذي (2175)، والنسائي (1638) واللفظ للترمذي. وقال: (( حسن صحيح غريب))."},{"num":2767,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: وَلَا أَعْلَمُ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَرَأَ الْقُرْآنَ كُلَّهُ فِي لَيْلَةٍ، وَلَا صَلَّى لَيْلَةً إِلَى الصُّبْحِ، وَلَا صَامَ شَهْرًا كَامِلًا غَيْرَ رَمَضَانَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (746) في حديث طويل في جامع صلاة الليل من طريق قتادة، عن زرارة، عن سعد بن هشام بن عامر، عن عائشة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب كراهية إحياء الليلة كلها بالصلاة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (746).","chapter_en":"The disliked nature of reviving the entire night with prayer.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":35,"content":{"translation":{"en":["‘A’ishah said: I do not know that the Prophet of Allah ﷺ ever recited the entire Qur’an in one night, nor that he prayed a whole night until morning, nor that he fasted a complete month other than Ramadan."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (746)."},{"num":2768,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا نَعَسَ أَحَدُكُمْ وَهُوَ يُصَلِّي فَلْيَرْقُدْ حَتَّى يَذْهَبَ عَنْهُ النَّوْمُ، فَإِنَّ أَحَدَكُمْ إِذَا صَلَّى وَهُوَ نَاعِسٌ لاَ يَدْرِي لَعَلَّهُ يَسْتَغْفِرُ فَيَسُبَّ نَفْسَهُ."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (3) عن هشام بن عروة، عن أبيه، عن عائشة فذكرت مثله.","grade":"متفق عليه","chapter_ar":"باب من نَعَس في صلاته فليرقد حتى يذهب عنه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (3), al-Bukhari (212), and Muslim (786).","chapter_en":"Whoever becomes drowsy in his prayer should lie down until the sleepiness goes away.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":36,"content":{"translation":{"en":["‘A’ishah narrated that the Messenger of Allah ﷺ said: “If one of you becomes drowsy while praying, then let him lie down until the sleepiness goes away. For if one of you prays while drowsy, he may not realize—perhaps he intends to seek forgiveness but ends up insulting himself.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (3) والبخاري (212)، ومسلم (786)."},{"num":2769,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا نَعَسَ أَحَدُكُمْ فِي الصَّلاَةِ فَلْيَنَمْ حَتَّى يَعْلَمَ مَا يَقْرَأُ."],"takhrij":"صحيح: رواه البخاري في الوضوء (213) عن أبي معمر، قال: حدثنا عبد الوارث، حدثنا أيوب، عن أبي قِلابة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب من نَعَس في صلاته فليرقد حتى يذهب عنه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: al-Bukhari (213).","chapter_en":"Whoever becomes drowsy in his prayer should lie down until the sleepiness goes away.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":36,"content":{"translation":{"en":["Anas ibn Malik narrated from the Prophet ﷺ: “If one of you becomes drowsy in prayer, then let him sleep until he knows what he is reciting.”"]},"buhuth":{"en":["Al-Nasa’i (443) also narrated it with the wording: “If one of you becomes drowsy in his prayer, let him leave (the prayer) and lie down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (213)."},{"num":2770,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِذَا قَامَ أَحَدُكُمْ مِنَ اللَّيْلِ فَاسْتَعْجَمَ الْقُرْآنُ عَلَى لِسَانِهِ فَلَمْ يَدْرِ مَا يَقُولُ: فَلْيَضْطَجِعْ ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (787) عن محمد بن رافع، حدثنا عبدالرزاق، حدثنا معمر، عن همام بن مُنَبِّه قال: هذا ما حدثنا أبو هريرة، عن محمد رسول الله صلى الله عليه وسلم فذكر أحاديث منها هذا.","grade":"صحيح","chapter_ar":"باب من نَعَس في صلاته فليرقد حتى يذهب عنه النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (787).","chapter_en":"Whoever becomes drowsy in his prayer should lie down until the sleepiness goes away.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":36,"content":{"translation":{"en":["Abu Hurayrah said: The Messenger of Allah ﷺ said: “If one of you stands at night (to pray) and the Qur’an becomes unclear on his tongue so he does not know what he is saying, then let him lie down.”"]},"buhuth":{"en":["Commentary: “فاستعجم” means: it became unclear/obscure and difficult to articulate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (787). وقوله: (( فاستعجم) أي: استبهم واستغلق."},{"num":2771,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ، قَالَ: سَأَلْتُ أُمَّ الْمُؤْمِنِينَ عَائِشَةَ قُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ: كَيْفَ كَانَ عَمَلُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَلْ كَانَ يَخُصُّ شَيْئًا مِنَ الأَيَّامِ؟ قَالَتْ: لاَ، كَانَ عَمَلُهُ دِيمَةً، وَأَيُّكُمْ يَسْتَطِيعُ مَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَطِيعُ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6466)، ومسلم في صلاة المسافرين (783) من حديث جرير، عن منصور، عن إبراهيم، عن علقمة فذكره.","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (6466) and Muslim (783).","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["‘Alqamah said: I asked the Mother of the Believers ‘A’ishah: How was the Prophet’s ﷺ practice—did he single out any particular days? She said: No. His deeds were consistent and continuous. And which of you can do what the Prophet ﷺ was able to do?"]}},"tuhfa":{},"full":1,"rep":[15286],"tks":"متفق عليه: رواه البخاري (6466)، ومسلم (783)."},{"num":2772,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ ، قَالَ: : سَأَلْتُ عَائِشَةَ: أَيُّ الْعَمَلِ كَانَ أَحَبَّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ؟ فَقَالَتْ: : الدَّائِمُ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1132)، ومسلم في صلاة المسافرين (741) كلاهما من طريق أبي الأحوص، عن الأشعث بن سُليم، عن أبيه، عن مسروق فذكر الحديث، انظر باب قيام النبي صلى الله عليه وسلم في أوقات مختلفة من الليل.","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1132) and Muslim (741).","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["Masruq said: I said to ‘A’ishah: Which deed was most beloved to the Messenger of Allah ﷺ? She said: The one done consistently."]}},"tuhfa":{},"voc":["ahmad",24628],"full":1,"tks":"متفق عليه: رواه البخاري (1132)، ومسلم (741)."},{"num":2773,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: سُئِلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَىُّ الأَعْمَالِ أَحَبُّ إِلَى اللَّهِ؟ قَالَ: أَدْوَمُهَا وَإِنْ قَلَّ. وَقَالَ: اكْلَفُوا مِنَ الأَعْمَالِ مَا تُطِيقُونَ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6465)، ومسلم في صلاة المسافرين (782/216) كلاهما من حديث شعبة، عن سعد بن إبراهيم، أنه سمع أبا سلمة يحدث عن عائشة فذكرت الحديث واللفظ للبخاري، ولم يذكر مسلم الجزء الثاني من الحديث.","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (6465) and Muslim (782); the wording is al-Bukhari’s.","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["‘A’ishah said: The Prophet ﷺ was asked: Which deeds are most beloved to Allah? He said: “Those that are most consistent, even if few.” And he said: “Take on from deeds what you are able to bear.”"]}},"tuhfa":{},"full":1,"rep":[15288],"tks":"متفق عليه: رواه البخاري (6465)، ومسلم (782/216) واللفظ للبخاري."},{"num":2774,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَحْتَجِرُ حَصِيرًا بِاللَّيْلِ فَيُصَلِّي، وَيَبْسُطُهُ بِالنَّهَارِ فَيَجْلِسُ عَلَيْهِ، فَجَعَلَ النَّاسُ يَثُوبُونَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيُصَلُّونَ بِصَلاَتِهِ حَتَّى كَثُرُوا فَأَقْبَلَ فَقَالَ: يَا أَيُّهَا النَّاسُ خُذُوا مِنَ الأَعْمَالِ مَا تُطِيقُونَ، فَإِنَّ اللَّهَ لاَ يَمَلُّ حَتَّى تَمَلُّوا، وَإِنَّ أَحَبَّ الأَعْمَالِ إِلَى اللَّهِ مَا دَامَ وَإِنْ قَلَّ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5861)، ومسلم في صلاة المسافرين (782) كلاهما من حديث عبيدالله، عن سعيد بن أبي سعيد، عن أبي سلمة، عن عائشة فذكرته. واللفظ للبخاري، ولفظ مسلم قريب منه.","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (5861) and Muslim (782); the wording is al-Bukhari’s.","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["The Mother of the Believers ‘A’ishah said: The Prophet ﷺ used to enclose a small area with a mat at night and pray in it, and he would spread it out in the daytime and sit on it. People began coming repeatedly to the Prophet ﷺ and praying along with his prayer until they became many. Then he turned to them and said: “O people, take on from deeds what you are able to do, for Allah does not tire until you tire. And the most beloved deeds to Allah are those that are maintained consistently, even if few.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5861)، ومسلم (782). واللفظ للبخاري."},{"num":2775,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَحَبُّ الْأَعْمَالِ إِلَى اللَّهِ تَعَالَى أَدْوَمُهَا وَإِنْ قَلَّ. قَالَ: وَكَانَتْ عَائِشَةُ إِذَا عَمِلَتِ الْعَمَلَ لَزِمَتْهُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (783/218) من حديث سعد ابن سعيد، أخبرني القاسم بن محمد، عن عائشة فذكره.","grade":"صحيح","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: Muslim (783, no. 218 in that section).","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ said: “The most beloved deeds to Allah Most High are those that are most consistent, even if few.” And ‘A’ishah, when she did a deed, would keep to it (persist in it)."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (783/218)."},{"num":2776,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ قَالَ: مَنْ هَذِهِ؟ قَالَتْ: فُلاَنَةُ، تَذْكُرُ مِنْ صَلاَتِهَا. قَالَ: مَهْ! عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللَّهِ! لاَ يملُّ اللَّهُ حَتَّى تَمَلُّوا . وَكَانَ أحبَّ الدِّينِ إِلَيْهِ مَا دامَ عَلَيْهِ صَاحِبُهُ."],"takhrij":"متفق عليه: رواه البخاري في الإيمان (43)، ومسلم في صلاة المسافرين (785/221) كلاهما من طريق يحيى بن سعيد، عن هشام، قال: أخبرني أبي، عن عائشة فذكرت مثله واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (43) and Muslim (785, no. 221 in that section); the wording is al-Bukhari’s.","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Prophet ﷺ entered upon her while a woman was with her. He said: “Who is this?” She said: “So-and-so,” and she mentioned how much she prayed. He said: “Enough! Stick to what you can manage. By Allah, Allah does not tire until you tire.” And the most beloved religion (practice) to him was that which its companion maintained consistently."]},"buhuth":{"en":["Commentary:","His statement “Allah does not tire until you tire,” and likewise the wording “Allah does not become weary until you become weary,” is not to be understood in its outward, literal sense (i.e., “when you get tired, Allah gets tired”), because tiring and weariness are attributes of deficiency, and Allah is exalted above all attributes of deficiency. Therefore, the scholars said: it is understood to mean that He does not deal with you as one who is tired or weary would—by cutting off from you His reward and recompense. This is like the old expression: “So-and-so does not stop until his opponents stop,” meaning: he does not stop when they stop—i.e., the stopping of the second does not necessitate the stopping of the first. Otherwise, if it meant “he stops when his opponents stop,” then he would have no virtue over anyone else. This meaning is conveyed by al-Nawawi in his commentary on Sahih Muslim, with some rephrasing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (43)، ومسلم (785/221) واللفظ للبخاري."},{"num":2777,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَإِذَا حَبْلٌ مَمْدُودٌ بَيْنَ السَّارِيَتَيْنِ. فَقَالَ: مَا هَذَا الْحَبْلُ. قَالُوا: هَذَا حَبْلٌ لِزَيْنَبَ، فَإِذَا فَتَرَتْ تَعَلَّقَتْ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ، حُلُّوهُ، لِيُصَلِّ أَحَدُكُمْ نَشَاطَهُ، فَإِذَا فَتَرَ فَلْيَقْعُدْ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1150)، ومسلم في صلاة المسافرين (784) كلاهما من حديث عبد الوارث، عن عبد العزيز بن صُهيب، عن أنس فذكره، واللفظ للبخاري. ولفظ مسلم قريب منه إلا أنه قال: كَسِلَتْ أو فترتْ أمْسَكتْ به فقال: حُلُّوه ليصل أحدكم نشاطَه فإذا كسِلَ أو فَتَر قعد وفي رواية فليقعُد .","grade":"متفق عليه","chapter_ar":"باب المداومة على العمل وإن قلَّ","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1150) and Muslim (784); the wording is al-Bukhari’s.","chapter_en":"Persisting in deeds even if they are few.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":37,"content":{"translation":{"en":["Anas ibn Malik said: The Prophet ﷺ entered and saw a rope stretched between two pillars. He said: “What is this rope?” They said: “This is a rope for Zaynab; when she becomes fatigued, she holds onto it.” The Prophet ﷺ said: “No. Untie it. Let one of you pray as long as he is energetic; and when he becomes fatigued, let him sit down.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1150)، ومسلم (784)، واللفظ للبخاري."},{"num":2778,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : أَلَمْ أُخْبرَ أَنَّك تَقُومُ اللَّيْلَ وَتَصُومُ النَّهَارَ؟ قُلْتُ: إِنِّي أَفْعَلُ ذَلِكَ. قَالَ: فإنَّك إِنْ فَعَلْتَ ذَلِكَ هَجَمَتْ عَيْنُكَ، ونَفِهَتْ نَفْسُكَ، وإنَّ لِنَفْسِكَ حقّاً، وَلأَهْلِكَ حقاً، فصُم وَأَفْطِرْ، وقُم ونَمْ ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1153)، ومسلم في الصوم (1159/188) كلاهما عن سفيان، عن عمرو، عن أبي العباس، قال: سمعتُ عبدالله بن عمرو فذكره.","grade":"متفق عليه","chapter_ar":"باب الاقتصاد في العبادة وكراهية التّشديد فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1153) and Muslim (1159, no. 188 in that section).","chapter_en":"Moderation in worship and the disliked nature of excessive strictness in it.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":38,"content":{"translation":{"en":["‘Abdullah ibn ‘Amr ibn al-‘As said: The Messenger of Allah ﷺ said to me: “Have I been informed that you stand (in prayer) at night and fast during the day?” I said: Yes, I do that. He said: “If you do that, your eyes will weaken and your soul will become exhausted. Your self has a right over you, and your family has a right over you. So fast and break your fast; and stand (in prayer) and sleep.”"]},"buhuth":{"en":["Commentary:","“هَجَمَتْ” means: it became weak due to excessive staying up at night.","“نَفِهتْ” means: it became fatigued / worn out."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1153)، ومسلم (1159/188)."},{"num":2779,"demo":false,"sanad":"","matn":["عَنْ مُجَاهِدٍ قَالَ: دَخَلْتُ أَنَا وَيَحْيَى بْنُ جَعْدَةَ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ مِنْ أَصْحَابِ الرَّسُولِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: ذَكَرُوا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْلَاةً لِبَنِي عَبْدِ الْمُطَّلِبِ، فَقَالَ: إِنَّهَا تَقُومُ اللَّيْلَ وَتَصُومُ النَّهَارَ، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَكِنِّي أَنَا أَنَامُ وَأُصَلِّي، وَأَصُومُ وَأُفْطِرُ، فَمَنْ اقْتَدَى بِي فَهُوَ مِنِّي، وَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي، إِنَّ لِكُلِّ عَمَلٍ شِرَّةً ثُمَّ فَتْرَةً، فَمَنْ كَانَتْ فَتْرَتُهُ إِلَى بِدْعَةٍ فَقَدْ ضَلَّ، وَمَنْ كَانَتْ فَتْرَتُهُ إِلَى سُنَّةٍ فَقَدْ اهْتَدَى."],"takhrij":"صحيح: رواه الإمام أحمد (23474) عن يحيى بن سعيد، حدثنا جرير، عن منصور، عن مجاهد قال فذكره.","grade":"صحيح","chapter_ar":"باب الاقتصاد في العبادة وكراهية التّشديد فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Authentic: narrated by Imam Ahmad (23474).","chapter_en":"Moderation in worship and the disliked nature of excessive strictness in it.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":38,"content":{"translation":{"en":["Mujahid said: Yahya ibn Ja‘dah and I entered upon a man from the Ansar, one of the Companions of the Messenger of Allah ﷺ. He said: They mentioned, in the presence of the Messenger of Allah ﷺ, a freedwoman (mawlah) from Banu ‘Abd al-Muttalib, and it was said: She stands (in prayer) at night and fasts in the day. The Messenger of Allah ﷺ said: “But as for me, I sleep and I pray; and I fast and I break my fast. Whoever follows my way is from me, and whoever turns away from my Sunnah is not from me. Indeed every deed has a burst of enthusiasm, then a period of slackness. Whoever’s slackness turns him to an innovation has gone astray, and whoever’s slackness turns him to a Sunnah has been guided.”"]},"buhuth":{"en":["Commentary:","“الشِّرَّة” (with a kasrah) means: intensity, eagerness, and energetic drive."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15695],"tks":"صحيح: رواه الإمام أحمد (23474). والشرة: بالكسرة - الحدة والنشاط."},{"num":2780,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: دَخَلَتْ عَلَيَّ خُوَيْلَةُ بِنْتُ حَكِيمِ بْنِ أُمَيَّةَ بْنِ حَارِثَةَ بْنِ الْأَوْقَصِ السُّلَمِيَّةُ وَكَانَتْ عِنْدَ عُثْمَانَ بْنِ مَظْعُونٍ قَالَتْ: فَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَذَاذَةَ هَيْئَتِهَا، فَقَالَ لِي: يَا عَائِشَةُ، مَا أَبَذَّ هَيْئَةَ خُوَيْلَةَ؟ قَالَتْ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، امْرَأَةٌ لَا زَوْجَ لَهَا يَصُومُ النَّهَارَ، وَيَقُومُ اللَّيْلَ فَهِيَ كَمَنْ لَا زَوْجَ لَهَا، فَتَرَكَتْ نَفْسَهَا وَأَضَاعَتْهَا، قَالَتْ: فَبَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عُثْمَانَ بْنِ مَظْعُونٍ فَجَاءَهُ، فَقَالَ: يَا عُثْمَانُ، أَرَغْبَةً عَنْ سُنَّتِي؟ قَالَ: فَقَالَ: لَا وَاللهِ يَا رَسُولَ اللَّهِ، وَلَكِنْ سُنَّتَكَ أَطْلُبُ، قَالَ: فَإِنِّي أَنَامُ وَأُصَلِّي، وَأَصُومُ وَأُفْطِرُ، وَأَنْكِحُ النِّسَاءَ، فَاتَّقِ اللهَ يَا عُثْمَانُ، فَإِنَّ لِأَهْلِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِضَيْفِكَ عَلَيْكَ حَقًّا، وَإِنَّ لِنَفْسِكَ عَلَيْكَ حَقًّا، فَصُمْ وَأَفْطِرْ، وَصَلِّ وَنَمْ."],"takhrij":"حسن: رواه الإمام أحمد (26308) عن يعقوب (بن إبراهيم بن سعد الزهري) قال: حدثنا أبي، عن ابن إسحاق، قال: حدثني هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب الاقتصاد في العبادة وكراهية التّشديد فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (26308) and Abu Dawud (1369).","chapter_en":"Moderation in worship and the disliked nature of excessive strictness in it.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":38,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: Khawlah bint Hakim ibn Umayyah ibn Harithah ibn al-Awqas al-Sulamiyyah entered upon me—she was married to ‘Uthman ibn Maz‘un. She said: The Messenger of Allah ﷺ saw the poor state of her appearance and said to me: “O ‘A’ishah, why is Khawlah’s appearance so neglected?” I said: “O Messenger of Allah, she is a woman whose husband fasts during the day and stands in prayer at night, so she is like a woman who has no husband; thus she has neglected herself and let herself go.” She said: So the Messenger of Allah ﷺ sent for ‘Uthman ibn Maz‘un, and he came. The Prophet ﷺ said: “O ‘Uthman, are you turning away from my Sunnah?” He said: “No, by Allah, O Messenger of Allah! Rather, I seek your Sunnah.” He said: “As for me: I sleep and I pray; I fast and I break my fast; and I marry women. So fear Allah, O ‘Uthman: your family has a right over you, your guest has a right over you, and your own self has a right over you. So fast and break your fast; and pray and sleep.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (26308)، وأبو داود (1369)."},{"num":2781,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ، قَالَ: لَمَّا كَانَ مِنْ أَمْرِ عُثْمَانَ بْنِ مَظْعُونٍ الَّذِي كَانَ مِنْ تَرْكِ النِّسَاءِ، بَعَثَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا عُثْمَانُ إِنِّي لَمْ أُومَرْ بِالرَّهْبَانِيَّةِ، أَرَغِبْتَ عَنْ سُنَّتِي؟، قَالَ: لَا، يَا رَسُولَ اللَّهِ، قَالَ: إِنَّ مِنْ سُنَّتِي أَنْ أُصَلِّي، وَأَنَام، وَأَصُومَ، وَأَطْعَمَ، وَأَنْكِحَ، وَأُطَلِّقَ، فَمَنْ رَغِبَ عَنْ سُنَّتِي، فَلَيْسَ مِنِّي، يَا عُثْمَانُ، إِنَّ لِأَهْلِكَ عَلَيْكَ حَقًّا، وَلِنَفْسِكَ عَلَيْكَ حَقًّا. قَالَ سَعْدٌ: فَوَاللَّهِ لَقَدْ كَانَ أَجْمَعَ رِجَالٌ مِنَ الْمُسْلِمِينَ عَلَى أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِنْ هُوَ أَقَرَّ عُثْمَانَ عَلَى مَا هُوَ عَلَيْهِ أَنْ نَخْتَصِيَ فَنَتَبَتَّلَ."],"takhrij":"حسن: رواه الدارمي (2173)عن محمد بن يزيد الحزامي، ثنا يونس بن بكير، حدثني ابن إسحاق، حدثني الزهري، عن سعيد بن المسيب، عن سعد بن أبي وقاص فذكره.","grade":"حسن","chapter_ar":"باب الاقتصاد في العبادة وكراهية التّشديد فيها","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Darimi (2173). And it is also reported in the two Sahihs: al-Bukhari (5074) and Muslim (1402) with the wording: “The Messenger of Allah ﷺ rejected celibacy (tabattul) for ‘Uthman ibn Maz‘un; if he had permitted it for him, we would have castrated ourselves.”","chapter_en":"Moderation in worship and the disliked nature of excessive strictness in it.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":38,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas said: When the matter of ‘Uthman ibn Maz‘un occurred—he was among those who had avoided women—the Messenger of Allah ﷺ sent for him and said: “O ‘Uthman, I have not been commanded with monasticism. Have you turned away from my Sunnah?” He said: “No, O Messenger of Allah.” He said: “Indeed, from my Sunnah is that I pray and I sleep; I fast and I eat (i.e., I break my fast); I marry and I divorce. Whoever turns away from my Sunnah is not from me. O ‘Uthman, your family has a right over you, and your own self has a right over you.” Sa‘d said: By Allah, a group of Muslim men had gathered with the intention that if the Messenger of Allah ﷺ were to approve ‘Uthman in what he was doing, we would castrate ourselves and live in celibacy."]}},"tuhfa":{},"full":1,"dr":1,"rep":[6183,13634],"tks":"حسن: رواه الدارمي (2173). والحديث مخرج في الصحيحين البخاري (5074)، ومسلم (1402)."},{"num":2782,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنَّ فُلَانًا يُصَلِّي بِاللَّيْلِ، فَإِذَا أَصْبَحَ سَرَقَ، قَالَ: إِنَّهُ سَيَنْهَاهُ مَا تَقُولُ."],"takhrij":"صحيح: رواه الإمام أحمد (9778) حدثنا وكيع، حدثنا الأعمش، قال: أُرَى أبا صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء أن الصلاة تنهى عن الفحشاء والمنكر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Ahmad (9778), al-Bazzar in Kashf al-Astar (720), and Ibn Hibban (2560).","chapter_en":"What has been narrated that prayer prevents indecency and wrongdoing.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":39,"content":{"translation":{"en":["Abu Hurayrah said: A man came to the Prophet ﷺ and said: “So-and-so prays at night, but when morning comes he steals.” He ﷺ said: “Indeed, what you mention will (eventually) prevent him.”"]},"intro":{"ar":["قال تعالى: ( إِنَّ الصَّلَوٰةَ تَنْهَى عَنِ ٱلْفَحْشَاءِ وَالْمُنكَرِ) [سورة العنكبوت: ٤٥]."],"en":["Allah Most High said: “Indeed, prayer restrains from indecency and wrongdoing.” (Al-‘Ankabut 29:45)"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12984],"tks":"صحيح: رواه الإمام أحمد (9778)، والبزار في كشف الأستار (720)، وابن حبان (2560)."},{"num":2783,"demo":false,"sanad":"","matn":["عَنْ جابر قَالَ: قَالَ رجلٌ للنّبيّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إنّ فُلَانًا يُصَلِّي، فَإِذَا أَصْبَحَ سَرَقَ! قَالَ: سَيَنْهَاهُ مَا تَقُولُ ."],"takhrij":"حسن: رواه البزار \"كشف الأستار\" (722) عن محمد بن موسى الحرشي، ثنا زياد بن عبدالله، عن الأعمش، عن أبي صالح، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب ما جاء أن الصلاة تنهى عن الفحشاء والمنكر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by al-Bazzar in Kashf al-Astar (722), and Ibn Abi al-Dunya in al-Tahajjud (382).","chapter_en":"What has been narrated that prayer prevents indecency and wrongdoing.","part_en":"Prayer (Ṣalāh)","group_ar":"مجموع أبواب صلاة الليل","group_en":"Combined Sections of the Night Prayer.","part_no":9,"group_no":16,"chapter_no":39,"content":{"translation":{"en":["Jabir said: A man said to the Prophet ﷺ: “So-and-so prays, but when morning comes he steals!” He ﷺ said: “What you mention will (eventually) prevent him.”"]},"buhuth":{"en":["Commentary:","Regarding his statement, “What you mention will prevent him,” Ibn Hibban said: “The Arabs sometimes attribute an action to the action itself, just as they attribute it to the doer. The Prophet ﷺ meant that when prayer is truly established—in its beginning and its completion—then the one who prays will keep away from prohibited matters along with it, as Allah Most High says: ‘Indeed, prayer restrains from indecency and wrongdoing.’” End quote."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار “كشف الأستار” (722)، وابن أبي الدنيا في “التهجد” (382)."},{"num":2784,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُحيريز أنَّ رَجُلاً مِنْ بَنِي كِنَانَةَ يُدْعَى المخْدَجِيَّ سَمِعَ رَجُلاً بِالشَّامِ يكنَّى أَبَا مُحَمَّدٍ يَقُولُ: إِنَّ الْوِتْرَ وَاجِبٌ. فَقَالَ المُخدَجِيُّ: فَرُحتُ إِلَى عُبَادَةَ بْنِ الصَّامِتِ، فاعترضتُ لَهُ وَهُوَ رائح إِلَى الْمَسْجِدِ. فَأَخْبَرْتُهُ بِالَّذِي قَالَ أَبُو مُحَمَّدٍ، فَقَالَ عُبَادَةُ: كَذَبَ أَبُو مُحَمَّدٍ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: خمسُ صَلَوَاتٍ كتبهنَّ اللَّهُ عزوجلَّ عَلَى الْعِبَادِ، فَمَنْ جَاءَ بِهِنَّ لَمْ يُضيّعْ مِنهنَّ شَيْئًا اسْتِخْفَافًا بِحَقِّهِنَّ كَانَ لَهُ عِنْدَ اللَّهِ عَهْدٌ أَنْ يُدْخِلَهُ الْجَنَّةَ. وَمَنْ لَمْ يَأْتِ بهِنَّ فَلَيْسَ لَهُ عِنْدَ اللَّهِ عَهْدٌ. إِنْ شَاءَ عذَّبه، وَإِنْ شَاءَ أدْخَلَه الْجَنَّةَ ."],"takhrij":"صحيح: رواه مالك في صلاة الليل (14) عن يحيى بن سعيد، عن محمد ابن يحيى بن حَبَّان، عن ابن محيريز فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تأكيد الوتر وأنه سنة وليس بواجب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Malik (14), Abu Dawud (1420), al-Nasa’i (461), and Ibn Majah (1401).","chapter_en":"What has been narrated about emphasizing Witr, and that it is Sunnah and not obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":1,"content":{"translation":{"en":["Ibn Muhayriz narrated that a man from Banu Kinanah, called al-Mukhdaji, heard a man in al-Sham whose kunyah was Abu Muhammad saying: “Witr is obligatory.” Al-Mukhdaji said: So I went to ‘Ubadah ibn al-Samit and intercepted him while he was heading to the mosque. I informed him of what Abu Muhammad had said. ‘Ubadah said: “Abu Muhammad has lied. I heard the Messenger of Allah ﷺ say: ‘Five prayers Allah, Mighty and Majestic, has prescribed upon the servants. Whoever comes with them and does not neglect anything of them out of belittling their due right—he will have a covenant with Allah that He will admit him into Paradise. And whoever does not come with them has no covenant with Allah: if He wills, He will punish him, and if He wills, He will admit him into Paradise.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (14) وأبو داود ( 1420)، والنسائي (461) وابن ماجه (1401)."},{"num":2785,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ وِتر يحبُّ الوتر ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6410)، ومسلم في الذكر (2677) كلاهما من حديث سفيان بن عيينة، عن أبي الزناد، عن الأعرج، عن أبي هريرة عن النبي صلى الله عليه وسلم وأول الحديث: لله تسعةٌ وتسعون اسماً من حفظها دخل الجنة .","grade":"متفق عليه","chapter_ar":"باب ما جاء في تأكيد الوتر وأنه سنة وليس بواجب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (6410) and Muslim (2677).","chapter_en":"What has been narrated about emphasizing Witr, and that it is Sunnah and not obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":1,"content":{"translation":{"en":["Abu Hurayrah narrated that the Prophet ﷺ said: “Indeed, Allah is One (Witr) and He loves Witr.”"]},"buhuth":{"en":["And at the beginning of the hadith: “Allah has ninety-nine names; whoever preserves them enters Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6410)، ومسلم (2677)."},{"num":2786,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَهْلَ الْقُرْآنِ أَوْتِرُوا، فَإِنَّ اللَّهَ وِتْرٌ يُحِبُّ الْوِتْرَ."],"takhrij":"حسن: رواه أبو داود (1416) عن إبراهيم بن موسى، أخبرنا عيسى، عن زكريا، عن أبي إسحاق، عن عاصم، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تأكيد الوتر وأنه سنة وليس بواجب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1416), al-Tirmidhi (453) who graded it hasan, al-Nasa’i (1675), and Ibn Majah (1169).","chapter_en":"What has been narrated about emphasizing Witr, and that it is Sunnah and not obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":1,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ said: “O people of the Qur’an, pray Witr, for Allah is Witr and He loves Witr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1416)، والترمذي (453) وحسنه، والنسائي (1675)، وابن ماجه ( 1169)."},{"num":2787,"demo":false,"sanad":"","matn":["عَنْ أَبِي تَمِيمٍ الْجَيْشَانِيِّ، أَنَّ عَمْرَو بْنَ الْعَاصِ، خَطَبَ النَّاسَ يَوْمَ الْجُمُعَةِ فَقَالَ: إِنَّ أَبَا بَصْرَةَ حَدَّثَنِي أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ اللَّهَ زَادَكُمْ صَلَاةً، وَهِيَ الْوِتْرُ، فَصَلُّوهَا فِيمَا بَيْنَ صَلَاةِ الْعِشَاءِ إِلَى صَلَاةِ الْفَجْرِ."],"takhrij":"صحيح: رواه أحمد (23851)، والطبراني في الكبير (2/313، 2168) كلاهما من حديث عبدالله بن المبارك، أخبرنا سعيد بن يزيد، حدثني ابن هُبَيرة، عن أبي تميم الجيشاني فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تأكيد الوتر وأنه سنة وليس بواجب","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Ahmad (23851) and al-Tabarani in al-Kabir (2168).","chapter_en":"What has been narrated about emphasizing Witr, and that it is Sunnah and not obligatory","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":1,"content":{"translation":{"en":["Abu Tamim al-Jayshani narrated that ‘Amr ibn al-‘As delivered a Friday sermon and said: Abu Basrah told me that the Prophet ﷺ said: “Indeed, Allah has added for you a prayer—Witr—so pray it between the ‘Isha’ prayer and the Fajr prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد ( 23851)، والطبراني في الكبير (2168، 2/313)."},{"num":2788,"demo":false,"sanad":"","matn":["عَنْ سَعِيدِ بْنِ يَسَارٍ أَنَّهُ قَالَ:  كُنْتُ أَسِيرُ مَعَ ابْنِ عُمَرَ بِطَرِيقِ مَكَّةَ. قَالَ سَعِيدٌ: فَلَمَّا خَشِيتُ الصُّبْحَ، نَزَلْتُ فَأَوْتَرْتُ، ثُمَّ أَدْرَكْتُهُ، فَقَالَ لِي ابْنُ عُمَرَ: أَيْنَ كُنْتَ؟ فَقُلْتُ لَهُ: خَشِيتُ الْفَجْرَ فَنَزَلْتُ فَأَوْتَرْتُ. فَقَالَ عَبْدُ اللَّهِ: أَلَيْسَ لَكَ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُسْوَةٌ! فَقُلْتُ: بَلَى. وَاللهِ. قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ عَلَى الْبَعِيرِ."],"takhrij":"متفق عليه: رواه مالك في صلاة الليل (15) عن أبي بكر بن عمر، عن سعيد بن يسار به مثله. ورواه البخاري في الوتر (999) عن إسماعيل بن أبي أويس، ومسلم في صلاة المسافرين (700/36) عن يحيى بن يحيى، كلاهما عن مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب أداء صلاة الوتر على الدابة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: Malik (15), al-Bukhari (999), and Muslim (700).","chapter_en":"Performing the Witr prayer on a riding animal","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":2,"content":{"translation":{"en":["Sa‘id ibn Yasar said: I was traveling with ‘Abdullah ibn ‘Umar on the road to Makkah. Sa‘id said: When I feared the approach of dawn, I got down and prayed Witr, then I caught up with him. ‘Abdullah ibn ‘Umar said to me: “Where were you?” I said: “I feared (the arrival of) Fajr, so I got down and prayed Witr.” He said: “Do you not have an example in the Messenger of Allah ﷺ?” I said: “Yes, by Allah.” He said: “Indeed, the Messenger of Allah ﷺ used to pray Witr on the camel.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (15) والبخاري (999)، ومسلم (700/36)."},{"num":2789,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَأَنَا رَاقِدَةٌ مُعْتَرِضَةً عَلَى فِرَاشِهِ، فَإِذَا أَرَادَ أَنْ يُوتِرَ أَيْقَظَنِي فَأَوْتَرْتُ."],"takhrij":"متفق عليه: رواه البخاري في الوتر (997) عن مسدد، قال: حدثنا يحيى، قال: حدثنا هشام، قال: حدثني أبي، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب إيقاظ النبي ﷺ أهلَهُ للوتر","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (997) and Muslim (744).","chapter_en":"The Prophet ﷺ waking his family for Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":3,"content":{"translation":{"en":["‘A’ishah, the wife of the Prophet ﷺ, said: The Prophet ﷺ would pray while I was lying down, stretched across his bed. When he wished to pray Witr, he would wake me, and I would pray Witr."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2534],"tks":"متفق عليه: رواه البخاري (997)، ومسلم (744)."},{"num":2790,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اجْعَلُوا آخِرَ صَلاَتِكُمْ بِاللَّيْلِ وِتْرًا ."],"takhrij":"متفق عليه: رواه البخاري في الوتر (998) ومسلم في صلاة المسافرين (751/151) كلاهما من حديث يحيى بن سعيد، عن عبيدالله، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب ليجعل آخر صلاته وترا","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (998) and Muslim (751).","chapter_en":"Making the last of one’s night prayer Witr","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":4,"content":{"translation":{"en":["Ibn ‘Umar narrated from the Prophet ﷺ: “Make the last of your night prayer Witr.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (998) ومسلم (751/151)."},{"num":2791,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ طَلْقٍ، قَالَ: زَارَنَا طَلْقُ بْنُ عَلِيٍّ فِي يَوْمٍ مِنْ رَمَضَانَ، وَأَمْسَى عِنْدَنَا وَأَفْطَرَ، ثُمَّ قَامَ بِنَا تِلْكَ اللَّيْلَةَ وَأَوْتَرَ بِنَا، ثُمَّ انْحَدَرَ إِلَى مَسْجِدِهِ فَصَلَّى بِأَصْحَابِهِ، حَتَّى إِذَا بَقِيَ الْوِتْرُ قَدَّمَ رَجُلاً فَقَالَ: أَوْتِرْ بِأَصْحَابِكَ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ وِتْرَانِ فِي لَيْلَةٍ."],"takhrij":"حسن: رواه أبو داود (1439)، والترمذي (470)، والنسائي (1679) كلهم من طريق ملازم بن عمرو، حدثنا عبدالله بن بدر، عن قيس بن طلق فذكره، واللفظ لأبي داود، وعندهما مثله غير أنهما لم يذكرا القصة. قال الترمذي: حسن غريب.","grade":"حسن","chapter_ar":"باب النهي عن وترين في ليلة","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (1439) (wording is his), al-Tirmidhi (470) who graded it hasan, and al-Nasa’i (1679).","chapter_en":"Prohibition of two Witr prayers in one night","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":5,"content":{"translation":{"en":["Qays ibn Talq said: Talq ibn ‘Ali visited us on a day of Ramadan, spent the evening with us and broke his fast, then led us in prayer that night and prayed Witr with us. Then he went down to his mosque and prayed with his companions until only Witr remained. He put forward a man and said: “Pray Witr for your companions, for I heard the Messenger of Allah ﷺ say: ‘There are not two Witr prayers in one night.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1439)، والترمذي (470) وحسنه، والنسائي (1679)، واللفظ لأبي داود."},{"num":2792,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  مِنْ كُلِّ اللَّيْلِ قَدْ أَوْتَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ.","وفي رواية: من كلِّ اللَّيلِ قد أوتر رسولُ الله صلى الله عليه وسلم من أوَّلِ اللَّيل، وأوسطه، وآخره. فانتهى وِتْرُه إلى السَّحَر."],"takhrij":"متفق عليه: رواه البخاري في كتاب الوتر (996)، ومسلم في صلاة المسافرين (745) كلاهما من حديث الأعمش قال: حدثني مسلم (وهو أبو الضُحى) عن مسروق، عن عائشة فذكرته واللفظ لهما.","grade":"متفق عليه","chapter_ar":"باب في ساعات الوتر أول الليل وأوسطه وآخره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (996) and Muslim (745).","chapter_en":"The times for Witr: the beginning, middle, and end of the night","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":6,"content":{"translation":{"en":["‘A’ishah said: The Messenger of Allah ﷺ prayed Witr during all parts of the night, and his Witr ultimately ended up being in the pre-dawn (sahar) time. In another narration: The Messenger of Allah ﷺ prayed Witr in every part of the night—at its beginning, its middle, and its end—then his Witr ended up being in the pre-dawn time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (996)، ومسلم (745)."},{"num":2793,"demo":false,"sanad":"","matn":["عَنْ غُضَيْفِ بْنِ الْحَارِثِ، قَالَ: قُلْتُ لِعَائِشَةَ: أَرَأَيْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَغْتَسِلُ مِنَ الْجَنَابَةِ فِي أَوَّلِ اللَّيْلِ أَوْ فِي آخِرِهِ؟ قَالَتْ: رُبَّمَا اغْتَسَلَ فِي أَوَّلِ اللَّيْلِ، وَرُبَّمَا اغْتَسَلَ فِي آخِرِهِ. قُلْتُ: اللَّهُ أَكْبَرُ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الأَمْرِ سَعَةً. قُلْتُ: أَرَأَيْتِ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُوتِرُ أَوَّلَ اللَّيْلِ أَمْ فِي آخِرِهِ؟ قَالَتْ: رُبَّمَا أَوْتَرَ فِي أَوَّلِ اللَّيْلِ، وَرُبَّمَا أَوْتَرَ فِي آخِرِهِ. قُلْتُ: اللَّهُ أَكْبَرُ الْحَمْدُ لِلَّهِ الَّذِي جَعَلَ فِي الأَمْرِ سَعَةً."],"takhrij":"حسن: رواه أبو داود (226) (226) واللفظ له، والنسائي (1/125، 222، 223) مقتصراً على الجزء الأول كلاهما من طريق عُبادة ابن نُسَي، عن غُضيف بن الحارث فذكر الحديث.","grade":"حسن","chapter_ar":"باب في ساعات الوتر أول الليل وأوسطه وآخره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Abu Dawud (226) (wording is his) and al-Nasa’i (222, 223).","chapter_en":"The times for Witr: the beginning, middle, and end of the night","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":6,"content":{"translation":{"en":["Ghudayf ibn al-Harith said: I said to ‘A’ishah: “Did the Messenger of Allah ﷺ perform ghusl from janabah at the beginning of the night or at its end?” She said: “Sometimes he would bathe at the beginning of the night, and sometimes he would bathe at the end of it.” I said: “Allahu Akbar—praise be to Allah who has placed ease in this matter.” I then said: “Did the Messenger of Allah ﷺ pray Witr at the beginning of the night or at its end?” She said: “Sometimes he would pray Witr at the beginning of the night, and sometimes he would pray Witr at its end.” I said: “Allahu Akbar—praise be to Allah who has placed ease in this matter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (226) (1/152-153) واللفظ له، والنسائي (1/125)."},{"num":2794,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ قَالَ: مِنْ كُلِّ اللَّيْلِ قَدْ أَوْتَرَ رَسُولُ اللَّهِ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. مِنْ أَوَّلِهِ، وَأَوْسَطِهِ، وَانْتَهَى وِتْرُهُ إِلَى السَّحَرِ."],"takhrij":"حسن: رواه ابن ماجه (1186) من حديث شعبة عن أبي إسحاق، عن عاصم بن ضَمْرة، عن علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب في ساعات الوتر أول الليل وأوسطه وآخره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1186); and Ibn Khuzaymah authenticated it (1080).","chapter_en":"The times for Witr: the beginning, middle, and end of the night","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":6,"content":{"translation":{"en":["‘Ali ibn Abi Talib said: The Messenger of Allah ﷺ prayed Witr in every part of the night—at its beginning and its middle—and his Witr ended up being in the pre-dawn (sahar) time."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1186) وصححه ابن خزيمة ( 1080)."},{"num":2795,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ خَافَ أَنْ لَا يَقُومَ مِنْ آخِرِ اللَّيْلِ فَلْيُوتِرْ أَوَّلَهُ، وَمَنْ طَمِعَ أَنْ يَقُومَ آخِرَهُ فَلْيُوتِرْ آخِرَ اللَّيْلِ، فَإِنَّ صَلَاةَ آخِرِ اللَّيْلِ مَشْهُودَةٌ، وَذَلِكَ أَفْضَلُ.","وفي رواية: أَيُّكُمْ خَافَ أَنْ لَا يَقُومَ مِنْ آخِرِ اللَّيْلِ فَلْيُوتِرْ، ثُمَّ لْيَرْقُدْ، وَمَنْ وَثِقَ بِقِيَامٍ مِنَ اللَّيْلِ فَلْيُوتِرْ مِنْ آخِرِهِ. فَإِنَّ قِرَاءَةَ آخِرِ اللَّيْلِ مَحْضُورَةٌ، وَذَلِكَ أَفْضَلُ .."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (755) عن أبي بكر بن أبي شيبة، حدثنا حفص وأبو معاوية، عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الوقت المختار للوتر هو آخر الليل لمن قوي عليه وتقديمه لغيره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Muslim (755), and the second wording is also in Muslim.","chapter_en":"The preferred time for Witr is the end of the night for whoever is able; and bringing it forward for others","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Jabir said: The Messenger of Allah ﷺ said: “Whoever fears that he will not get up at the end of the night, let him pray Witr at its beginning; and whoever hopes to get up at its end, let him pray Witr at the end of the night—for the prayer of the end of the night is witnessed, and that is better.” In another narration: “Whoever fears that he will not get up at the end of the night, let him pray Witr, then sleep; and whoever is confident he will get up at night, let him pray Witr at its end. For the recitation at the end of the night is attended, and that is better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (755)، والرواية الثانية عند مسلم أيضا."},{"num":2796,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لأَبِي بَكْرٍ: مَتَى تُوتِرُ قَالَ: أُوتِرُ مِنْ أَوَّلِ اللَّيْلِ. وَقَالَ لِعُمَرَ: مَتَى تُوتِرُ. قَالَ: آخِرَ اللَّيْلِ. فَقَالَ لأَبِي بَكْرٍ: أَخَذَ هَذَا بِالْحَزْمِ. وَقَالَ لِعُمَرَ: أَخَذَ هَذَا بِالْقُوَّةِ."],"takhrij":"صحيح: رواه أبو داود (1434) قال: حدثنا محمد بن أحمد بن أبي خلف، حدثنا أبو زكريا [ يحيى بن إسحاق السَّيْلَحيني] حدثنا حماد بن سلمة، عن ثابت، عن عبدالله بن رباح، عن أبي قتادة فذكره.","grade":"صحيح","chapter_ar":"باب الوقت المختار للوتر هو آخر الليل لمن قوي عليه وتقديمه لغيره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Sahih: narrated by Abu Dawud (1434), Ibn Khuzaymah (1084); also transmitted by al-Hakim (301/1) and al-Bayhaqi (35/3).","chapter_en":"The preferred time for Witr is the end of the night for whoever is able; and bringing it forward for others","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Abu Qatadah narrated that the Prophet ﷺ said to Abu Bakr: “When do you pray Witr?” He said: “I pray Witr at the beginning of the night.” And he said to ‘Umar: “When do you pray Witr?” He said: “At the end of the night.” So he said to Abu Bakr: “This one has taken it with caution (prudence),” and he said to ‘Umar: “This one has taken it with strength.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1434)، وابن خزيمة (1084)، وعنه الحاكم (1120)، والبيهقي (4839)."},{"num":2797,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لأَبِي بَكْرٍ: أَىَّ حِينٍ تُوتِرُ؟ قَالَ: أَوَّلَ اللَّيْلِ بَعْدَ الْعَتَمَةِ. قَالَ: فَأَنْتَ يَا عُمَرُ. فَقَالَ: آخِرَ اللَّيْلِ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَّا أَنْتَ يَا أَبَا بَكْرٍ فَأَخَذْتَ بِالْوُثْقَى، وَأَمَّا أَنْتَ يَا عُمَرُ فَأَخَذْتَ بِالْقُوَّةِ."],"takhrij":"حسن: رواه ابن ماجه (1202) قال: حدثنا أبو داود سليمان بن تَوْبة، قال: حدثنا يحيى بن أبي بكير، قال: حدثنا زائدة، عن عبدالله بن محمد بن عقيل، عن جابر بن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب الوقت المختار للوتر هو آخر الليل لمن قوي عليه وتقديمه لغيره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ibn Majah (1202), Ahmad (14323), Abu Dawud al-Tayalisi (1776), and Abu Ya‘la (1821).","chapter_en":"The preferred time for Witr is the end of the night for whoever is able; and bringing it forward for others","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Jabir ibn ‘Abdullah said: The Messenger of Allah ﷺ said to Abu Bakr: “At what time do you pray Witr?” He said: “At the beginning of the night after ‘Isha’.” He said: “And you, ‘Umar?” He said: “At the end of the night.” So the Prophet ﷺ said: “As for you, Abu Bakr, you have held to the firmest handhold; and as for you, ‘Umar, you have held to strength.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (1202)، وأحمد (14323)، وأبو داود الطيالسي (1776 )، وأبو يعلى (1821)."},{"num":2798,"demo":false,"sanad":"","matn":["عن سعد بن أبي وَقَّاصٍ أَنَّهُ كَانَ يُصَلِّي الْعِشَاءَ الْآخِرَةَ فِي مَسْجِدِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ يُوتِرُ بِوَاحِدَةٍ، لَا يَزِيدُ عَلَيْهَا، قَالَ: فَيُقَالُ لَهُ: أَتُوتِرُ بِوَاحِدَةٍ، لَا تَزِيدُ عَلَيْهَا يَا أَبَا إِسْحَاقَ؟ فَيَقُولُ: نَعَمْ، إِنِّي سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الَّذِي لَا يَنَامُ حَتَّى يُوتِرَ حَازِمٌ."],"takhrij":"حسن: رواه أحمد (1461) عن يعقوب، حدثنا أبي، عن ابن إسحاق، حدثني محمد بن عبد الرحمن بن عبد الله بن الحصين، أنه حدّث عن سعد بن أبي وقاص فذكره.","grade":"حسن","chapter_ar":"باب الوقت المختار للوتر هو آخر الليل لمن قوي عليه وتقديمه لغيره","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Hasan: narrated by Ahmad (1461).","chapter_en":"The preferred time for Witr is the end of the night for whoever is able; and bringing it forward for others","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":7,"content":{"translation":{"en":["Sa‘d ibn Abi Waqqas would pray the ‘Isha’ prayer in the mosque of the Messenger of Allah ﷺ, then pray Witr with one rak‘ah, not adding anything beyond it. It would be said to him: “Do you pray Witr with one (rak‘ah) and not add to it, O Abu Ishaq?” He would say: “Yes. Indeed I heard the Messenger of Allah ﷺ say: ‘Whoever does not sleep until he has prayed Witr is resolute (firm/decisive).’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد ( 1461)."},{"num":2799,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: أَوْصَانِي خَلِيلِي بِثَلاَثٍ لاَ أَدَعُهُنَّ حَتَّى أَمُوتَ، صَوْمِ ثَلاَثَةِ أَيَّامٍ مِنْ كُلِّ شَهْرٍ، وَصَلاَةِ الضُّحَى، وَنَوْمٍ عَلَى وِتْرٍ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1178)، ومسلم في صلاة المسافرين (721) كلاهما من طريق شعبة، حدثنا عباس الجُريري -وهو ابن فَرُّوخ، عن أبي عثمان النهدي، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في أداء صلاة الوتر قبل النوم","chapter_ur":"","part_ar":"كتاب الصلاة","part_ur":"","takhrij_en":"Agreed upon: al-Bukhari (1178) and Muslim (721).","chapter_en":"What has been narrated about performing Witr before sleeping","part_en":"Prayer (Ṣalāh)","group_ar":"جموع أبواب صلاة الوتر","group_en":"Combined chapters on the Witr prayer","part_no":9,"group_no":17,"chapter_no":8,"content":{"translation":{"en":["Abu Hurayrah said: “My close friend (the Prophet ﷺ) advised me with three things which I will not leave until I die: fasting three days of every month, praying Duha, and sleeping after praying Witr.”"]}},"tuhfa":{},"full":1,"rep":[2929],"tks":"متفق عليه: رواه البخاري (1178)، ومسلم (721)."}]);